        TpmAlgIdConstants.TPM_ALG_MGF1,
        TpmAlgIdConstants.TPM_ALG_KDF1_SP800_56A,
        TpmAlgIdConstants.TPM_ALG_KDF1_SP800_108,
        TpmAlgIdConstants.TPM_ALG_HKDF
