        //Handle area: @authHandle (the entity whose authValue is being replaced). Table 205: @authHandle is
        //TPM2_HierarchyChangeAuth()'s sole handle, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

