        //while the parameter area is transformed in place.
        bool isPasswordArm = isSingleSession && sessionHandle.IsPasswordSession;
        TpmParameterArea parameterArea = TpmParameterArea.Empty;
        Tpm2bAuth slotCredential = Tpm2bAuth.Empty;
        Tpm2bNonce slotNonce = Tpm2bNonce.Empty;
        Tpm2bAuth decryptCredential = Tpm2bAuth.Empty;
        Tpm2bNonce decryptNonce = Tpm2bNonce.Empty;
        try
        {
            parameterArea = isPasswordArm ? TpmParameterArea.Empty : TpmParameterArea.Create(rawParameterAreaOctets, pool);
            slotCredential = Tpm2bAuth.Create(hmac, pool);
            slotNonce = sessionHandle.IsPasswordSession ? Tpm2bNonce.Empty : Tpm2bNonce.Create(nonceCaller, pool);
            decryptCredential = isSingleSession ? Tpm2bAuth.Empty : Tpm2bAuth.Create(decryptHmac, pool);
            decryptNonce = isSingleSession ? Tpm2bNonce.Empty : Tpm2bNonce.Create(decryptNonceCaller, pool);

            input = isPasswordArm
                ? new TpmHierarchyChangeAuthRequested(TpmiRhHierarchyAuth.FromValue(authHandle), slotCredential, Tpm2bAuth.Create(newAuth, pool))
                : new TpmHierarchyChangeAuthOverSessionRequested(
                    TpmiRhHierarchyAuth.FromValue(authHandle), sessionHandle, slotNonce, sessionAttributes, slotCredential,
                    !isSingleSession, decryptHandle, decryptNonce, decryptAttributes, decryptCredential,
                    parameterArea, Tpm2bAuth.Create(newAuth, pool));
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            decryptNonce.Dispose();
            decryptCredential.Dispose();
            slotNonce.Dispose();
            slotCredential.Dispose();
            parameterArea.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_NV_Certify()</c> is authorized and takes three handles, two of which require authorization: the
    /// wire layout after the header is handle area (@signHandle, @authHandle, nvIndex — Part 3, clause 31.16.2,
    /// Table 271), then parameters (qualifyingData as TPM2B_DATA, inScheme as TPMT_SIG_SCHEME, size as UINT16,
    /// offset as UINT16).
    /// </summary>
    /// <remarks>
    /// <para>
    /// The authorization area carries two required sessions in handle order — session 1 authorizes signHandle,
    /// session 2 authorizes authHandle (Table 271 gives both Auth Role USER) — optionally followed by a third,
    /// companion slot that authorizes nothing (Part 1, clause 15.6.1, Table 12). Each is read generically with
    /// <c>TryReadCommandSessionSpans</c>, the span-returning shape a parse that rents its own carriers needs, and
    /// the slot count comes from the declared authorization size rather than being assumed. A
    /// <c>TPMS_AUTH_COMMAND</c>'s wire layout is the same for a password session and a real one, so the parsed
    /// sessionHandles and the presence of a companion decide the form: two LONE <c>TPM_RS_PW</c> handles make
    /// this <see cref="TpmNvCertifyRequested"/>, and any other combination — including two password slots
    /// alongside a companion — makes it <see cref="TpmNvCertifyOverSessionRequested"/>.
    /// </para>
    /// <para>
    /// The slots are decided independently rather than as a pair, because mixed forms are legal wire: nothing in
    /// Table 271 couples one handle's authorization mechanism to the other's. Every field of every session is
    /// captured rather than consumed-and-discarded — the parser records what arrived and the transition decides
    /// what each slot may authorize.
    /// </para>
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented sign-slot credential, authorizing-slot credential, companion-slot credential, all three slots' caller nonces, and qualifying-data carriers transfers to the constructed request input, whose consuming transition (password) or continuation (session) releases them or transfers them into the NV-certify action and its response-session entries, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseNvCertify(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: @signHandle, @authHandle, nvIndex — each field's own shortfall designated to its own index
        //(Table 271; a buffer wide enough for an earlier handle alone designates the next handle, not the area's
        //first slot).
        if(!TryReadHandle(ref reader, 0, out uint signHandleRaw, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 1, out uint authHandleRaw, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 2, out uint nvIndexRaw, out malformedResponseCode))
        {
            return false;
        }

        TpmiDhObject signHandle = TpmiDhObject.FromValue(signHandleRaw);
        TpmiRhNvAuth authHandle = TpmiRhNvAuth.FromValue(authHandleRaw);
        TpmiRhNvIndex nvIndex = TpmiRhNvIndex.FromValue(nvIndexRaw);

        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //Session 1 authorizes signHandle — the signing key's own USER-role authorization, verified by the
        //transitions on both arms (the all-password form compares the captured password against the signing
        //key's retained authValue exactly as TPM2_Certify()/TPM2_Quote()/TPM2_GetTime() do; the session form
        //compares a password slot inline or verifies a real command HMAC after the Name hop). Every field is
        //captured: a real session here owes a genuine response entry.
        if(!TryReadCommandSessionSpans(ref reader, sessionIndex: 0, out TpmiShAuthSession signSessionHandle, out ReadOnlySpan<byte> signNonceCaller, out TpmaSession signSessionAttributes, out ReadOnlySpan<byte> signHmac, out malformedResponseCode))
        {
            return false;
        }

        //Session 2 authorizes authHandle; this is the slot whose authorization is actually evaluated, over a
        //password compare or a command HMAC depending on the handle it names.
        if(!TryReadCommandSessionSpans(ref reader, sessionIndex: 1, out TpmiShAuthSession authSessionHandle, out ReadOnlySpan<byte> authNonceCaller, out TpmaSession authSessionAttributes, out ReadOnlySpan<byte> authHmac, out malformedResponseCode))
        {
            return false;
        }

        //Octets left inside the declared authorization size after the last REQUIRED slot are a companion slot
        //(Part 1, clause 15.6.1, Table 12, position after the authorization sessions).
        bool hasCompanion = reader.Consumed - sessionsStart != (int)authorizationSize;
        TpmiShAuthSession companionSessionHandle = TpmiShAuthSession.FromValue(0);
        TpmaSession companionSessionAttributes = default;

        //The two span locals are declared scoped so they can receive slices that alias the command buffer the
        //by-reference reader points into: without it the compiler must assume a span written through an out
        //parameter of a ref-taking method could outlive that buffer.
        scoped ReadOnlySpan<byte> companionNonceCaller = ReadOnlySpan<byte>.Empty;
        scoped ReadOnlySpan<byte> companionHmac = ReadOnlySpan<byte>.Empty;
        if(hasCompanion
            && !TryReadCommandSessionSpans(ref reader, sessionIndex: 2, out companionSessionHandle, out companionNonceCaller, out companionSessionAttributes, out companionHmac, out malformedResponseCode))
        {
            return false;
        }

        if(!TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //NV_Certify's entire parameter set (qualifyingData ‖ inScheme ‖ size ‖ offset) is every octet left after
        //the authorization area — captured verbatim, before any field is decoded, as the session arm's cpHash
        //parameter term (Part 1, clause 15.7 equation 15).
        ReadOnlySpan<byte> rawParameterAreaOctets = reader.PeekBytes(reader.Remaining);

        //Which arm the area belongs to is settled before the parameters are read, because it decides how
        //qualifyingData may be treated: two LONE TPM_RS_PW slots are the all-password form the password arm
        //serves, while any other combination — a mixed one, or two password slots alongside a companion — is the
        //session arm, whose response owes at least one real entry.
        bool isAllPassword = signSessionHandle.IsPasswordSession && authSessionHandle.IsPasswordSession && !hasCompanion;

        //Parameter: qualifyingData (TPM2B_DATA) — the caller nonce echoed into the attestation, and the first
        //command parameter, which is the one a decrypt session protects (Part 1, clause 15.4). On the session
        //form these octets may be CIPHERTEXT, so the parse only steps over the field's framing to reach the
        //parameters behind it and the decrypt step supplies the plaintext (Part 3, clause 5.7 precedes clause
        //5.8); decoding here would also be futile, since a separately copied field is not updated by the in-place
        //transform of the captured area. On the password form no session can protect it, so it is read as a span
        //over the command buffer whose owning carrier is rented as this parse's last act.
        scoped ReadOnlySpan<byte> qualifyingData = ReadOnlySpan<byte>.Empty;
        if(isAllPassword)
        {
            if(!TryReadTpm2bSpan(ref reader, out qualifyingData, out malformedResponseCode))
            {
                //Table 271: qualifyingData is TPM2_NV_Certify()'s first parameter, index 0.
                malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

                return false;
            }

            //TPM2B_DATA is bounded by sizeof(TPMT_HA) (Part 2, clause 10.3.3, Table 91), so a wider value is
            //TPM_RC_SIZE here, before any carrier is rented; the consuming transition's own bound check stands as
            //the fail-closed backstop. The session form's bound is applied to the RECOVERED value instead, which
            //is the only form of it TPM2B_DATA is about. qualifyingData is this command's first parameter (P1).
            if(qualifyingData.Length > Tpm2bData.MaxSize)
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

                return false;
            }
        }
        else if(!TrySkipTpm2b(ref reader, out malformedResponseCode))
        {
            //Table 271: qualifyingData is TPM2_NV_Certify()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: inScheme (TPMT_SIG_SCHEME) — scheme selector (UINT16), plus a hashAlg (UINT16) detail pair
        //only when the selector is not TPM_ALG_NULL (TPM 2.0 Library Part 2, clause 11.2.1.4/11.2.1.5, Tables
        //182/183: the "null" row of Table 182 carries an empty Type column against selector TPM_ALG_NULL, so
        //Table 183's [scheme]details is absent entirely for it). It sits behind the first parameter and so is
        //never encrypted, which is why it is decoded on both arms alike. Table 271: inScheme is the second
        //parameter, index 1.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

            return false;
        }

        TpmiAlgSigScheme signatureScheme = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        TpmiAlgHash schemeHashAlg;
        if(signatureScheme.IsNull)
        {
            schemeHashAlg = TpmiAlgHash.FromValue(TpmAlgIdConstants.TPM_ALG_NULL);
        }
        else
        {
            if(reader.Remaining < sizeof(ushort))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

                return false;
            }

            schemeHashAlg = TpmiAlgHash.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        }

        //Parameters: size (UINT16) then offset (UINT16), each field's own shortfall designated to its own
        //index (Table 271) — size is the third parameter, index 2, and offset the fourth, index 3.
        if(!TryReadUInt16Parameter(ref reader, 2, out ushort size, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadUInt16Parameter(ref reader, 3, out ushort offset, out malformedResponseCode))
        {
            return false;
        }

        //offset is the final parameter; no octets may follow it — the reference's own generic trailing-octets
        //check, not attributable to a single field. Stays bare.
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //Either form's owned pooled carriers are rented here, the parse's last act after every wire check has
        //passed, so no refused parse ever creates one.
        Tpm2bAuth suppliedSignCredential = Tpm2bAuth.Empty;
        Tpm2bAuth suppliedAuthorizingCredential = Tpm2bAuth.Empty;
        Tpm2bNonce signNonce = Tpm2bNonce.Empty;
        Tpm2bNonce authorizingNonce = Tpm2bNonce.Empty;
        Tpm2bAuth companionCredential = Tpm2bAuth.Empty;
        Tpm2bNonce companionNonce = Tpm2bNonce.Empty;
        TpmParameterArea parameterArea = TpmParameterArea.Empty;
        try
        {
            suppliedSignCredential = Tpm2bAuth.Create(signHmac, pool);
            suppliedAuthorizingCredential = Tpm2bAuth.Create(authHmac, pool);

            //Only the session arm retains the slots' caller nonces, so only it rents them — and it rents BOTH,
            //because a mixed area's TPM_RS_PW slot still owes its own response entry (Part 1, clause 15.6.1).
            signNonce = isAllPassword ? Tpm2bNonce.Empty : Tpm2bNonce.Create(signNonceCaller, pool);
            authorizingNonce = isAllPassword ? Tpm2bNonce.Empty : Tpm2bNonce.Create(authNonceCaller, pool);
            companionCredential = hasCompanion ? Tpm2bAuth.Create(companionHmac, pool) : Tpm2bAuth.Empty;
            companionNonce = hasCompanion ? Tpm2bNonce.Create(companionNonceCaller, pool) : Tpm2bNonce.Empty;
            parameterArea = isAllPassword ? TpmParameterArea.Empty : TpmParameterArea.Create(rawParameterAreaOctets, pool);
            input = isAllPassword
                ? new TpmNvCertifyRequested(
                    signHandle, authHandle, nvIndex, suppliedSignCredential, suppliedAuthorizingCredential,
                    Tpm2bData.Create(qualifyingData, pool), signatureScheme, schemeHashAlg, size, offset)
                : new TpmNvCertifyOverSessionRequested(
                    signHandle, authHandle, nvIndex,
                    signSessionHandle, signNonce, signSessionAttributes, suppliedSignCredential,
                    authSessionHandle, authorizingNonce, authSessionAttributes, suppliedAuthorizingCredential,
                    Tpm2bData.Empty, signatureScheme, schemeHashAlg, size, offset, parameterArea,
                    hasCompanion, companionSessionHandle, companionNonce, companionSessionAttributes, companionCredential, Tpm2bName.Empty);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            parameterArea.Dispose();
            companionNonce.Dispose();
            companionCredential.Dispose();
            authorizingNonce.Dispose();
            signNonce.Dispose();
            suppliedAuthorizingCredential.Dispose();
            suppliedSignCredential.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_VerifySignature()</c> authorizes no entity — keyHandle needs no authorization at all (Part 3,
    /// clause 20.2) — so its wire layout after the header is: handle area (keyHandle, 1 handle), then, on
    /// <c>TPM_ST_SESSIONS</c>, the shared no-authorization mechanism's authorization area (Table 116's tag
    /// cell: "TPM_ST_SESSIONS if an audit or decrypt session is present"; deprecated in this revision, still
    /// mandatory — admitted like its siblings); on <c>TPM_ST_NO_SESSIONS</c>, parameters (digest as
    /// TPM2B_DIGEST, signature as TPMT_SIGNATURE: sigAlg selecting the ECDSA r/s TPM2B pair, the single RSA
    /// TPM2B signature, or the unsized TPMT_HA the HMAC member carries) with no authorization area at all. A
    /// decrypt companion protects <c>digest</c> (<see cref="TpmNoAuthSessionShape"/>'s row for this command).
    /// </summary>
    /// <remarks>
    /// digest is read fail-closed inline (<see cref="TryReadTpm2bSpan"/> plus an explicit <see cref="Tpm2bDigest.MaxSize"/>
    /// bound), and the <c>sigAlg</c> selector gate that answers <c>TPM_RC_SCHEME</c> stays inline here too — only
    /// the post-gate <c>TPMT_SIGNATURE</c> body (hashAlg plus the selected union member) is shared with every
    /// other signature-consuming parse, through <see cref="TryParseTpmtSignatureBody"/>: the same fail-closed
    /// wire checks, ending in a pooled <see cref="TpmtSignature"/> whose octets ride the Spec carrier alone,
    /// never through an intermediate heap copy.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented digest and signature carriers transfers to the constructed request input, whose consuming transition hands them to the verification action for the effect to release, and whose refusing arms dispose them through the input's own Dispose.")]
    private static bool TryParseVerifySignature(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            return TryParseNoAuthOverSessions(ref reader, TpmCcConstants.TPM_CC_VerifySignature, pool, out input, out malformedResponseCode);
        }

        //Handle area: keyHandle (the key whose public part verifies the signature; no authorization area on
        //this TPM_ST_NO_SESSIONS form). Table 116: keyHandle is TPM2_VerifySignature()'s sole handle, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint keyHandle = reader.ReadUInt32();

        //keyHandle is TPMI_DH_OBJECT (Table 116, Auth Index: None); a type octet outside the transient/persistent
        //range is a handle-area syntax failure, judged before any parameter or session (TPM 2.0 Library Part 3,
        //clause 5.4, step 1; Part 2, clause 9.3, Table 49).
        if(!IsWithinDhObjectRange(keyHandle))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        //Parameter: digest (TPM2B_DIGEST) — the digest the signature is claimed to be over. Bound-first against
        //sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.2, Table 90), matching the shared TPMT_SIGNATURE
        //body this parse delegates to below — a digest that is both over-bound and truncated answers
        //TPM_RC_SIZE, never TPM_RC_INSUFFICIENT.
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> digest, out malformedResponseCode))
        {
            //Table 116: digest is TPM2_VerifySignature()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: signature (TPMT_SIGNATURE) — sigAlg (TPMI_ALG_SIG_SCHEME) selects the union member; the
        //admitted set is the asymmetric schemes plus TPM_ALG_HMAC, Table 115's digest-verifying row for this
        //command (clause 20.2.1's symmetric-key sentence). Table 116: signature is the second parameter, index 1.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

            return false;
        }

        TpmiAlgSigScheme sigAlg = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        if(sigAlg.Value is not (TpmAlgIdConstants.TPM_ALG_ECDSA or TpmAlgIdConstants.TPM_ALG_RSASSA or TpmAlgIdConstants.TPM_ALG_RSAPSS or TpmAlgIdConstants.TPM_ALG_HMAC))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SCHEME, 1);

            return false;
        }

        //The post-gate TPMT_SIGNATURE body (hashAlg plus the sigAlg-selected member) is the shared helper's job;
        //it rents the pooled signature carrier as its own last act.
        if(!TryParseTpmtSignatureBody(ref reader, sigAlg, pool, out TpmtSignature? signature, out malformedResponseCode))
        {
            //Table 116: signature is TPM2_VerifySignature()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //signature is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            signature.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled digest carrier is rented here, the parse's last act after every wire check has
        //passed; the signature carrier was already rented earlier, inside TryParseTpmtSignatureBody, so a
        //failing digest rent here must release it too or that earlier rental is orphaned.
        try
        {
            input = new TpmVerifySignatureRequested(
                TpmiDhObject.FromValue(keyHandle), Tpm2bDigest.Create(digest, pool), sigAlg, TpmiAlgHash.FromValue(signature.Signature.HashAlgorithm), signature);
        }
        catch
        {
            signature.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_VerifyDigestSignature()</c>'s <c>keyHandle</c> carries no <c>@</c> (Auth Index None, a public-key
    /// operation), so its wire layout after the header is: handle area (1 handle), then, on
    /// <c>TPM_ST_SESSIONS</c>, the shared no-authorization mechanism's authorization area (Table 120's tag
    /// cell: "TPM_ST_SESSIONS if an audit or decrypt session is present"); on <c>TPM_ST_NO_SESSIONS</c>,
    /// parameters (context as TPM2B_SIGNATURE_CTX, digest as TPM2B_DIGEST, signature as TPMT_SIGNATURE) with no
    /// authorization area at all. A decrypt companion protects <c>context</c> — the first command parameter,
    /// NOT <c>digest</c> — matching <see cref="VerifyDigestSignatureInput"/>'s own
    /// <c>FirstCommandParameterIsEncryptable</c> declaration (<see cref="TpmNoAuthSessionShape"/>'s row for this
    /// command).
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented context and signature carriers transfers to the constructed request input, whose consuming transition disposes the context once its emptiness is confirmed and transfers the signature into the verification action, and whose refusing arms dispose them both through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseVerifyDigestSignature(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            return TryParseNoAuthOverSessions(ref reader, TpmCcConstants.TPM_CC_VerifyDigestSignature, pool, out input, out malformedResponseCode);
        }

        //Handle area: keyHandle (the key whose public part verifies the signature; no authorization area on
        //this TPM_ST_NO_SESSIONS form). Table 120: keyHandle is TPM2_VerifyDigestSignature()'s sole handle,
        //index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint keyHandle = reader.ReadUInt32();

        //keyHandle is TPMI_DH_OBJECT (Table 120, Auth Index: None); a type octet outside the transient/persistent
        //range is a handle-area syntax failure, judged before any parameter or session (TPM 2.0 Library Part 3,
        //clause 5.4, step 1; Part 2, clause 9.3, Table 49).
        if(!IsWithinDhObjectRange(keyHandle))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        //Parameter: context (TPM2B_SIGNATURE_CTX) — bound-first against MaxSize (255, TPM_RC_SIZE), matching
        //the structure's own Parse throw (TPM 2.0 Library Part 2, clause 11.3.8). Table 120: context is the
        //first parameter, index 0.
        Tpm2bSignatureCtx context;
        try
        {
            context = Tpm2bSignatureCtx.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        //Parameter: digest (TPM2B_DIGEST) — bound-first against sizeof(TPMU_HA), matching the shared TPMT_SIGNATURE
        //body this parse delegates to below — a digest that is both over-bound and truncated answers
        //TPM_RC_SIZE, never TPM_RC_INSUFFICIENT.
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> digest, out malformedResponseCode))
        {
            context.Dispose();

            //Table 120: digest is TPM2_VerifyDigestSignature()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //Parameter: signature (TPMT_SIGNATURE) — sigAlg (TPMI_ALG_SIG_SCHEME) selects the union member. Table
        //120: signature is the third parameter, index 2.
        if(reader.Remaining < sizeof(ushort))
        {
            context.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 2);

            return false;
        }

        TpmiAlgSigScheme sigAlg = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        if(sigAlg.Value is not (TpmAlgIdConstants.TPM_ALG_ECDSA or TpmAlgIdConstants.TPM_ALG_RSASSA or TpmAlgIdConstants.TPM_ALG_RSAPSS))
        {
            context.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SCHEME, 2);

            return false;
        }

        //The post-gate TPMT_SIGNATURE body (hashAlg plus the sigAlg-selected member) is the shared helper's job;
        //it rents the pooled signature carrier as its own last act.
        if(!TryParseTpmtSignatureBody(ref reader, sigAlg, pool, out TpmtSignature? signature, out malformedResponseCode))
        {
            context.Dispose();

            //Table 120: signature is TPM2_VerifyDigestSignature()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        //signature is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            context.Dispose();
            signature.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled digest carrier is rented as its own statement, ahead of the request's own
        //construction — a rent inline in the constructor argument list would let its failure orphan the
        //context and signature carriers already rented earlier without a catch clause covering them, so it
        //gets its own guarded statement instead, matching TryParseSignDigest's shape.
        Tpm2bDigest digestCarrier = Tpm2bDigest.Empty;
        try
        {
            digestCarrier = Tpm2bDigest.Create(digest, pool);
            input = new TpmVerifyDigestSignatureRequested(
                TpmiDhObject.FromValue(keyHandle), context, digestCarrier, sigAlg, TpmiAlgHash.FromValue(signature.Signature.HashAlgorithm), signature);
        }
        catch
        {
            digestCarrier.Dispose();
            context.Dispose();
            signature.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_Encapsulate()</c>'s <c>keyHandle</c> carries no <c>@</c> (Auth Index None, a public-key
    /// operation — "The TPM does not verify the objectAttributes of the key"), so its wire layout after the
    /// header is: handle area (1 handle), then, on <c>TPM_ST_SESSIONS</c>, the shared no-authorization
    /// mechanism's authorization area (Table 60's tag cell: "TPM_ST_SESSIONS if an audit or encrypt session is
    /// present"); on <c>TPM_ST_NO_SESSIONS</c>, no parameters at all — Table 60 carries none — with no
    /// authorization area either. An encrypt companion returns the response's <c>sharedSecret</c> (Table 61's
    /// FIRST field) encrypted (<see cref="TpmNoAuthSessionShape"/>'s row for this command); the host-side codec
    /// declares <c>responseFirstParameterIsEncryptable: true</c> to match.
    /// </summary>
    private static bool TryParseEncapsulate(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            return TryParseNoAuthOverSessions(ref reader, TpmCcConstants.TPM_CC_Encapsulate, pool, out input, out malformedResponseCode);
        }

        //Handle area: keyHandle (the KEM key; no authorization area on this TPM_ST_NO_SESSIONS form — Table 60,
        //Auth Index None). Table 60: keyHandle is TPM2_Encapsulate()'s sole handle, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint keyHandle = reader.ReadUInt32();

        //keyHandle is TPMI_DH_OBJECT (Table 60, Auth Index: None); a type octet outside the transient/persistent
        //range is a handle-area syntax failure, judged before any parameter or session (TPM 2.0 Library Part 3,
        //clause 5.4, step 1; Part 2, clause 9.3, Table 49).
        if(!IsWithinDhObjectRange(keyHandle))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        //Table 60 carries no parameters at all; no octets may follow the handle area (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmEncapsulateRequested(TpmiDhObject.FromValue(keyHandle));

        return true;
    }

    /// <summary>
    /// <c>TPM2_Decapsulate()</c> is authorized, so its wire layout after the header is: handle area
    /// (@keyHandle, 1 handle), authorization area (a single password session), then the one parameter,
    /// ciphertext (<c>TPM2B_KEM_CIPHERTEXT</c>). Tag pinned <c>TPM_ST_SESSIONS</c> (Table 62) — the same
    /// key-slot authorization shape <see cref="TryParseSignDigest"/> parses.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented key-password and ciphertext carriers transfers to the constructed request input, whose consuming transition releases the password once the key-slot compare has consumed it and transfers the ciphertext into the decapsulation action, and whose refusing arms dispose them both through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseDecapsulate(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: @keyHandle (the KEM key). Table 62: @keyHandle is TPM2_Decapsulate()'s sole handle,
        //index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint keyHandle = reader.ReadUInt32();

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        //Parameter: ciphertext (TPM2B_KEM_CIPHERTEXT) — bound-first against MaxSize (1568, TPM_RC_SIZE),
        //truncation TPM_RC_INSUFFICIENT, matching the structure's own Parse throw and the bound-before-truncation
        //order. Table 62: ciphertext is TPM2_Decapsulate()'s sole parameter, index 0.
        Tpm2bKemCiphertext ciphertext;
        try
        {
            ciphertext = Tpm2bKemCiphertext.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        //ciphertext is the final parameter; no octets may follow it — the reference's own generic
        //trailing-octets check, not attributable to a single field. Stays bare.
        if(reader.Remaining != 0)
        {
            ciphertext.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled password carrier is rented as the parse's last act, so no refused parse ever
        //creates one.
        Tpm2bAuth suppliedKeyPassword = Tpm2bAuth.Empty;
        try
        {
            suppliedKeyPassword = Tpm2bAuth.Create(suppliedAuth, pool);
            input = new TpmDecapsulateRequested(TpmiDhObject.FromValue(keyHandle), suppliedKeyPassword, ciphertext);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            suppliedKeyPassword.Dispose();
            ciphertext.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_MakeCredential()</c> takes no authorization (it uses only the credential key's public area), so
    /// its wire layout after the header is: handle area (1 handle, the credential key), then, on
    /// <c>TPM_ST_SESSIONS</c>, the shared no-authorization mechanism's authorization area despite this command
    /// having no <c>@</c>-authorized handle at all — the mechanism is precisely for a handle that carries no
    /// authorization (Table 28's tag cell: "TPM_ST_SESSIONS if an audit, encrypt, or decrypt session is
    /// present"); on <c>TPM_ST_NO_SESSIONS</c>, parameters (credential as TPM2B_DIGEST, objectName as
    /// TPM2B_NAME) with no authorization area at all (TPM 2.0 Library Part 3, clause 12.6).
    /// </summary>
    /// <remarks>
    /// The credential is copied into durable model memory and the bound Name rides an owned pooled
    /// <c>TPM2B_NAME</c> carrier rented as the parse's last act, so no refused parse ever creates one. A
    /// decrypt companion protects <c>credential</c> and an encrypt companion protects the response's
    /// <c>credentialBlob</c> (<see cref="TpmNoAuthSessionShape"/>'s row for this command).
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented object-Name carrier transfers to the constructed request input, whose consuming transition transfers it into the wrap action for the effect to release, and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParseMakeCredential(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            return TryParseNoAuthOverSessions(ref reader, TpmCcConstants.TPM_CC_MakeCredential, pool, out input, out malformedResponseCode);
        }

        //Handle area: handle (the credential key; no authorization area on this TPM_ST_NO_SESSIONS form). Table
        //28: handle is TPM2_MakeCredential()'s sole handle, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint keyHandle = reader.ReadUInt32();

        //keyHandle is TPMI_DH_OBJECT (Table 28, Auth Index: None); a type octet outside the transient/persistent
        //range is a handle-area syntax failure, judged before any parameter or session (TPM 2.0 Library Part 3,
        //clause 5.4, step 1; Part 2, clause 9.3, Table 49).
        if(!IsWithinDhObjectRange(keyHandle))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        //Parameter: credential (TPM2B_DIGEST) — the secret to wrap.
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> credential, out malformedResponseCode))
        {
            //Table 28: credential is TPM2_MakeCredential()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_DIGEST buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.2,
        //Table 90), so the wire bound is answered here, ahead of the rental whose Create refuses the same bound
        //by throwing. Table 28: credential is the first parameter, index 0.
        if(credential.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameter: objectName (TPM2B_NAME) — the Name the credential is bound to (the attestation key's Name).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> objectName, out malformedResponseCode))
        {
            //Table 28: objectName is TPM2_MakeCredential()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //A TPM2B_NAME's content is bounded by sizeof(TPMU_NAME) — a 2-octet nameAlg plus the widest digest
        //(TPM 2.0 Library Part 2, clause 10.4.3, Table 105; the reference enforces it in TPM2B_NAME_Unmarshal),
        //so an oversized Name is refused here rather than reaching the carrier's own throwing bound. Table 28:
        //objectName is the second parameter, index 1.
        if(objectName.Length > Tpm2bName.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        //objectName is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled credential and Name carriers are rented here, the parse's last act after every wire
        //check has passed, so no refused parse ever creates one.
        Tpm2bDigest credentialSecret = Tpm2bDigest.Empty;
        try
        {
            credentialSecret = Tpm2bDigest.Create(credential, pool);
            input = new TpmMakeCredentialRequested(TpmiDhObject.FromValue(keyHandle), credentialSecret, Tpm2bName.Create(objectName, pool));
        }
        catch
        {
            //This carrier's only owner is this frame until the request adopts it, so a failing later rent
            //must release it or the pinned rental is orphaned.
            credentialSecret.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_ActivateCredential()</c> is authorized and takes two handles, so its wire layout after the header
    /// is: handle area (@activateHandle — the attestation key, ADMIN role; @keyHandle — the credential key, USER
    /// role — 2 handles, both require auth), authorization area, then parameters (credentialBlob as
    /// TPM2B_ID_OBJECT, secret as TPM2B_ENCRYPTED_SECRET). It is framed with <c>TPM_ST_SESSIONS</c> (TPM 2.0
    /// Library Part 3, clause 12.5). The blob and secret are copied into durable model memory.
    /// </summary>
    /// <remarks>
    /// The authorization area is read slot by slot: session 1 (@activateHandle, ADMIN role) stays password-only
    /// via <c>TryReadPasswordSessionBody</c> — no template this simulator builds sets adminWithPolicy, so a
    /// non-password session there keeps failing <c>TPM_RC_AUTH_TYPE</c>, today's behavior. Session 2 (@keyHandle,
    /// USER role) is read generically via <c>TryReadCommandSessionSpans</c>, mirroring
    /// <c>TryParseUnseal</c>'s first session: a standard endorsement key's authPolicy makes TPM_RS_PW
    /// insufficient there, so the wire form (not just the transition) must be able to carry a policy session
    /// handle. The transition, not the parser, resolves whether that handle names a real policy session and
    /// whether it satisfies the key's authPolicy.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented credentialBlob, secret, activate-password (and, for the plain form, key-password) carriers transfers to the constructed request input, whose consuming transition releases them once the per-slot compares have consumed them and the recovery action has been built, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases the earlier ones in the enclosing catch before rethrowing.")]
    private static bool TryParseActivateCredential(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: @activateHandle (the object the credential is bound to) then @keyHandle (the credential
        //key), each field's own shortfall designated to its own index (Table 26; a buffer wide enough for
        //@activateHandle alone designates @keyHandle, not @activateHandle).
        if(!TryReadHandle(ref reader, 0, out uint activateHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 1, out uint keyHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //Session 1 authorizes @activateHandle (ADMIN role); password-only. The supplied value is
        //retained for the transition's activate-slot compare in both downstream forms.
        if(!TryReadPasswordSessionBody(ref reader, out ReadOnlySpan<byte> activatePassword, out malformedResponseCode))
        {
            return false;
        }

        //Session 2 authorizes @keyHandle (USER role): read generically so a policy session handle parses, then let
        //the transition resolve it (password vs. policy) exactly as Unseal's over-sessions form does. The hmac
        //field is retained for the plain TPM_RS_PW form's key-slot compare; a real policy session's command-side
        //HMAC verification remains out of scope here (only GetRandom-over-session and Unseal are chartered), so
        //the over-session form does not carry it.
        if(!TryReadCommandSessionSpans(ref reader, sessionIndex: 1, out TpmiShAuthSession keyPolicySession, out _, out TpmaSession keyPolicyAttributes, out ReadOnlySpan<byte> keyHmac, out malformedResponseCode))
        {
            return false;
        }

        //A third session in the area (for example an attempted encrypt session) is not modelled for this command;
        //TryEndAuthArea rejects the surplus naturally with TPM_RC_AUTHSIZE.
        if(!TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //ActivateCredential's entire parameter set (credentialBlob ‖ secret) is every octet left after the
        //authorization area — captured verbatim, before either field is decoded, as the term the key slot's
        //policy session is judged against when it latched a cpHash or pHash binding (Part 1, clause 15.7
        //equation 15; Part 4 CompareParametersHash); unused by the password form.
        ReadOnlySpan<byte> rawParameterAreaOctets = reader.PeekBytes(reader.Remaining);

        //Parameter: credentialBlob (TPM2B_ID_OBJECT) — the credential from TPM2_MakeCredential(), bound-checked
        //ahead of the remaining-octets check (Table 245), so a declared size that is BOTH over-bound and
        //truncated answers TPM_RC_SIZE rather than TPM_RC_INSUFFICIENT.
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bIdObject.MaxSize, out ReadOnlySpan<byte> credentialBlobSpan, out malformedResponseCode))
        {
            //Table 26: credentialBlob is TPM2_ActivateCredential()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: secret (TPM2B_ENCRYPTED_SECRET) — the encrypted seed from TPM2_MakeCredential(), same
        //bound-before-truncation ordering (Table 224).
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bEncryptedSecret.MaxSize, out ReadOnlySpan<byte> secretSpan, out malformedResponseCode))
        {
            //Table 26: secret is TPM2_ActivateCredential()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //secret is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //credentialBlob and secret are rented as the parse's last act, alongside the password carrier(s), so
        //no refused parse ever creates one.
        Tpm2bIdObject credentialBlob = Tpm2bIdObject.Empty;
        Tpm2bEncryptedSecret secret = Tpm2bEncryptedSecret.Empty;
        try
        {
            credentialBlob = Tpm2bIdObject.Create(credentialBlobSpan, pool);
            secret = Tpm2bEncryptedSecret.Create(secretSpan, pool);

            if(keyPolicySession.IsPasswordSession)
            {
                Tpm2bAuth suppliedActivatePassword = Tpm2bAuth.Empty;
                try
                {
                    suppliedActivatePassword = Tpm2bAuth.Create(activatePassword, pool);
                    input = new TpmActivateCredentialRequested(TpmiDhObject.FromValue(activateHandle), suppliedActivatePassword, TpmiDhObject.FromValue(keyHandle), Tpm2bAuth.Create(keyHmac, pool), credentialBlob, secret);
                }
                catch
                {
                    //This carrier's only owner is this frame until the request adopts it, so a failing later rent
                    //must release it or the pinned rental is orphaned.
                    suppliedActivatePassword.Dispose();
                    throw;
                }
            }
            else
            {
                Tpm2bAuth suppliedActivatePassword = Tpm2bAuth.Empty;
                try
                {
                    suppliedActivatePassword = Tpm2bAuth.Create(activatePassword, pool);
                    input = new TpmActivateCredentialOverSessionRequested(
                        TpmiDhObject.FromValue(activateHandle), suppliedActivatePassword, TpmiDhObject.FromValue(keyHandle), credentialBlob, secret,
                        keyPolicySession, keyPolicyAttributes, TpmParameterArea.Create(rawParameterAreaOctets, pool));
                }
                catch
                {
                    //This carrier's only owner is this frame until the request adopts it, so a failing later rent
                    //must release it or the pinned rental is orphaned.
                    suppliedActivatePassword.Dispose();
                    throw;
                }
            }
        }
        catch
        {
            //credentialBlob and secret are this frame's only owner until whichever branch's request adopts
            //them, so a failing later rent (the password branch's own carrier, or the over-session branch's
            //activate password) must release both or the pinned rentals are orphaned.
            secret.Dispose();
            credentialBlob.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PCR_Read()</c>'s parameter core (TPM 2.0 Library Part 3, clause 22.4, Table 134): its whole
    /// parameter area is a single <c>TPML_PCR_SELECTION</c>, shared by the plain <c>TPM_ST_NO_SESSIONS</c> form
    /// (<see cref="TryParsePcrRead"/>) and the no-authorization wrapper's parameter step
    /// (<see cref="TryParseNoAuthParameters"/>).
    /// </summary>
    /// <remarks>
    /// The selection is decoded into an owned pooled carrier that both drives the PCR gather in the transition
    /// and is written back verbatim into the response's <c>pcrSelectionOut</c> — the <c>TPM2_Quote()</c> idiom
    /// (<see cref="TryParseQuote"/>): a by-value probe through <see cref="TrySkipPcrSelection"/> answers a
    /// truncated or over-bound list before any rental, then <see cref="TpmlPcrSelection.Parse"/> decodes it.
    /// The probe also stands in for the trailing-octet check every parameter core's plain wrapper otherwise
    /// applies after the fact (Part 3, clause 5.8.2, Table 2): it already refuses a non-empty remainder before
    /// any carrier is rented, so <see cref="TryParsePcrRead"/> adds no second check of its own.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented selection carrier transfers to the constructed request input, whose consuming transition transfers it into the response; a refused parse never rents one.")]
    private static bool TryParsePcrReadParameters(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        TpmReader probe = reader;
        if(!TrySkipPcrSelection(ref probe, out malformedResponseCode))
        {
            //Table 134: pcrSelectionIn is TPM2_PCR_Read()'s sole parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(probe.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        TpmlPcrSelection pcrSelection;
        try
        {
            pcrSelection = TpmlPcrSelection.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            //A list naming more banks than HASH_COUNT selections is out of the structure's declared bound
            //(Part 2, clause 10.8.7, Table 128: #TPM_RC_SIZE). Table 134: pcrSelectionIn is TPM2_PCR_Read()'s
            //sole parameter, index 0 — the probe above already refuses this width, so this is the fail-closed
            //backstop rather than the answering layer.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            //A selection whose sizeofSelect lies outside PCR_SELECT_MIN..PCR_SELECT_MAX is out of the member's
            //own declared bounds (Part 2, clause 10.5.2, Table 107: #TPM_RC_VALUE). The probe above already
            //refuses that width, so this is the fail-closed backstop rather than the answering layer. Table 134:
            //pcrSelectionIn is TPM2_PCR_Read()'s sole parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        input = new TpmPcrReadRequested(pcrSelection);

        return true;
    }

    /// <summary>
    /// <c>TPM2_PCR_Read()</c>'s <c>TPM_ST_SESSIONS</c>/<c>TPM_ST_NO_SESSIONS</c> fork (TPM 2.0 Library Part 3,
    /// clause 22.4, Table 134's tag cell: "TPM_ST_SESSIONS if an audit session is present"): the
    /// no-authorization wrapper over an audit companion, or the plain form's parameter core
    /// (<see cref="TryParsePcrReadParameters"/>), which already answers a trailing octet <c>TPM_RC_SIZE</c> on
    /// its own.
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="tag">The command's wire tag.</param>
    /// <param name="pool">The memory pool the parsed carriers are rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParsePcrRead(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            return TryParseNoAuthOverSessions(ref reader, TpmCcConstants.TPM_CC_PCR_Read, pool, out input, out malformedResponseCode);
        }

        return TryParsePcrReadParameters(ref reader, pool, out input, out malformedResponseCode);
    }

    /// <summary>
    /// Reads a <c>TPMI_DH_PCR</c> handle (TPM 2.0 Library Part 2, clause 9.7, Table 53): <c>PCR_FIRST</c> is
    /// zero, so the range check is the upper bound alone — this simulator's <c>PCR_LAST</c> is register 23
    /// (<see cref="PcrBankState.PcrCount"/>), and any other value, a higher index or a handle of another type
    /// alike, is <c>#TPM_RC_VALUE</c> (Part 3, clause 22.8.1's note). <c>TPM_RH_NULL</c> is admitted only for
    /// the <c>+</c> form (Tables 95, 130 and 132; not Table 142).
    /// </summary>
    /// <param name="reader">The reader positioned at the handle.</param>
    /// <param name="isNullAdmitted">Whether the table carries <c>TPMI_DH_PCR+</c>.</param>
    /// <param name="pcrHandle">The parsed handle.</param>
    /// <param name="malformedResponseCode">The refusal when the handle is not admitted.</param>
    /// <returns><see langword="true"/> when a handle was read and admitted.</returns>
    private static bool TryParsePcrHandle(ref TpmReader reader, bool isNullAdmitted, out TpmiDhPcr pcrHandle, out TpmRcConstants malformedResponseCode)
    {
        pcrHandle = default;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        //Every caller (TPM2_PCR_Extend() Table 130, TPM2_PCR_Event() Table 132, TPM2_PCR_Reset() Table 142,
        //TPM2_EventSequenceComplete() Table 95) places pcrHandle as its FIRST handle, index 0, invariant across
        //every caller, so it is encoded here rather than at each call site.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint value = reader.ReadUInt32();
        if(isNullAdmitted && value == (uint)TpmRh.TPM_RH_NULL)
        {
            pcrHandle = TpmiDhPcr.FromValue(value);

            return true;
        }

        if(value >= PcrBankState.PcrCount)
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        pcrHandle = TpmiDhPcr.FromValue(value);

        return true;
    }

    /// <summary>
    /// Walks a <c>TPML_DIGEST_VALUES</c> by value, before any rental, answering each of its wire rules with the
    /// code Part 2 names: a <c>count</c> above the simulator's implemented-hash count → <c>TPM_RC_SIZE</c>
    /// (Table 127's <c>{:HASH_COUNT}</c>; Part 4 <c>TPML_DIGEST_VALUES_Unmarshal</c>); an entry whose
    /// <c>hashAlg</c> is not a hash the simulator implements — a non-hash identifier, <c>TPM_ALG_NULL</c> (no
    /// <c>+</c> in this list), or a TCG hash outside SHA-1/256/384/512 — → <c>TPM_RC_HASH</c> (Part 3, clause
    /// 22.2.1: "If the TPM unmarshals the hashAlg of a list entry and the unmarshaled value is not a hash
    /// algorithm implemented on the TPM, the TPM shall return TPM_RC_HASH"); a digest shorter than its
    /// algorithm's width → <c>TPM_RC_INSUFFICIENT</c>. <see cref="TpmlDigestValues.Parse"/> then decodes the
    /// validated octets.
    /// </summary>
    /// <param name="reader">A by-value copy of the reader positioned at the list.</param>
    /// <param name="malformedResponseCode">The refusal when the list is not admitted.</param>
    /// <returns><see langword="true"/> when the whole list is well-formed for this simulator.</returns>
    private static bool TrySkipDigestValues(ref TpmReader reader, out TpmRcConstants malformedResponseCode)
    {
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        //This probe's only caller is TryParsePcrExtend (Table 130: TPM2_PCR_Extend()'s sole parameter, digests,
        //index 0), so every failure here is parameter 1.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint count = reader.ReadUInt32();
        if(count > (uint)ImplementedHashAlgorithms.Length)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        for(uint i = 0; i < count; i++)
        {
            if(reader.Remaining < sizeof(ushort))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

                return false;
            }

            var hashAlg = TpmiAlgHash.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
            if(!TpmLifecycleTransitions.IsImplementedSequenceHash(hashAlg))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_HASH, 0);

                return false;
            }

            int digestSize = hashAlg.DigestSize!.Value;
            if(reader.Remaining < digestSize)
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

                return false;
            }

            _ = reader.ReadBytes(digestSize);
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PCR_Extend()</c> authorizes <c>@pcrHandle</c> (TPM 2.0 Library Part 3, clause 22.2, Table 130), so
    /// its wire layout after the header is: handle area (<c>@pcrHandle</c> as <c>TPMI_DH_PCR+</c>), authorization
    /// area (one <c>TPM_RS_PW</c> slot), parameter area (<c>digests</c> as <c>TPML_DIGEST_VALUES</c>). The list
    /// is probed by value (<see cref="TrySkipDigestValues"/>) before the rentals, so every refusal — including
    /// clause 22.2.1's <c>TPM_RC_HASH</c> — is answered with nothing rented.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented password and digest-list carriers transfers to the constructed request input, whose consuming transition releases the password once the compare has consumed it and hands the list to the extend effect, and whose refusing and no-op arms dispose them both through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParsePcrExtend(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        if(!TryParsePcrHandle(ref reader, isNullAdmitted: true, out TpmiDhPcr pcrHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        TpmReader probe = reader;
        if(!TrySkipDigestValues(ref probe, out malformedResponseCode))
        {
            return false;
        }

        //digests is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(probe.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bAuth suppliedPcrPassword = Tpm2bAuth.Empty;
        TpmlDigestValues digests = TpmlDigestValues.Empty;
        try
        {
            suppliedPcrPassword = Tpm2bAuth.Create(suppliedAuth, pool);
            digests = TpmlDigestValues.Parse(ref reader, pool);
            input = new TpmPcrExtendRequested(pcrHandle, suppliedPcrPassword, digests);
        }
        catch
        {
            digests.Dispose();
            suppliedPcrPassword.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PCR_Event()</c> authorizes <c>@pcrHandle</c> (TPM 2.0 Library Part 3, clause 22.3, Table 132), so
    /// its wire layout after the header is: handle area (<c>@pcrHandle</c> as <c>TPMI_DH_PCR+</c>), authorization
    /// area (one <c>TPM_RS_PW</c> slot), parameter area (<c>eventData</c> as <c>TPM2B_EVENT</c>, bounded 1024 —
    /// Part 2, Table 95; "A TPM shall support an eventData.size of zero through 1,024 inclusive").
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented password and event carriers transfers to the constructed request input, whose consuming transition releases the password once the compare has consumed it and hands the event to the digest effect, and whose refusing arms dispose them both through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParsePcrEvent(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        if(!TryParsePcrHandle(ref reader, isNullAdmitted: true, out TpmiDhPcr pcrHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bEvent.MaxSize, out ReadOnlySpan<byte> eventData, out malformedResponseCode))
        {
            //Table 132: eventData is TPM2_PCR_Event()'s sole parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //eventData is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bAuth suppliedPcrPassword = Tpm2bAuth.Empty;
        Tpm2bEvent eventCarrier = Tpm2bEvent.Empty;
        try
        {
            suppliedPcrPassword = Tpm2bAuth.Create(suppliedAuth, pool);
            eventCarrier = Tpm2bEvent.Create(eventData, pool);
            input = new TpmPcrEventRequested(pcrHandle, suppliedPcrPassword, eventCarrier);
        }
        catch
        {
            eventCarrier.Dispose();
            suppliedPcrPassword.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PCR_Reset()</c> authorizes <c>@pcrHandle</c> and carries no parameters (TPM 2.0 Library Part 3,
    /// clause 22.8, Table 142), so its wire layout after the header is: handle area (<c>@pcrHandle</c> as
    /// <c>TPMI_DH_PCR</c> — no <c>+</c>, so <c>TPM_RH_NULL</c> is <c>TPM_RC_VALUE</c>), authorization area (one
    /// <c>TPM_RS_PW</c> slot), and nothing more.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented password carrier transfers to the constructed request input, whose consuming transition releases it once the compare has consumed it and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParsePcrReset(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        if(!TryParsePcrHandle(ref reader, isNullAdmitted: false, out TpmiDhPcr pcrHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        //Table 142 has no parameter area; no octets may follow the authorization area (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmPcrResetRequested(pcrHandle, Tpm2bAuth.Create(suppliedAuth, pool));

        return true;
    }

    /// <summary>
    /// <c>TPM2_EventSequenceComplete()</c> authorizes both <c>@pcrHandle</c> and <c>@sequenceHandle</c> (TPM 2.0
    /// Library Part 3, clause 17.9, Table 95), so its wire layout after the header is: handle area
    /// (<c>@pcrHandle</c> as <c>TPMI_DH_PCR+</c>, then <c>@sequenceHandle</c>), authorization area (two
    /// <c>TPM_RS_PW</c> slots in handle order — a second slot missing is clause 5.5's "An authorization session
    /// is present for each of the handles with the '@' decoration (TPM_RC_AUTH_MISSING)"), parameter area
    /// (<c>buffer</c> as <c>TPM2B_MAX_BUFFER</c>) — the <see cref="TryParseSequenceComplete"/> shape with a PCR
    /// handle and its slot in front and no ticket hierarchy behind.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented password and buffer carriers transfers to the constructed request input, whose consuming transition releases the passwords once the compares have consumed them and hands the buffer to the digest effect, and whose refusing arms dispose all three through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseEventSequenceComplete(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        if(!TryParsePcrHandle(ref reader, isNullAdmitted: true, out TpmiDhPcr pcrHandle, out malformedResponseCode))
        {
            return false;
        }

        //Handle area, second slot: @sequenceHandle (the open Event Sequence), resolved by the transition. Table
        //95: @sequenceHandle is the second (index 1) handle.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

            return false;
        }

        uint sequenceHandle = reader.ReadUInt32();

        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPasswordSessionBody(ref reader, out ReadOnlySpan<byte> pcrAuth, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Consumed - sessionsStart >= (int)authorizationSize)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        if(!TryReadPasswordSessionBody(ref reader, out ReadOnlySpan<byte> sequenceAuth, out malformedResponseCode, sessionIndex: 1))
        {
            return false;
        }

        if(!TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //Parameter: buffer (TPM2B_MAX_BUFFER) — bound-first against MaxSize (1024, TPM_RC_SIZE); an empty
        //buffer is admitted ("the last part of data, if any", clause 17.9.1).
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bMaxBuffer.MaxSize, out ReadOnlySpan<byte> buffer, out malformedResponseCode))
        {
            //Table 95: buffer is TPM2_EventSequenceComplete()'s sole parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //buffer is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bAuth suppliedPcrPassword = Tpm2bAuth.Empty;
        Tpm2bAuth suppliedSequencePassword = Tpm2bAuth.Empty;
        Tpm2bMaxBuffer trailingBuffer = Tpm2bMaxBuffer.Empty;
        try
        {
            suppliedPcrPassword = Tpm2bAuth.Create(pcrAuth, pool);
            suppliedSequencePassword = Tpm2bAuth.Create(sequenceAuth, pool);
            trailingBuffer = Tpm2bMaxBuffer.Create(buffer, pool);
            input = new TpmEventSequenceCompleteRequested(pcrHandle, suppliedPcrPassword, TpmiDhObject.FromValue(sequenceHandle), suppliedSequencePassword, trailingBuffer);
        }
        catch
        {
            trailingBuffer.Dispose();
            suppliedSequencePassword.Dispose();
            suppliedPcrPassword.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_Quote()</c> is authorized and takes one handle, so its wire layout after the header is: handle
    /// area (@signHandle — 1 handle requiring authorization), authorization area (the @signHandle slot, either a
    /// <c>TPM_RS_PW</c> password whose hmac field is the plaintext authValue or a real HMAC session whose hmac is
    /// the command HMAC, optionally followed by one or two companion slots authorizing nothing), then parameters
    /// (qualifyingData as TPM2B_DATA, inScheme as TPMT_SIG_SCHEME, PCRselect as TPML_PCR_SELECTION). A lone
    /// password slot parses to <see cref="TpmQuoteRequested"/>; anything else, including a password slot
    /// ALONGSIDE a companion, parses to <see cref="TpmQuoteOverSessionRequested"/>, whose response owes one entry
    /// per slot (TPM 2.0 Library Part 1, clause 15.6.1).
    /// </summary>
    /// <remarks>
    /// The number of slots is read from the declared authorization size rather than assumed, the
    /// <c>TPM2_Create()</c> idiom: a slot that has not consumed the whole area leaves a companion behind it
    /// (Part 1, clause 15.6.1, Table 12 — "authorization sessions come before sessions used only for encryption,
    /// decryption, or audit"). One authorizing slot leaves BOTH of Table 12's later positions open, so the area may
    /// carry two companions; <c>TryEndAuthArea</c> answers <c>TPM_RC_AUTHSIZE</c> for a fourth slot or any surplus
    /// octet, which is the "no more than three" bound of clause 15.6.1. The scheme's validation is entirely in the
    /// signing scheme selector (Part 3, clause 18.4).
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented PCR selection, sign-slot credential, sign-slot caller nonce, both companion slots' credentials and caller nonces, and qualifying-data carriers transfers to the constructed request input, whose consuming transition (password) or continuation (session) releases them or transfers them into the quote action and its response-session entries, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseQuote(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: @signHandle (the signing key). Table 101: @signHandle is TPM2_Quote()'s sole handle,
        //index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        TpmiDhObject signHandle = TpmiDhObject.FromValue(reader.ReadUInt32());

        //The authorizing slot is read generically: a TPM_RS_PW handle is the password form, any other handle is a
        //real HMAC session. The area is bracketed exactly as the password form was.
        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadCommandSessionSpans(ref reader, sessionIndex: 0, out TpmiShAuthSession signSessionHandle, out ReadOnlySpan<byte> signNonceCaller, out TpmaSession signSessionAttributes, out ReadOnlySpan<byte> signHmac, out malformedResponseCode))
        {
            return false;
        }

        //Octets left inside the declared authorization size after the last REQUIRED slot are a companion slot
        //(Part 1, clause 15.6.1, Table 12, position after the authorization sessions).
        bool hasCompanion = reader.Consumed - sessionsStart != (int)authorizationSize;
        TpmiShAuthSession companionSessionHandle = TpmiShAuthSession.FromValue(0);
        TpmaSession companionSessionAttributes = default;

        //The two span locals are declared scoped so they can receive slices that alias the command buffer the
        //by-reference reader points into: without it the compiler must assume a span written through an out
        //parameter of a ref-taking method could outlive that buffer.
        scoped ReadOnlySpan<byte> companionNonceCaller = ReadOnlySpan<byte>.Empty;
        scoped ReadOnlySpan<byte> companionHmac = ReadOnlySpan<byte>.Empty;
        if(hasCompanion
            && !TryReadCommandSessionSpans(ref reader, sessionIndex: 1, out companionSessionHandle, out companionNonceCaller, out companionSessionAttributes, out companionHmac, out malformedResponseCode))
        {
            return false;
        }

        //Octets STILL left after the first companion are a second one: with a single authorizing slot, Table 12's
        //positions 2 and 3 are both open, and each may be an encryption, decryption, or audit session (Part 1,
        //clause 15.6.1). A fourth block would overrun the declared size, which TryEndAuthArea answers below.
        bool hasSecondCompanion = reader.Consumed - sessionsStart != (int)authorizationSize;
        TpmiShAuthSession secondCompanionSessionHandle = TpmiShAuthSession.FromValue(0);
        TpmaSession secondCompanionSessionAttributes = default;

        scoped ReadOnlySpan<byte> secondCompanionNonceCaller = ReadOnlySpan<byte>.Empty;
        scoped ReadOnlySpan<byte> secondCompanionHmac = ReadOnlySpan<byte>.Empty;
        if(hasSecondCompanion
            && !TryReadCommandSessionSpans(ref reader, sessionIndex: 2, out secondCompanionSessionHandle, out secondCompanionNonceCaller, out secondCompanionSessionAttributes, out secondCompanionHmac, out malformedResponseCode))
        {
            return false;
        }

        if(!TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //The parameter set (qualifyingData ‖ inScheme ‖ PCRselect) is every octet left after the authorization
        //area — captured verbatim, before any field is decoded, as the session arm's cpHash parameter term
        //(Part 1, clause 15.7 equation 15).
        ReadOnlySpan<byte> rawParameterAreaOctets = reader.PeekBytes(reader.Remaining);

        //Which arm the area belongs to is settled before the parameters are read, because it decides how
        //qualifyingData may be treated: a LONE TPM_RS_PW slot is the all-password form the password arm serves.
        bool isPasswordSlot = signSessionHandle.IsPasswordSession && !hasCompanion;

        //Parameter: qualifyingData (TPM2B_DATA) — the caller nonce echoed into the attestation, and the first
        //command parameter, which is the one a decrypt session protects (Part 1, clause 15.4). On the session
        //form these octets may be CIPHERTEXT, so the parse only steps over the field's framing to reach the
        //parameters behind it and the decrypt step supplies the plaintext (Part 3, clause 5.7 precedes clause
        //5.8); decoding here would also be futile, since a separately copied field is not updated by the in-place
        //transform of the captured area. On the password form no session can protect it, so it is read as a span
        //over the command buffer whose owning carrier is rented as this parse's last act.
        scoped ReadOnlySpan<byte> qualifyingData = ReadOnlySpan<byte>.Empty;
        if(isPasswordSlot)
        {
            if(!TryReadTpm2bSpan(ref reader, out qualifyingData, out malformedResponseCode))
            {
                //Table 101: qualifyingData is TPM2_Quote()'s first parameter, index 0.
                malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

                return false;
            }

            //TPM2B_DATA is bounded by sizeof(TPMT_HA) (Part 2, clause 10.3.3, Table 91), so a wider value is
            //TPM_RC_SIZE here, before any carrier is rented; the consuming transition's own bound check stands as
            //the fail-closed backstop. The session form's bound is applied to the RECOVERED value instead, which
            //is the only form of it TPM2B_DATA is about. qualifyingData is this command's first parameter (P1).
            if(qualifyingData.Length > Tpm2bData.MaxSize)
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

                return false;
            }
        }
        else if(!TrySkipTpm2b(ref reader, out malformedResponseCode))
        {
            //Table 101: qualifyingData is TPM2_Quote()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: inScheme (TPMT_SIG_SCHEME) — scheme selector (UINT16), plus a hashAlg (UINT16) detail pair
        //only when the selector is not TPM_ALG_NULL (TPM 2.0 Library Part 2, clause 11.2.1.4/11.2.1.5, Tables
        //182/183: the "null" row of Table 182 carries an empty Type column against selector TPM_ALG_NULL, so
        //Table 183's [scheme]details is absent entirely for it). It sits behind the first parameter and so is
        //never encrypted, which is why it is decoded on both arms alike. Table 101: inScheme is the second
        //parameter, index 1.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

            return false;
        }

        TpmiAlgSigScheme signatureScheme = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        TpmiAlgHash schemeHashAlg;
        if(signatureScheme.IsNull)
        {
            schemeHashAlg = TpmiAlgHash.FromValue(TpmAlgIdConstants.TPM_ALG_NULL);
        }
        else
        {
            if(reader.Remaining < sizeof(ushort))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

                return false;
            }

            schemeHashAlg = TpmiAlgHash.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        }

        //Parameter: PCRselect (TPML_PCR_SELECTION) — the final parameter, decoded into an owned pooled carrier
        //that both drives the PCR gather in the transition and is written back verbatim into the attestation's
        //pcrSelect. The wire shape is probed first on a by-value copy of the reader, which leaves the reader
        //itself untouched, so a truncated list answers TPM_RC_INSUFFICIENT and a trailing octet TPM_RC_SIZE
        //(Part 3, clause 5.8.2, Table 2) before any rental happens.
        TpmReader probe = reader;
        if(!TrySkipPcrSelection(ref probe, out malformedResponseCode))
        {
            //Table 101: PCRselect is TPM2_Quote()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        if(probe.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        TpmlPcrSelection pcrSelection;
        try
        {
            pcrSelection = TpmlPcrSelection.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            //A list naming more banks than HASH_COUNT selections is out of the structure's declared bound
            //(Part 2, clause 10.8.7, Table 128: #TPM_RC_SIZE). Table 101: PCRselect is TPM2_Quote()'s third
            //parameter, index 2 — the probe above already refuses this width, so this is the fail-closed
            //backstop rather than the answering layer.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 2);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            //A selection whose sizeofSelect lies outside PCR_SELECT_MIN..PCR_SELECT_MAX is out of the member's
            //own declared bounds (Part 2, clause 10.5.2, Table 107: #TPM_RC_VALUE). The probe above already
            //refuses that width, so this is the fail-closed backstop rather than the answering layer. Table 101:
            //PCRselect is TPM2_Quote()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 2);

            return false;
        }

        //Either form's owned pooled carriers are rented here, the parse's last act after every wire check has
        //passed, so no refused parse ever creates one. Only the session arm retains the slots' caller nonces, so
        //only it rents them — the password record has no slot to adopt one — and only the password arm carries a
        //qualifying-data carrier out of the parse, the session arm's being supplied by the decrypt step.
        Tpm2bAuth signCredential = Tpm2bAuth.Empty;
        Tpm2bNonce signNonce = Tpm2bNonce.Empty;
        Tpm2bAuth companionCredential = Tpm2bAuth.Empty;
        Tpm2bNonce companionNonce = Tpm2bNonce.Empty;
        Tpm2bAuth secondCompanionCredential = Tpm2bAuth.Empty;
        Tpm2bNonce secondCompanionNonce = Tpm2bNonce.Empty;
        TpmParameterArea parameterArea = TpmParameterArea.Empty;
        try
        {
            signCredential = Tpm2bAuth.Create(signHmac, pool);
            signNonce = isPasswordSlot ? Tpm2bNonce.Empty : Tpm2bNonce.Create(signNonceCaller, pool);
            companionCredential = hasCompanion ? Tpm2bAuth.Create(companionHmac, pool) : Tpm2bAuth.Empty;
            companionNonce = hasCompanion ? Tpm2bNonce.Create(companionNonceCaller, pool) : Tpm2bNonce.Empty;
            secondCompanionCredential = hasSecondCompanion ? Tpm2bAuth.Create(secondCompanionHmac, pool) : Tpm2bAuth.Empty;
            secondCompanionNonce = hasSecondCompanion ? Tpm2bNonce.Create(secondCompanionNonceCaller, pool) : Tpm2bNonce.Empty;
            parameterArea = isPasswordSlot ? TpmParameterArea.Empty : TpmParameterArea.Create(rawParameterAreaOctets, pool);
            input = isPasswordSlot
                ? new TpmQuoteRequested(
                    signHandle, signCredential, Tpm2bData.Create(qualifyingData, pool), signatureScheme, schemeHashAlg, pcrSelection)
                : new TpmQuoteOverSessionRequested(
                    signHandle, signSessionHandle, signNonce, signSessionAttributes, signCredential,
                    Tpm2bData.Empty, signatureScheme, schemeHashAlg, pcrSelection, parameterArea,
                    hasCompanion, companionSessionHandle, companionNonce, companionSessionAttributes, companionCredential,
                    hasSecondCompanion, secondCompanionSessionHandle, secondCompanionNonce, secondCompanionSessionAttributes, secondCompanionCredential);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            parameterArea.Dispose();
            secondCompanionNonce.Dispose();
            secondCompanionCredential.Dispose();
            companionNonce.Dispose();
            companionCredential.Dispose();
            signNonce.Dispose();
            signCredential.Dispose();
            pcrSelection.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_StartAuthSession()</c> is framed with no sessions (Part 3, clause 11.1): its wire body after the
    /// header is the handle area (tpmKey, bind) then the parameters (nonceCaller as TPM2B_NONCE, encryptedSalt
    /// as TPM2B_ENCRYPTED_SECRET, sessionType as TPM_SE (BYTE), symmetric as TPMT_SYM_DEF, authHash as
    /// TPMI_ALG_HASH).
    /// </summary>
    /// <remarks>
    /// A policy or trial session (TPM_SE_POLICY / TPM_SE_TRIAL) and a bound and/or salted HMAC session
    /// (TPM_SE_HMAC) dispatch to distinct inputs, but the clause 11.1 precondition ladder and the salt recovery
    /// behind them are session-type-agnostic: tpmKey, bind, nonceCaller (a KDFa context of the session key),
    /// encryptedSalt, and the negotiated symmetric definition parse and thread through BOTH forms, so a salted
    /// policy session derives its session key exactly as a salted HMAC session does.
    /// </remarks>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="pool">The memory pool the request's owned nonce and salt carriers are rented from.</param>
    /// <param name="input">The parsed <see cref="TpmStartAuthSessionRequested"/> or <see cref="TpmStartHmacSessionRequested"/> input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented caller-nonce and encrypted-salt carriers transfers to the constructed request input; the accepted transition transfers both into the session-start action whose effect is their terminal owner, and every refusing arm releases them through the input's own Dispose; a rent that fails after the first carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseStartAuthSession(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        //Handle area: tpmKey (the key salt is encrypted to, or TPM_RH_NULL for unsalted) and bind (the entity a
        //bound session binds to, or TPM_RH_NULL), each field's own shortfall designated to its own index (Table
        //14; a buffer wide enough for tpmKey alone designates bind, not tpmKey).
        if(!TryReadHandle(ref reader, 0, out uint tpmKey, out malformedResponseCode))  //tpmKey (TPM_RH_NULL for an unsalted session).
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 1, out uint bind, out malformedResponseCode))  //bind entity (TPM_RH_NULL when unbound).
        {
            return false;
        }

        //Parameter: nonceCaller (TPM2B_NONCE) — captured because a bound HMAC session folds it into the session key.
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> nonceCaller, out malformedResponseCode))
        {
            //Table 14: nonceCaller is TPM2_StartAuthSession()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, which types it as a TPM2B_DIGEST, over clause 10.3.2, Table 90, which bounds
        //that structure's buffer and names TPM_RC_SIZE); the carrier's Create refuses the same bound by
        //throwing, so the wire answer is given here, ahead of the rental. clause 11.1.1's own floor and its
        //"no wider than the digest produced by authHash" ceiling are narrower, session-specific rules and stay
        //where the session's hash is known.
        //Table 14: nonceCaller is the first parameter, index 0.
        if(nonceCaller.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameter: encryptedSalt (TPM2B_ENCRYPTED_SECRET) — an RSA OAEP ciphertext or a marshaled
        //TPMS_ECC_POINT depending on tpmKey's algorithm, captured for the HMAC session's salted arm; empty for an
        //unsalted session.
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> encryptedSalt, out malformedResponseCode))
        {
            //Table 14: encryptedSalt is TPM2_StartAuthSession()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //A TPM2B_ENCRYPTED_SECRET's secret is bounded by sizeof(TPMU_ENCRYPTED_SECRET) (TPM 2.0 Library Part 2,
        //clause 11.4.3, Table 224, page 180), the widest asymmetrically protected seed the union holds, and a
        //sized buffer past its prescribed range is TPM_RC_SIZE (clause 10.3.2, Table 90, page 134's implied
        //check). The carrier's Create refuses the same bound by throwing, so the wire answer is given here.
        //Table 14: encryptedSalt is the second parameter, index 1.
        if(encryptedSalt.Length > Tpm2bEncryptedSecret.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        //Parameter: sessionType (TPM_SE, BYTE). Table 14: sessionType is the third parameter, index 2.
        if(reader.Remaining < sizeof(byte))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 2);

            return false;
        }

        var sessionType = (TpmSeConstants)reader.ReadByte();

        //Parameter: symmetric (TPMT_SYM_DEF) — a null definition for a policy session, or XOR/AES for a parameter-
        //encryption HMAC session. Its unions collapse on the wire (Part 2, clause 11.1.6), so the encoded length
        //depends on the algorithm selector; bound-check the full definition before unmarshalling it. Table 14:
        //symmetric is the fourth parameter, index 3.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

            return false;
        }

        var symmetricAlg = (TpmAlgIdConstants)System.Buffers.Binary.BinaryPrimitives.ReadUInt16BigEndian(reader.PeekBytes(sizeof(ushort)));
        int symmetricSize = symmetricAlg switch
        {
            TpmAlgIdConstants.TPM_ALG_NULL => sizeof(ushort),               //algorithm only.
            TpmAlgIdConstants.TPM_ALG_XOR => sizeof(ushort) + sizeof(ushort),//algorithm + keyBits (the KDF hash); XOR has no mode.
            _ => sizeof(ushort) + sizeof(ushort) + sizeof(ushort)           //algorithm + keyBits + mode (a block cipher).
        };
        if(reader.Remaining < symmetricSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

            return false;
        }

        TpmtSymDef symmetric = TpmtSymDef.Parse(ref reader);

        //Parameter: authHash (TPMI_ALG_HASH, UINT16) — the session's hash algorithm. Table 14: authHash is the
        //fifth parameter, index 4.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 4);

            return false;
        }

        TpmiAlgHash authHash = TpmiAlgHash.FromValue((TpmAlgIdConstants)reader.ReadUInt16());

        //authHash is the final parameter; no octets may follow it — the reference's own generic trailing-octets
        //check, not attributable to a single field. Stays bare.
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //A bound and/or salted HMAC session drives parameter encryption; a policy/trial session drives a
        //policyDigest — the bind/salt fields are still carried for it (the sessionKey derivation ladder is
        //session-type-independent, Part 3, clause 11.1.1), not discarded. Both owned carriers are rented here,
        //the parse's last act after every wire check has passed, so no refused parse ever creates one.
        Tpm2bNonce startNonceCaller = Tpm2bNonce.Empty;
        Tpm2bEncryptedSecret startEncryptedSalt = Tpm2bEncryptedSecret.Empty;
        try
        {
            startNonceCaller = Tpm2bNonce.Create(nonceCaller, pool);
            startEncryptedSalt = Tpm2bEncryptedSecret.Create(encryptedSalt, pool);

            input = sessionType == TpmSeConstants.TPM_SE_HMAC
                ? new TpmStartHmacSessionRequested(TpmiDhEntity.FromValue(bind), startNonceCaller, symmetric, authHash, TpmiDhObject.FromValue(tpmKey), startEncryptedSalt)
                : new TpmStartAuthSessionRequested(sessionType, authHash, TpmiDhEntity.FromValue(bind), startNonceCaller, symmetric, TpmiDhObject.FromValue(tpmKey), startEncryptedSalt);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            startEncryptedSalt.Dispose();
            startNonceCaller.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_GetRandom()</c>'s parameter core (TPM 2.0 Library Part 3, clause 16.1, Table 75): the single
    /// <c>bytesRequested</c> (UINT16) parameter, shared by the plain <c>TPM_ST_NO_SESSIONS</c> form
    /// (<see cref="TryParseGetRandom"/>) and the no-authorization wrapper's parameter step
    /// (<see cref="TryParseNoAuthParameters"/>) — safe over ciphertext too, since GetRandom's shape row admits
    /// only a response-side <c>encrypt</c> companion, never a command-side <c>decrypt</c> one.
    /// </summary>
    /// <param name="reader">The reader positioned at <c>bytesRequested</c>.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameter parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseGetRandomParameters(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        //A command whose parameter area is too short to unmarshal bytesRequested is a shortfall, which the TPM
        //reports as TPM_RC_INSUFFICIENT ("not enough octets in the input buffer"), not the size-value-out-of-range
        //TPM_RC_SIZE (Part 2, Table 2). Table 75: bytesRequested is TPM2_GetRandom()'s sole parameter, index 0 —
        //invariant across both of this reader's callers (the plain form and the no-authorization wrapper), since
        //both parse the same command.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        input = new TpmGetRandomRequested(reader.ReadUInt16());
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// <c>TPM2_GetRandom()</c>'s <c>TPM_ST_NO_SESSIONS</c> form (TPM 2.0 Library Part 3, clause 16.1): the
    /// parameter core (<see cref="TryParseGetRandomParameters"/>) plus the final-parameter width check every
    /// bare command shares (Part 4 <c>CommandDispatcher</c>'s generic "no leftover octets" rule).
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseGetRandom(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        if(!TryParseGetRandomParameters(ref reader, out input, out malformedResponseCode))
        {
            return false;
        }

        //bytesRequested is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            input = null;
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_StirRandom()</c>'s parameter core (TPM 2.0 Library Part 3, clause 16.2, Table 77): the single
    /// <c>inData</c> (<c>TPM2B_SENSITIVE_DATA</c>) parameter, shared by the plain <c>TPM_ST_NO_SESSIONS</c> form
    /// (<see cref="TryParseStirRandom"/>) and the no-authorization wrapper's parameter step
    /// (<see cref="TryParseNoAuthParameters"/>). Safe to run over ciphertext: only the <c>TPM2B</c>'s
    /// never-encrypted structural size prefix is interpreted here, never the DATA portion a decrypt claim
    /// protects (TPM 2.0 Library Part 1, clause 18); <see cref="DecryptFirstParameterAsync"/>'s wrapper arm
    /// re-runs this same core over the recovered plaintext once a decrypt claim has transformed it.
    /// </summary>
    /// <param name="reader">The reader positioned at <c>inData</c>.</param>
    /// <param name="pool">The memory pool <c>inData</c>'s carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameter parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseStirRandomParameters(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        Tpm2bSensitiveData inData;
        try
        {
            //Tpm2bSensitiveData.Parse's own bound: a declared size over MAX_SYM_DATA (128) is TPM_RC_SIZE
            //(InvalidOperationException); a size the frame cannot hold is TPM_RC_INSUFFICIENT
            //(ArgumentOutOfRangeException) — checked before any storage is rented, so a truncated frame orphans
            //nothing. inData is TPM2_StirRandom()'s sole parameter (Table 77, index 0; the reference's
            //RC_StirRandom_inData = TPM_RC_P + TPM_RC_1). The decrypt continuation's own already-designated
            //guard (TpmRcExtensions.IsDesignated) keeps this from ever picking up a second, session designation
            //when a decrypt slot's claim brought the reader here over already-plaintext octets.
            inData = Tpm2bSensitiveData.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        input = new TpmStirRandomRequested(inData);
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// <c>TPM2_StirRandom()</c>'s <c>TPM_ST_NO_SESSIONS</c> form (TPM 2.0 Library Part 3, clause 16.2, Table
    /// 77): the parameter core (<see cref="TryParseStirRandomParameters"/>) plus the final-parameter width check
    /// every bare-TPM2B command shares.
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="pool">The memory pool <c>inData</c>'s carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseStirRandom(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        if(!TryParseStirRandomParameters(ref reader, pool, out input, out malformedResponseCode))
        {
            return false;
        }

        //inData is the whole parameter area; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            (input as IDisposable)?.Dispose();
            input = null;
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_TestParms()</c>'s parameter core (TPM 2.0 Library Part 3, clause 30.3, Table 240): the whole
    /// parameter area is one <c>TPMT_PUBLIC_PARMS</c>, unmarshalled by <see cref="TryReadPublicParms"/> — the
    /// command IS its unmarshal (Part 4 <c>TestParms.c</c>'s <c>TPM2_TestParms()</c>: "We do nothing in command action") — shared by the
    /// plain <c>TPM_ST_NO_SESSIONS</c> form (<see cref="TryParseTestParms"/>) and the no-authorization wrapper's
    /// parameter step (<see cref="TryParseNoAuthParameters"/>): safe to run unconditionally, since TestParms's
    /// shape admits no <c>decrypt</c> companion at all (Table 240's tag cell names only <c>audit</c>), so this
    /// parameter is never ciphertext.
    /// </summary>
    /// <param name="reader">The reader positioned at <c>parameters</c>.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameter parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseTestParmsParameters(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPublicParms(ref reader, out TpmtPublicParms parms, out malformedResponseCode))
        {
            return false;
        }

        input = new TpmTestParmsRequested(parms);

        return true;
    }

    /// <summary>
    /// <c>TPM2_TestParms()</c>'s <c>TPM_ST_NO_SESSIONS</c> form (TPM 2.0 Library Part 3, clause 30.3): the
    /// parameter core (<see cref="TryParseTestParmsParameters"/>) plus the final-parameter width check every
    /// bare command shares.
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseTestParms(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        if(!TryParseTestParmsParameters(ref reader, out input, out malformedResponseCode))
        {
            return false;
        }

        //parameters is the whole parameter area; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            input = null;
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_ReadClock()</c>'s parameter core (TPM 2.0 Library Part 3, clause 29.1, Table 232): no parameters
    /// at all, shared by the plain <c>TPM_ST_NO_SESSIONS</c> form (<see cref="TryParseReadClock"/>) and the
    /// no-authorization wrapper's parameter step (<see cref="TryParseNoAuthParameters"/>).
    /// </summary>
    /// <param name="reader">The reader positioned where a parameter would begin; unread, since there is none.</param>
    /// <param name="input">The parsed request input; always set.</param>
    /// <param name="malformedResponseCode">Always <see cref="TpmRcConstants.TPM_RC_SUCCESS"/>.</param>
    /// <returns>Always <see langword="true"/>.</returns>
    private static bool TryParseReadClockParameters(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        _ = reader;
        input = new TpmReadClockRequested();
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// <c>TPM2_ReadClock()</c>'s <c>TPM_ST_SESSIONS</c>/<c>TPM_ST_NO_SESSIONS</c> fork (TPM 2.0 Library Part 3,
    /// clause 29.1, Table 232's tag cell: "TPM_ST_SESSIONS if an audit session is present"): the
    /// no-authorization wrapper over an audit companion, or the plain form's parameter core
    /// (<see cref="TryParseReadClockParameters"/>) plus the final-parameter width check every bare command
    /// shares (Part 4 <c>CommandDispatcher</c>'s generic "no leftover octets" rule).
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="tag">The command's wire tag.</param>
    /// <param name="pool">The memory pool the <c>TPM_ST_SESSIONS</c> fork's owned carriers are rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    private static bool TryParseReadClock(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        if(tag == (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
