        }

        //Table 89: context is the third parameter, index 2.
        Tpm2bSignatureCtx context;
        try
        {
            context = Tpm2bSignatureCtx.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            hint.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 2);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            hint.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 2);

            return false;
        }
        catch
        {
            hint.Dispose();

            throw;
        }

        if(reader.Remaining != 0)
        {
            hint.Dispose();
            context.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bAuth sequenceAuth = Tpm2bAuth.Empty;
        try
        {
            sequenceAuth = Tpm2bAuth.Create(auth, pool);
            input = new TpmVerifySequenceStartRequested(TpmiDhObject.FromValue(handles[0].Value), sequenceAuth, hint, context);
        }
        catch
        {
            sequenceAuth.Dispose();
            hint.Dispose();
            context.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_VerifySignature()</c>'s parameter core when reached through the no-authorization wrapper (TPM 2.0
    /// Library Part 3, clause 20.2, Table 116): <c>digest</c> (TPM2B_DIGEST, bounded <c>sizeof(TPMU_HA)</c> —
    /// the one decrypt-eligible first command parameter), then <c>signature</c> (TPMT_SIGNATURE) — the exact
    /// body <see cref="TryParseVerifySignature"/>'s <c>TPM_ST_NO_SESSIONS</c> form runs after its own tag check,
    /// built against the already-parsed <paramref name="handles"/> entry rather than reading <c>keyHandle</c>
    /// again. The response's validation is a TPMT_TK_VERIFIED, not a TPM2B, so no encrypt slot protects it.
    /// </summary>
    /// <param name="handles">The wrapper's parsed handle area; its single entry is <c>keyHandle</c>.</param>
    /// <param name="reader">The reader positioned at <c>digest</c>.</param>
    /// <param name="pool">The memory pool an owned carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameters parse successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented digest and signature carriers transfers to the constructed request input, whose consuming transition hands them to the verification action for the effect to release, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseVerifySignatureParameters(ImmutableArray<TpmHandle> handles, ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> digest, out malformedResponseCode))
        {
            //Table 116: digest is TPM2_VerifySignature()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 116: signature is the second parameter, index 1 (sigAlg is its own leading selector).
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 1);

            return false;
        }

        TpmiAlgSigScheme sigAlg = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        if(sigAlg.Value is not (TpmAlgIdConstants.TPM_ALG_ECDSA or TpmAlgIdConstants.TPM_ALG_RSASSA or TpmAlgIdConstants.TPM_ALG_RSAPSS or TpmAlgIdConstants.TPM_ALG_HMAC))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SCHEME, 1);

            return false;
        }

        if(!TryParseTpmtSignatureBody(ref reader, sigAlg, pool, out TpmtSignature? signature, out malformedResponseCode))
        {
            //Table 116: signature is TPM2_VerifySignature()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        if(reader.Remaining != 0)
        {
            signature.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bDigest digestCarrier = Tpm2bDigest.Empty;
        try
        {
            digestCarrier = Tpm2bDigest.Create(digest, pool);
            input = new TpmVerifySignatureRequested(
                TpmiDhObject.FromValue(handles[0].Value), digestCarrier, sigAlg, TpmiAlgHash.FromValue(signature.Signature.HashAlgorithm), signature);
        }
        catch
        {
            digestCarrier.Dispose();
            signature.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_VerifyDigestSignature()</c>'s parameter core when reached through the no-authorization wrapper
    /// (TPM 2.0 Library Part 3, clause 20.4, Table 120): <c>context</c> (TPM2B_SIGNATURE_CTX, bounded 255 — the
    /// one decrypt-eligible first command parameter, NOT <c>digest</c>), <c>digest</c> (TPM2B_DIGEST, bounded
    /// <c>sizeof(TPMU_HA)</c>), then <c>signature</c> (TPMT_SIGNATURE) — the exact body
    /// <see cref="TryParseVerifyDigestSignature"/>'s <c>TPM_ST_NO_SESSIONS</c> form runs after its own tag
    /// check, built against the already-parsed <paramref name="handles"/> entry rather than reading
    /// <c>keyHandle</c> again. The response's validation is a TPMT_TK_VERIFIED, not a TPM2B, so no encrypt slot
    /// protects it.
    /// </summary>
    /// <param name="handles">The wrapper's parsed handle area; its single entry is <c>keyHandle</c>.</param>
    /// <param name="reader">The reader positioned at <c>context</c>.</param>
    /// <param name="pool">The memory pool an owned carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameters parse successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented context, digest and signature carriers transfers to the constructed request input, whose consuming transition disposes the context once its emptiness is confirmed and transfers the digest and signature to the verification action, and whose refusing arms dispose them all through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseVerifyDigestSignatureParameters(ImmutableArray<TpmHandle> handles, ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        //Table 120: context is the first parameter, index 0.
        Tpm2bSignatureCtx context;
        try
        {
            context = Tpm2bSignatureCtx.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> digest, out malformedResponseCode))
        {
            context.Dispose();

            //Table 120: digest is TPM2_VerifyDigestSignature()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //Table 120: signature is the third parameter, index 2 (sigAlg is its own leading selector).
        if(reader.Remaining < sizeof(ushort))
        {
            context.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 2);

            return false;
        }

        TpmiAlgSigScheme sigAlg = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        if(sigAlg.Value is not (TpmAlgIdConstants.TPM_ALG_ECDSA or TpmAlgIdConstants.TPM_ALG_RSASSA or TpmAlgIdConstants.TPM_ALG_RSAPSS))
        {
            context.Dispose();
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SCHEME, 2);

            return false;
        }

        if(!TryParseTpmtSignatureBody(ref reader, sigAlg, pool, out TpmtSignature? signature, out malformedResponseCode))
        {
            context.Dispose();

            //Table 120: signature is TPM2_VerifyDigestSignature()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        if(reader.Remaining != 0)
        {
            context.Dispose();
            signature.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bDigest digestCarrier = Tpm2bDigest.Empty;
        try
        {
            digestCarrier = Tpm2bDigest.Create(digest, pool);
            input = new TpmVerifyDigestSignatureRequested(
                TpmiDhObject.FromValue(handles[0].Value), context, digestCarrier, sigAlg, TpmiAlgHash.FromValue(signature.Signature.HashAlgorithm), signature);
        }
        catch
        {
            digestCarrier.Dispose();
            context.Dispose();
            signature.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_Encapsulate()</c>'s parameter core when reached through the no-authorization wrapper (TPM 2.0
    /// Library Part 3, clause 14.10, Table 60): the request needs only the already-parsed
    /// <paramref name="handles"/> entry — Table 60 declares no command parameter at all, so no decrypt slot has
    /// anything to protect — and the trailing-octet check <see cref="TryParseEncapsulate"/>'s
    /// <c>TPM_ST_NO_SESSIONS</c> form applies after its own handle read.
    /// </summary>
    /// <param name="handles">The wrapper's parsed handle area; its single entry is <c>keyHandle</c>.</param>
    /// <param name="reader">The reader positioned where Table 60's (empty) parameter area would begin.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when no octets remain; otherwise <see langword="false"/>.</returns>
    private static bool TryParseEncapsulateParameters(ImmutableArray<TpmHandle> handles, ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmEncapsulateRequested(TpmiDhObject.FromValue(handles[0].Value));

        return true;
    }

    /// <summary>
    /// <c>TPM2_MakeCredential()</c>'s parameter core when reached through the no-authorization wrapper (TPM 2.0
    /// Library Part 3, clause 12.6, Table 28): <c>credential</c> (TPM2B_DIGEST, bounded
    /// <c>sizeof(TPMU_HA)</c> — the one decrypt-eligible first command parameter), then <c>objectName</c>
    /// (TPM2B_NAME, bounded <c>sizeof(TPMU_NAME)</c>) — the exact body <see cref="TryParseMakeCredential"/>'s
    /// <c>TPM_ST_NO_SESSIONS</c> form runs after its own tag check, built against the already-parsed
    /// <paramref name="handles"/> entry rather than reading the handle again. The response's credentialBlob IS
    /// a TPM2B_ID_OBJECT an encrypt slot may protect (Part 4 CommandAttributeData.h's ENCRYPT_2 bit, read by <c>CommandCapGetCCAttribute()</c>).
    /// </summary>
    /// <param name="handles">The wrapper's parsed handle area; its single entry is the credential key.</param>
    /// <param name="reader">The reader positioned at <c>credential</c>.</param>
    /// <param name="pool">The memory pool an owned carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameters parse successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented credential carrier transfers to the constructed request input, whose consuming transition transfers it into the wrap action for the effect to release, and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParseMakeCredentialParameters(ImmutableArray<TpmHandle> handles, ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> credential, out malformedResponseCode))
        {
            //Table 28: credential is TPM2_MakeCredential()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 28: credential is the first parameter, index 0.
        if(credential.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> objectName, out malformedResponseCode))
        {
            //Table 28: objectName is TPM2_MakeCredential()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //Table 28: objectName is the second parameter, index 1.
        if(objectName.Length > Tpm2bName.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        Tpm2bDigest credentialSecret = Tpm2bDigest.Empty;
        try
        {
            credentialSecret = Tpm2bDigest.Create(credential, pool);
            input = new TpmMakeCredentialRequested(TpmiDhObject.FromValue(handles[0].Value), credentialSecret, Tpm2bName.Create(objectName, pool));
        }
        catch
        {
            credentialSecret.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_RSA_Encrypt()</c>'s parameter core when reached through the no-authorization wrapper (TPM 2.0
    /// Library Part 3, clause 14.2, Table 44): <c>message</c>, <c>inScheme</c> and <c>label</c> through
    /// <see cref="TryParseRsaEncryptParameters"/> — the SAME core <see cref="TryParseRsaEncrypt"/>'s
    /// <c>TPM_ST_NO_SESSIONS</c> form runs, <c>message</c>'s own <c>MAX_RSA_KEY_BYTES</c> bound included — built
    /// against the already-parsed <paramref name="handles"/> entry rather than reading the handle again. Reached
    /// only once the authorization area has verified (clause 5.5 precedes clause 5.8), so a decrypt slot's
    /// ciphertext has already been recovered in place before this runs.
    /// </summary>
    /// <param name="handles">The wrapper's parsed handle area; its single entry is <c>keyHandle</c>.</param>
    /// <param name="reader">The reader positioned at <c>message</c>.</param>
    /// <param name="pool">The memory pool an owned carrier is rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameters parse successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented message and label carriers transfers to the constructed request input, whose accepting transition transfers them into the encryption action for the effect to release, and whose refusing arms dispose them through the input's own Dispose.")]
    private static bool TryParseRsaEncryptParametersFromHandle(ImmutableArray<TpmHandle> handles, ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryParseRsaEncryptParameters(ref reader, pool, out Tpm2bPublicKeyRsa message, out TpmtRsaDecrypt inScheme, out Tpm2bData label, out malformedResponseCode))
        {
            return false;
        }

        //label is the last parameter (Table 44); no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            label.Dispose();
            message.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmRsaEncryptRequested(TpmiDhObject.FromValue(handles[0].Value), message, inScheme, label);

        return true;
    }

    /// <summary>
    /// Dispatches to a no-authorization command's own parameter core (TPM 2.0 Library Part 3, clause 5.8) — the
    /// SAME core its plain <c>TPM_ST_NO_SESSIONS</c> form runs, shared here so the wrapper's parse and its
    /// decrypt-rebuild step (<see cref="DecryptFirstParameterAsync"/>) can never drift from the plain form's own
    /// shape. A command whose parameter core builds its request straight from the handle area
    /// (<c>TPM2_ReadPublic()</c>, <c>TPM2_NV_ReadPublic()</c>) reads <paramref name="handles"/> instead of
    /// <paramref name="reader"/>.
    /// </summary>
    /// <param name="commandCode">The wrapped command; must have a row in <see cref="TpmNoAuthSessionShape"/>.</param>
    /// <param name="reader">The reader positioned at the command's own parameters.</param>
    /// <param name="pool">The memory pool an owned carrier is rented from.</param>
    /// <param name="handles">The wrapper's parsed handle area, empty for a handle-less command.</param>
    /// <param name="input">The parsed inner request on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the parameters parse successfully; otherwise <see langword="false"/>.</returns>
    /// <exception cref="InvalidOperationException"><paramref name="commandCode"/> is not one of the commands this mechanism routes — a programming error, since only a caller that already confirmed a <see cref="TpmNoAuthSessionShape"/> row reaches here.</exception>
    private static bool TryParseNoAuthParameters(TpmCcConstants commandCode, ref TpmReader reader, BaseMemoryPool pool, ImmutableArray<TpmHandle> handles, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode) =>
        commandCode switch
        {
            TpmCcConstants.TPM_CC_GetRandom => TryParseGetRandomParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_StirRandom => TryParseStirRandomParameters(ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_TestParms => TryParseTestParmsParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_ReadClock => TryParseReadClockParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_Shutdown => TryParseShutdownParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_SelfTest => TryParseSelfTestParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_GetTestResult => TryParseGetTestResultParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_GetCapability => TryParseGetCapabilityParameters(ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_PCR_Read => TryParsePcrReadParameters(ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_ReadPublic => TryParseReadPublicFromHandle(handles, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_NV_ReadPublic => TryParseNvReadPublicFromHandle(handles, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_Hash => TryParseHashParameters(ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_HashSequenceStart => TryParseHashSequenceStartParameters(ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_SignSequenceStart => TryParseSignSequenceStartParameters(handles, ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_VerifySequenceStart => TryParseVerifySequenceStartParameters(handles, ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_VerifySignature => TryParseVerifySignatureParameters(handles, ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_VerifyDigestSignature => TryParseVerifyDigestSignatureParameters(handles, ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_Encapsulate => TryParseEncapsulateParameters(handles, ref reader, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_MakeCredential => TryParseMakeCredentialParameters(handles, ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_LoadExternal => TryParseLoadExternal(ref reader, pool, out input, out malformedResponseCode),
            TpmCcConstants.TPM_CC_RSA_Encrypt => TryParseRsaEncryptParametersFromHandle(handles, ref reader, pool, out input, out malformedResponseCode),
            _ => throw new InvalidOperationException($"No no-authorization parameter core is defined for '{commandCode}'.")
        };

    /// <summary>
    /// Reads whichever of the sixteen no-authorization commands' handle areas precedes its authorization area
    /// (TPM 2.0 Library Part 3, clause 4.3: authorizationSize "shall immediately follow the handle area (which
    /// may contain no handles)") — a switch keyed on <paramref name="commandCode"/>, since each command's handle
    /// carries its own interface type (Part 3, clause 5.4) and this mechanism's handles are never authorized
    /// (<c>Auth Index: None</c> on every one of them), so no <c>TpmAuthorizedEntity</c> is ever produced here.
    /// </summary>
    /// <param name="commandCode">The command; every arm mirrors its own plain parser's handle read exactly.</param>
    /// <param name="reader">The reader positioned at the first handle.</param>
    /// <param name="handles">The parsed handle area in wire order, empty for a handle-less command.</param>
    /// <param name="malformedResponseCode">The response code to return when a handle is malformed.</param>
    /// <returns><see langword="true"/> when the handle area parsed successfully; otherwise <see langword="false"/>.</returns>
    /// <exception cref="InvalidOperationException"><paramref name="commandCode"/> declares a handle (<see cref="Spec.Attributes.TpmaCc.C_HANDLES"/> is non-zero) but has no arm here — a programming error, since every admitted command with a handle must have one.</exception>
    private static bool TryParseNoAuthHandles(TpmCcConstants commandCode, ref TpmReader reader, out ImmutableArray<TpmHandle> handles, out TpmRcConstants malformedResponseCode)
    {
        handles = ImmutableArray<TpmHandle>.Empty;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        int handleCount = commandCode.GetCommandAttributes().C_HANDLES;
        if(handleCount == 0)
        {
            return true;
        }

        if(reader.Remaining < sizeof(uint))
        {
            //Every command this switch admits carries exactly one handle (C_HANDLES == 1 whenever this line is
            //reached, handleCount == 0 having already returned above), so a failure reading it is always the
            //command's sole handle, index 0 (Part 2, clause 6.6.2; CommandDispatcher's ParseHandleBuffer
            //attributes any handle-area unmarshal failure the same way).
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        switch(commandCode)
        {
            //TPM2_ReadPublic() (Part 3, clause 12.4, Table 24): objectHandle, TPMI_DH_OBJECT — transient or
            //persistent only, sharing IsWithinDhObjectRange with TryParseReadPublic's own plain-form check (Part
            //2, clause 9.3, Table 49; Table 24 declares the handle without the '+', so TPM_RH_NULL is out of
            //range here too).
            case TpmCcConstants.TPM_CC_ReadPublic:
            {
                uint objectHandle = reader.ReadUInt32();
                if(!IsWithinDhObjectRange(objectHandle))
                {
                    //TPM2_ReadPublic() (Table 24) declares objectHandle as its sole handle: index 0.
                    malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

                    return false;
                }

                handles = ImmutableArray.Create(new TpmHandle(objectHandle));

                return true;
            }

            //TPM2_NV_ReadPublic() (Part 3, clause 31.6, Table 251): nvIndex, TPMI_RH_NV_INDEX, mirroring
            //TryParseNvReadPublic's own range check exactly (Part 2, Table 71).
            case TpmCcConstants.TPM_CC_NV_ReadPublic:
            {
                uint nvIndex = reader.ReadUInt32();
                if((byte)(nvIndex >> 24) != (byte)TpmHt.TPM_HT_NV_INDEX)
                {
                    //TPM2_NV_ReadPublic() (Table 251) declares nvIndex as its sole handle: index 0.
                    malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

                    return false;
                }

                handles = ImmutableArray.Create(new TpmHandle(nvIndex));

                return true;
            }

            //TPM2_SignSequenceStart() (Table 87), TPM2_VerifySequenceStart() (Table 89), TPM2_VerifySignature()
            //(Table 116), TPM2_VerifyDigestSignature() (Table 120), TPM2_Encapsulate() (Table 60),
            //TPM2_MakeCredential() (Table 28) and TPM2_RSA_Encrypt() (Table 44) each carry exactly one handle
            //with no '@' decoration (Auth Index None) typed TPMI_DH_OBJECT, the same interface type and
            //no-authorization posture as TPM2_ReadPublic()'s own handle — so this case block shares
            //IsWithinDhObjectRange with it too: a type octet outside the transient/persistent range is a
            //handle-area syntax failure (TPM_RC_VALUE), judged here before any authorization area is read (TPM
            //2.0 Library Part 3, clause 5.4, step 1). A well-typed but undefined or wrong-object handle still
            //answers TPM_RC_HANDLE (or, for the three that special-case an open sequence, TPM_RC_KEY) at Name
            //resolution, mirroring each plain transition's own gate exactly.
            case TpmCcConstants.TPM_CC_SignSequenceStart:
            case TpmCcConstants.TPM_CC_VerifySequenceStart:
            case TpmCcConstants.TPM_CC_VerifySignature:
            case TpmCcConstants.TPM_CC_VerifyDigestSignature:
            case TpmCcConstants.TPM_CC_Encapsulate:
            case TpmCcConstants.TPM_CC_MakeCredential:
            case TpmCcConstants.TPM_CC_RSA_Encrypt:
            {
                uint keyHandle = reader.ReadUInt32();
                if(!IsWithinDhObjectRange(keyHandle))
                {
                    //Each of these seven commands' own table (Tables 87, 89, 116, 120, 60, 28, 44) declares
                    //this handle as its sole handle, Auth Index None: index 0.
                    malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

                    return false;
                }

                handles = ImmutableArray.Create(new TpmHandle(keyHandle));

                return true;
            }

            default:
            {
                throw new InvalidOperationException($"No no-authorization handle parse is defined for '{commandCode}'.");
            }
        }
    }

    /// <summary>
    /// Parses the handle area (when the command has one) and the authorization area shared by every
    /// no-authorization command admitted through the generic mechanism (TPM 2.0 Library Part 3, clause 4.3; Part
    /// 1, clause 15.6.1): 1-3 companion slots, since none of these commands has an <c>@</c>-marked handle for a
    /// slot to authorize (<c>authorizingCount: 0</c>) — and the raw parameter octets cpHash is computed over.
    /// The command's own parameter core is deliberately NOT run here, so the wrapper leaves with
    /// <see cref="TpmNoAuthOverSessionsRequested.Inner"/> unset: clause 5.5's session-area checks precede clause
    /// 5.8's parameter unmarshaling, so the command's own PARAMETERS — including a profile membership check
    /// (<c>TPM2_TestParms()</c>) or a content-dependent bound (<c>TPM2_StirRandom()</c>'s 128-octet MAX_SYM_DATA)
    /// — are never judged, or even decoded, before the area is known admissible. The core runs once every
    /// session has verified, through the parameter step (<see cref="ParseNoAuthInnerAsync"/>, or
    /// <see cref="DecryptFirstParameterAsync"/>'s wrapper arm after a claimed decrypt transform).
    /// </summary>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="commandCode">The command; must have a row in <see cref="TpmNoAuthSessionShape"/>.</param>
    /// <param name="pool">The memory pool the request's owned carriers are rented from.</param>
    /// <param name="input">The parsed request input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented authorization area and parameter-area carrier transfers to the constructed wrapper; the completing transition releases the area's credentials and the parameter area per carrier, and every refusing arm releases both through the wrapper's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParseNoAuthOverSessions(ref TpmReader reader, TpmCcConstants commandCode, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryParseNoAuthHandles(commandCode, ref reader, out ImmutableArray<TpmHandle> handles, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadAuthorizationAreaSpans(ref reader, authorizingCount: 0, out AuthorizationAreaSpans area, out malformedResponseCode))
        {
            return false;
        }

        //Captured before any attempt to interpret it, as cpHash's parameter term (Part 1, clause 15.7 equation
        //15) — the whole remaining command buffer, since no separate parameterSize field marks its boundary the
        //way the authorization area's own authorizationSize does (Part 3, clause 4.3).
        ReadOnlySpan<byte> rawParameterAreaOctets = reader.PeekBytes(reader.Remaining);

        TpmAuthorizationArea? authorizationArea = null;
        TpmParameterArea parameterArea = TpmParameterArea.Empty;
        try
        {
            authorizationArea = RentAuthorizationArea(in area, authorizingCount: 0, pool);
            parameterArea = TpmParameterArea.Create(rawParameterAreaOctets, pool);

            input = new TpmNoAuthOverSessionsRequested(commandCode, Inner: null, authorizationArea, parameterArea, handles);
        }
        catch
        {
            //These carriers' only owner is this frame until the wrapper adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            parameterArea.Dispose();
            authorizationArea?.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// Reads one <c>TPMS_AUTH_COMMAND</c> as spans over the command buffer — sessionHandle (UINT32), nonceCaller
    /// (TPM2B), sessionAttributes (BYTE), hmac (TPM2B) — for a parser that rents the slot's owning carriers as its
    /// last act, so the nonce and the credential reach the request through those carriers alone and never through
    /// an intermediate heap copy.
    /// </summary>
    /// <remarks>
    /// Both sized fields go through <see cref="TryReadSessionCredentialSpan"/>, so each carries the structural
    /// width rule of its own type ahead of its body-length check, and the same layout serves a password slot and
    /// a real session (Part 1, clause 16.6.4.1): the handle alone decides which. It is carried as read through
    /// <see cref="TpmiShAuthSession.FromValue"/>, leaving a handle outside the interface type's set (Part 2, clause
    /// 9.8, Table 54) to the consuming transition's response code rather than a parse-time exception. The reader is
    /// taken by reference so the returned spans, which alias the command buffer, are valid for the caller. A
    /// <c>TPM_RS_PW</c> handle carries the structural rules of Part 1, clause 15.6.4, Table 15, applied through the
    /// shared <see cref="TpmLifecycleTransitions.TryValidatePasswordSlot"/> at this slot's own index — the same one
    /// rule, at the same position, the reference's <c>RetrieveSessionData</c> applies to every slot it unmarshals.
    /// </remarks>
    /// <param name="reader">The reader positioned at the slot's sessionHandle.</param>
    /// <param name="sessionIndex">The slot's zero-based index in the authorization area, for the session-index-encoded response codes.</param>
    /// <param name="sessionHandle">The slot's session handle.</param>
    /// <param name="nonceCaller">The slot's caller nonce, aliasing the command buffer.</param>
    /// <param name="sessionAttributes">The slot's command session attributes (<c>TPMA_SESSION</c>, Part 2, clause 8.4, Table 38).</param>
    /// <param name="hmac">The slot's supplied <c>hmac</c> field, aliasing the command buffer.</param>
    /// <param name="malformedResponseCode">The response code a malformed frame answers with.</param>
    /// <returns><see langword="true"/> when the whole slot read cleanly.</returns>
    private static bool TryReadCommandSessionSpans(
        ref TpmReader reader, int sessionIndex, out TpmiShAuthSession sessionHandle, out ReadOnlySpan<byte> nonceCaller,
        out TpmaSession sessionAttributes, out ReadOnlySpan<byte> hmac, out TpmRcConstants malformedResponseCode)
    {
        sessionHandle = TpmiShAuthSession.FromValue(0);
        nonceCaller = ReadOnlySpan<byte>.Empty;
        sessionAttributes = default;
        hmac = ReadOnlySpan<byte>.Empty;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(uint))
        {
            //The slot's own sessionHandle field is the session area's field (Part 2, clause 6.6.2): a failure
            //reading it is attributed to this slot's index, the same designation TryValidatePasswordSlot
            //already carries for its own checks a few lines below.
            malformedResponseCode = SessionEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, sessionIndex);

            return false;
        }

        sessionHandle = TpmiShAuthSession.FromValue(reader.ReadUInt32());

        if(!TryReadSessionCredentialSpan(ref reader, sessionIndex, Tpm2bNonce.MaxSize, out nonceCaller, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Remaining < sizeof(byte))
        {
            //The slot's own sessionAttributes octet, same designation as the sessionHandle read above.
            malformedResponseCode = SessionEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, sessionIndex);

            return false;
        }

        sessionAttributes = (TpmaSession)reader.ReadByte();

        if(!TryReadSessionCredentialSpan(ref reader, sessionIndex, Tpm2bAuth.MaxSize, out hmac, out malformedResponseCode))
        {
            return false;
        }

        if(sessionHandle.IsPasswordSession
            && !TpmLifecycleTransitions.TryValidatePasswordSlot(sessionAttributes, nonceCaller.Length, sessionIndex, out malformedResponseCode))
        {
            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyCommandCode()</c> carries the policy session as a command handle with no authorization
    /// (Part 3, clause 23.4): handle area (policySession), then the parameter code (TPM_CC). Framed with no
    /// sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    private static bool TryParsePolicyCommandCode(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        //Handle area: policySession; then the parameter code (TPM_CC).
        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 160: policySession is TPM2_PolicyCommandCode()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 160: code is TPM2_PolicyCommandCode()'s sole parameter, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        var code = (TpmCcConstants)reader.ReadUInt32();

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmPolicyCommandCodeRequested(TpmiShPolicy.FromValue(policySession), code);

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyAuthValue()</c> carries only the policy session command handle with no parameters (Part 3,
    /// clause 23.18). Framed with no sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of
    /// range at unmarshal by <see cref="TryReadPolicySessionOnly"/>.
    /// </summary>
    private static bool TryParsePolicyAuthValue(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
