        {
            return false;
        }

        input = new TpmPolicyParametersRequested(TpmiShPolicy.FromValue(policySession), Tpm2bDigest.Create(digest, pool));

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyTemplate()</c> carries the policy session command handle then the parameter templateHash
    /// (<c>TPM2B_DIGEST</c>) (Part 3, clause 23.21, Table 180). Framed with no sessions. <c>policySession</c> is
    /// <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by <see cref="TryReadPolicySessionThenDigest"/>.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented digest carrier transfers to the constructed request input, whose consuming transition transfers it onto the policy session and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParsePolicyTemplate(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        if(!TryReadPolicySessionThenDigest(ref reader, out uint policySession, out ReadOnlySpan<byte> digest, out malformedResponseCode))
        {
            return false;
        }

        input = new TpmPolicyTemplateRequested(TpmiShPolicy.FromValue(policySession), Tpm2bDigest.Create(digest, pool));

        return true;
    }

    /// <summary>
    /// The shared body of the four digest-latching policy commands: the policy session command handle — read
    /// through <see cref="TryReadPolicySessionHandle"/>, refusing an out-of-range value at unmarshal — then
    /// one <c>TPM2B_DIGEST</c> parameter bounded by <c>sizeof(TPMU_HA)</c> (Part 2, clause 10.3.2, Table 90), then
    /// nothing. The digest's equality with the session's own digest width is the transition's rule (it needs the
    /// session), not the parser's.
    /// </summary>
    private static bool TryReadPolicySessionThenDigest(ref TpmReader reader, out uint policySession, out ReadOnlySpan<byte> digest, out TpmRcConstants malformedResponseCode)
    {
        digest = ReadOnlySpan<byte>.Empty;

        if(!TryReadPolicySessionHandle(ref reader, out policySession, out malformedResponseCode))
        {
            //Every caller (TPM2_PolicyCpHash Table 164, TPM2_PolicyNameHash Table 166, TPM2_PolicyParameters
            //Table 187, TPM2_PolicyTemplate Table 180) declares policySession as its sole handle, index 0 —
            //invariant across every caller, so it is encoded here rather than at each call site.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out digest, out malformedResponseCode))
        {
            //The digest (cpHashA / nameHash / pHash / templateHash) is each caller's sole parameter, index 0
            //— invariant the same way, encoded here rather than at each call site.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(reader.Remaining != 0)
        {
            //Bare: the whole-area trailing-octets check, the same class as TryReadPolicySessionOnly's own
            //(CommandDispatcher's "nothing more was declared" check), not attributable to the digest field.
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyLocality()</c> carries the policy session command handle then the one-octet
    /// <c>TPMA_LOCALITY</c> parameter (Part 3, clause 23.8, Table 154; Part 2, clause 8.5, Table 39). Framed with
    /// no sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>; every octet value of the locality parameter itself is
    /// well-formed at unmarshal, and the zero-selection and type rules are the transition's (they need the
    /// session's prior setting).
    /// </summary>
    private static bool TryParsePolicyLocality(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 154: policySession is TPM2_PolicyLocality()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 154: locality is TPM2_PolicyLocality()'s sole parameter, index 0.
        if(reader.Remaining < sizeof(byte))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        byte locality = reader.ReadByte();

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmPolicyLocalityRequested(TpmiShPolicy.FromValue(policySession), locality);

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyNvWritten()</c> carries the policy session command handle then the one-octet
    /// <c>TPMI_YES_NO</c> parameter (Part 3, clause 23.20, Table 178; Part 2, clause 9.2, Table 48: <c>NO</c> is 0,
    /// <c>YES</c> is 1, and any other octet fails the unmarshal with <c>TPM_RC_VALUE</c>). Framed with no
    /// sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    private static bool TryParsePolicyNvWritten(ref TpmReader reader, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 178: policySession is TPM2_PolicyNvWritten()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 178: writtenSet is TPM2_PolicyNvWritten()'s sole parameter, index 0.
        if(reader.Remaining < sizeof(byte))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        byte writtenSet = reader.ReadByte();

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        if(writtenSet > 1)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }

        input = new TpmPolicyNvWrittenRequested(TpmiShPolicy.FromValue(policySession), writtenSet == 1);

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyAuthorizeNV()</c> carries three handles — <c>@authHandle</c> (authorized, USER role),
    /// <c>nvIndex</c>, and <c>policySession</c> — a one-slot password authorization area, and no parameters (Part 3,
    /// clause 23.22, Table 182). The read authorization is required even for a trial session, so the tag must be
    /// <c>TPM_ST_SESSIONS</c>. <c>policySession</c>, the third handle, is <c>TPMI_SH_POLICY</c>, refused out of
    /// range at unmarshal by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented password carrier transfers to the constructed request input, whose consuming transition disposes it once the read authorization has consumed it and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParsePolicyAuthorizeNv(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Table 182: authHandle then nvIndex, each field's own shortfall designated to its own index — a buffer
        //wide enough for authHandle alone designates nvIndex, not authHandle.
        if(!TryReadHandle(ref reader, 0, out uint authHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 1, out uint nvIndex, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 182: authHandle (index 0), nvIndex (index 1), policySession is the THIRD handle, index 2.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 2);

            return false;
        }

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmPolicyAuthorizeNvRequested(
            TpmiRhNvAuth.FromValue(authHandle), Tpm2bAuth.Create(suppliedAuth, pool), TpmiRhNvIndex.FromValue(nvIndex), TpmiShPolicy.FromValue(policySession));

        return true;
    }

    /// <summary>
    /// Reads one <c>TPMI_SH_POLICY</c> handle-area field, refusing a value outside the policy session range at
    /// unmarshal. TPM 2.0 Library Part 2, clause 9.10, Table 56 states <c>{POLICY_SESSION_FIRST:
    /// POLICY_SESSION_LAST}</c> as the "range of policy authorization session handles" and
    /// <c>#TPM_RC_VALUE</c> as the "error returned if the handle is out of range" — mirroring
    /// <see cref="IsWithinDhObjectRange"/>'s bare <c>TPM_RC_VALUE</c> shape for an out-of-range
    /// <c>TPMI_DH_OBJECT</c>. Every <c>TPM2_Policy*()</c> parser reads its <c>policySession</c> (or, for
    /// <c>TPM2_PolicyRestart()</c>, its <c>sessionHandle</c>) field through this helper — directly, or through
    /// <see cref="TryReadPolicySessionOnly"/> or <see cref="TryReadPolicySessionThenDigest"/> — at whichever
    /// position the field occupies in that command's own handle area.
    /// </summary>
    /// <param name="reader">The reader positioned at the 4-octet handle field.</param>
    /// <param name="sessionHandle">The parsed raw handle value on success.</param>
    /// <param name="malformedResponseCode">The response code to return when the field fails to unmarshal.</param>
    /// <returns><see langword="true"/> when the field unmarshals to a value within the policy session range; otherwise <see langword="false"/>.</returns>
    private static bool TryReadPolicySessionHandle(ref TpmReader reader, out uint sessionHandle, out TpmRcConstants malformedResponseCode)
    {
        sessionHandle = 0;

        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        sessionHandle = reader.ReadUInt32();

        if(!TpmiShPolicy.IsPolicySession(sessionHandle))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_VALUE;

            return false;
        }

        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// Reads the single policy-session handle-area field of a parameterless <c>TPM2_Policy*()</c> command
    /// through <see cref="TryReadPolicySessionHandle"/> (refusing an out-of-range value at unmarshal) and
    /// confirms no octet follows it.
    /// </summary>
    /// <remarks>
    /// The trailing-octet check stays bare: it is a whole-area "nothing more was declared" structural check,
    /// not attributable to any one field, matching the reference's own <c>CommandDispatcher</c> "trailing
    /// octets" check (<c>command->parameterSize != 0</c> once every declared parameter has unmarshaled) — the
    /// same class of check, applied here to a command with no parameters at all.
    /// </remarks>
    /// <param name="reader">The reader positioned at the 4-octet handle.</param>
    /// <param name="policySession">The parsed raw handle value on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the handle unmarshals within range and no octet follows it; otherwise <see langword="false"/>.</returns>
    private static bool TryReadPolicySessionOnly(ref TpmReader reader, out uint policySession, out TpmRcConstants malformedResponseCode)
    {
        if(!TryReadPolicySessionHandle(ref reader, out policySession, out malformedResponseCode))
        {
            //Every caller of this reader (TPM2_PolicyAuthValue, TPM2_PolicyGetDigest, TPM2_PolicyPassword,
            //TPM2_PolicyRestart — Part 3, clause 23.18 and clause 11.2, Table 16) declares policySession as
            //its sole handle, handle-area index 0, so the index is invariant across every caller and is
            //encoded here rather than at each call site (CommandDispatcher.c's ParseHandleBuffer() mechanism:
            //any handle-area unmarshal failure is H-encoded).
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(reader.Remaining != 0)
        {
            //Bare: a whole-area "nothing more was declared" structural check, not attributable to the
            //handle field itself — matching the reference's own CommandDispatcher trailing-octets check
            //(command->parameterSize != 0 once every declared parameter has unmarshaled), applied here to a
            //command with no parameters at all.
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyPCR()</c> carries the policy session command handle then the parameters pcrDigest
    /// (TPM2B_DIGEST) and pcrs (TPML_PCR_SELECTION, the final parameter, decoded into an owned carrier that
    /// folds into the policyDigest through its own <c>WriteTo</c>) (Part 3, clause 23.7). Framed with no
    /// sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    /// <remarks>
    /// <c>pcrs</c> is read the <c>TPM2_Quote()</c> idiom (<see cref="TryParseQuote"/>): a by-value probe through
    /// <see cref="TrySkipPcrSelection"/> answers a truncated or over-bound list before any rental, then
    /// <see cref="TpmlPcrSelection.Parse"/> decodes it.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented digest and selection carriers transfers to the constructed request input, whose asserting transition is their terminal owner on every arm and releases them through the input's own Dispose.")]
    private static bool TryParsePolicyPcr(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        //Handle area: policySession, refused out of range at unmarshal by TryReadPolicySessionHandle.
        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 152: policySession is TPM2_PolicyPCR()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: pcrDigest (TPM2B_DIGEST) — the expected PCR digest.
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> pcrDigest, out malformedResponseCode))
        {
            //Table 152: pcrDigest is TPM2_PolicyPCR()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_DIGEST buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.2,
        //Table 90), so the wire bound is answered here, ahead of the rental whose Create refuses the same bound
        //by throwing. Table 152: pcrDigest is the first parameter, index 0.
        if(pcrDigest.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameter: pcrs (TPML_PCR_SELECTION) — the final parameter, decoded into an owned carrier so the
        //transition can shape it into the clause-23.7 pcrs term (masked to the implemented PCR on a real
        //session, left as sent on a trial one) and the fold can re-marshal exactly that term.
        TpmReader probe = reader;
        if(!TrySkipPcrSelection(ref probe, out malformedResponseCode))
        {
            //Table 152: pcrs is TPM2_PolicyPCR()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        if(probe.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        TpmlPcrSelection pcrSelection;
        try
        {
            pcrSelection = TpmlPcrSelection.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            //A list naming more banks than HASH_COUNT selections is out of the structure's declared bound
            //(Part 2, clause 10.8.7, Table 128: #TPM_RC_SIZE). Table 152: pcrs is TPM2_PolicyPCR()'s second
            //parameter, index 1 — the probe above already refuses this width, so this is the fail-closed
            //backstop rather than the answering layer.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            //A selection whose sizeofSelect lies outside PCR_SELECT_MIN..PCR_SELECT_MAX is out of the member's
            //own declared bounds (Part 2, clause 10.5.2, Table 107: #TPM_RC_VALUE). The probe above already
            //refuses that width, so this is the fail-closed backstop rather than the answering layer. Table 152:
            //pcrs is TPM2_PolicyPCR()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 1);

            return false;
        }

        //The owned pooled digest carrier is rented here, the parse's last act after every wire check has passed,
        //so no refused parse ever creates one.
        input = new TpmPolicyPcrRequested(TpmiShPolicy.FromValue(policySession), Tpm2bDigest.Create(pcrDigest, pool), pcrSelection);

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyOR()</c> carries the policy session command handle then the parameter pHashList
    /// (TPML_DIGEST: a UINT32 count followed by that many TPM2B digests, the final parameter) (Part 3, clause
    /// 23.6). Framed with no sessions. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at
    /// unmarshal by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    /// <remarks>
    /// The branch count is bounded explicitly against Part 3, clause 23.6's own two-to-eight range before the
    /// branch list is pre-sized to it, so an out-of-range count answers <c>TPM_RC_SIZE</c> before any
    /// allocation rather than running the buffer out from an over-large declared count.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of every branch rented in the loop transfers into the adopted list, and from there into the constructed request input, whose accepting arm transfers it into the fold action and whose refusing arms dispose it through the input's own Dispose; a branch refusal after earlier ones succeeded releases every digest already rented in the loop before returning false.")]
    private static bool TryParsePolicyOr(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 150: policySession is TPM2_PolicyOR()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Table 150: pHashList is TPM2_PolicyOR()'s sole parameter, index 0.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint count = reader.ReadUInt32();

        //TPM2_PolicyOR's pHashList carries at least two and at most eight digests (Part 3, clause 23.6); a count
        //outside that range is a malformed command, not an assertion the simulator should fold (a trial session
        //would otherwise silently accept an empty or single-branch list and produce a nonstandard digest).
        const uint MinPolicyOrBranches = 2;
        const uint MaxPolicyOrBranches = 8;
        if(count < MinPolicyOrBranches || count > MaxPolicyOrBranches)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        var branches = new List<Tpm2bDigest>((int)count);
        for(uint i = 0; i < count; i++)
        {
            //Each branch is a TPM2B_DIGEST, so its declared size is checked against sizeof(TPMU_HA) (TPM 2.0
            //Library Part 2, clause 10.3.2, Table 90) BEFORE the remaining-buffer comparison — a branch that is
            //both over-bound and truncated answers the bound rather than the truncation. The bounded span rents
            //its own pooled digest immediately, so a later branch's refusal has every earlier one to release.
            if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> branchSpan, out malformedResponseCode))
            {
                ReleaseBranches(branches);

                //Table 150: pHashList is TPM2_PolicyOR()'s sole parameter, index 0 — invariant regardless of
                //which list branch failed, since Table 15 designates the command's own parameter, not a
                //position inside a variable-length list.
                malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

                return false;
            }

            branches.Add(Tpm2bDigest.Create(branchSpan, pool));
        }

        if(reader.Remaining != 0)
        {
            ReleaseBranches(branches);
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The branch list adopts every digest already rented above, transferring ownership without a second
        //pooled copy; this is the parse's last act, so no refused parse ever creates one.
        input = new TpmPolicyOrRequested(TpmiShPolicy.FromValue(policySession), TpmlDigest.Adopt(branches));

        return true;

        //Releases every digest rented so far in the branch loop, for a refusal that must leave none orphaned.
        static void ReleaseBranches(List<Tpm2bDigest> rented)
        {
            foreach(Tpm2bDigest digest in rented)
            {
                digest.Dispose();
            }
        }
    }

    /// <summary>
    /// Parses a TPM2_PolicySecret() command (TPM 2.0 Library Part 3, clause 23.4). <c>policySession</c>, the
    /// second handle, is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    /// <remarks>
    /// TPM2_PolicySecret() is authorized on the entity being consulted, so its wire layout after the header is:
    /// handle area (authHandle, policySession — only authHandle requires authorization), authorization area (a
    /// single session), then parameters (nonceTPM as TPM2B_NONCE, cpHashA as TPM2B_DIGEST, policyRef as
    /// TPM2B_NONCE, expiration as INT32). The authorization area's TPMS_AUTH_COMMAND wire shape is identical
    /// whether the session is <c>TPM_RS_PW</c>, an HMAC session, or a POLICY session (sessionHandle ‖ nonceCaller ‖
    /// sessionAttributes ‖ hmac — <c>TryReadPasswordSessionBody</c>'s <c>TPM_RS_PW</c> gate is the only
    /// difference), so <c>TryReadCommandSessionSpans</c> reads it generically (Part 3, clause 23.4.1: "A password
    /// session, an HMAC session, or a policy session ... will satisfy this requirement") and the parsed
    /// sessionHandle alone decides which record this becomes — the transition, not the parser, resolves whether a
    /// non-password handle names a real HMAC or POLICY session.
    /// </remarks>
    /// <param name="reader">The wire reader positioned after the command header.</param>
    /// <param name="tag">The command's structure tag.</param>
    /// <param name="pool">The memory pool the request's owned carriers are rented from.</param>
    /// <param name="input">The parsed <see cref="TpmPolicySecretRequested"/> or <see cref="TpmPolicySecretOverSessionRequested"/> input on success.</param>
    /// <param name="malformedResponseCode">The response code to return when parsing fails.</param>
    /// <returns><see langword="true"/> when the command parses successfully; otherwise <see langword="false"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented cpHashA, policyRef, caller-supplied nonceTPM and session-slot carriers transfers to the constructed request input, whose post-authorization ladder is their terminal owner — the caller of that ladder compares and releases the nonceTPM, and the slot's caller nonce transfers into the response-framing action — and whose refusing arms dispose them through the input's own Dispose; a rent that fails after an earlier carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParsePolicySecret(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: authHandle (the authorized entity) then policySession (the command handle, no
        //authorization, refused out of range at unmarshal by TryReadPolicySessionHandle). Table 146: a short
        //buffer cannot even read authHandle, the first (index 0) handle.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint authHandle = reader.ReadUInt32();

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 146: authHandle is index 0, policySession is the SECOND handle, index 1.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 1);

            return false;
        }

        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadCommandSessionSpans(ref reader, sessionIndex: 0, out TpmiShAuthSession sessionHandle, out ReadOnlySpan<byte> nonceCaller, out TpmaSession sessionAttributes, out ReadOnlySpan<byte> hmac, out malformedResponseCode))
        {
            return false;
        }

        if(!TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        //PolicySecret's entire parameter set (nonceTPM ‖ cpHashA ‖ policyRef ‖ expiration) is every octet left
        //after the authorization area — captured verbatim, before any field is decoded, as the HMAC/POLICY
        //arm's cpHash parameter term (Part 1, clause 15.7 equation 15); unused by the password arm.
        ReadOnlySpan<byte> rawParameterAreaOctets = reader.PeekBytes(reader.Remaining);

        //Parameter: nonceTPM (TPM2B_NONCE).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> nonceTpm, out malformedResponseCode))
        {
            //Table 146: nonceTPM is TPM2_PolicySecret()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, page 134, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, page 134, which bounds that
        //structure's buffer); the carrier's Create refuses the same bound by throwing, so the wire answer is
        //given here, ahead of the rental and ahead of any session-state comparison.
        //Table 146: nonceTPM is the first parameter, index 0.
        if(nonceTpm.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameter: cpHashA (TPM2B_DIGEST).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> cpHashA, out malformedResponseCode))
        {
            //Table 146: cpHashA is TPM2_PolicySecret()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //A TPM2B_DIGEST buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.2,
        //Table 90), so the wire bound is answered here, ahead of the rental whose Create refuses the same bound
        //by throwing. The transition's own "exactly the session's digest width" check stays as the backstop.
        //Table 146: cpHashA is the second parameter, index 1.
        if(cpHashA.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        //Parameter: policyRef (TPM2B_NONCE).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> policyRef, out malformedResponseCode))
        {
            //Table 146: policyRef is TPM2_PolicySecret()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, which bounds that structure's
        //buffer); the carrier's Create refuses the same bound by throwing, so the wire answer is given here.
        //Table 146: policyRef is the third parameter, index 2.
        if(policyRef.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 2);

            return false;
        }

        //Parameter: expiration (INT32). Table 146: expiration is the fourth parameter, index 3.
        if(reader.Remaining < sizeof(int))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

            return false;
        }

        int expiration = reader.ReadInt32();

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //A TPM_RS_PW session's hmac field is the plaintext supplied authValue (TryReadPasswordSessionBody's own
        //convention, mirrored here since the wire read is shared). The owned pooled carriers are rented here,
        //the parse's last act after every wire check has passed, so no refused parse ever creates one. A
        //TPM_RS_PW slot carries no caller nonce at all (its width rule already refused a non-empty one), so its
        //rental resolves to the dispose-immune empty sentinel without a special case.
        Tpm2bDigest suppliedCpHash = Tpm2bDigest.Empty;
        Tpm2bNonce suppliedPolicyRef = Tpm2bNonce.Empty;
        Tpm2bNonce suppliedNonceTpm = Tpm2bNonce.Empty;
        Tpm2bNonce slotNonce = Tpm2bNonce.Empty;
        Tpm2bAuth slotCredential = Tpm2bAuth.Empty;
        TpmParameterArea parameterArea = TpmParameterArea.Empty;
        try
        {
            suppliedCpHash = Tpm2bDigest.Create(cpHashA, pool);
            suppliedPolicyRef = Tpm2bNonce.Create(policyRef, pool);
            suppliedNonceTpm = Tpm2bNonce.Create(nonceTpm, pool);
            slotNonce = Tpm2bNonce.Create(nonceCaller, pool);
            slotCredential = Tpm2bAuth.Create(hmac, pool);
            parameterArea = sessionHandle.IsPasswordSession ? TpmParameterArea.Empty : TpmParameterArea.Create(rawParameterAreaOctets, pool);

            input = sessionHandle.IsPasswordSession
                ? new TpmPolicySecretRequested(TpmiDhEntity.FromValue(authHandle), TpmiShPolicy.FromValue(policySession), slotCredential, suppliedNonceTpm, suppliedCpHash, suppliedPolicyRef, expiration)
                : new TpmPolicySecretOverSessionRequested(
                    TpmiDhEntity.FromValue(authHandle), TpmiShPolicy.FromValue(policySession), sessionHandle, slotNonce, sessionAttributes, slotCredential, parameterArea,
                    suppliedNonceTpm, suppliedCpHash, suppliedPolicyRef, expiration);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            parameterArea.Dispose();
            slotCredential.Dispose();
            slotNonce.Dispose();
            suppliedNonceTpm.Dispose();
            suppliedPolicyRef.Dispose();
            suppliedCpHash.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicySigned()</c> authorizes neither handle (Auth Index: None for both authObject and
    /// policySession, TPM 2.0 Library Part 3, Table 144), so its wire layout after the header is: handle area
    /// (authObject, policySession — 2 handles, no authorization area at all, <c>TPM_ST_NO_SESSIONS</c> exactly
    /// like <c>TPM2_VerifySignature()</c>), then parameters (nonceTPM as TPM2B_NONCE, cpHashA as TPM2B_DIGEST,
    /// policyRef as TPM2B_NONCE, expiration as INT32, auth as TPMT_SIGNATURE). <c>policySession</c>, the second
    /// handle, is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by
    /// <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    /// <remarks>
    /// The <c>auth</c> parameter's <c>sigAlg</c> selector gate (<c>TPM_RC_SCHEME</c>) is inline here, exactly as
    /// <see cref="TryParseVerifySignature"/>'s is; the post-gate <c>TPMT_SIGNATURE</c> body is the SAME shared
    /// helper both parsers call, <see cref="TryParseTpmtSignatureBody"/> (Part 3, clause 23.3).
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented cpHashA and policyRef carriers transfers to the constructed request input, whose consuming transition transfers them into the verification action and whose refusing arms dispose them through the input's own Dispose; a rent that fails after the first carrier already succeeded releases it in the catch before rethrowing.")]
    private static bool TryParsePolicySigned(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_NO_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_BAD_TAG;

            return false;
        }

        //Handle area: authObject (validates the signature) then policySession (the session being extended,
        //refused out of range at unmarshal by TryReadPolicySessionHandle). Table 144: authObject is the first
        //(index 0) handle.
        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        uint authObject = reader.ReadUInt32();

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 144: authObject is index 0, policySession is the SECOND handle, index 1.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //Parameter: nonceTPM (TPM2B_NONCE).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> nonceTpm, out malformedResponseCode))
        {
            //Table 144: nonceTPM is TPM2_PolicySigned()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, page 134, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, page 134, which bounds that
        //structure's buffer); the carrier's Create refuses the same bound by throwing, so the wire answer is
        //given here, ahead of the rental and ahead of any session-state comparison.
        //Table 144: nonceTPM is the first parameter, index 0.
        if(nonceTpm.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameter: cpHashA (TPM2B_DIGEST). Bound-first against sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause
        //10.3.2, Table 90), matching the shared TPMT_SIGNATURE body this parse delegates to below — a cpHashA
        //that is both over-bound and truncated answers TPM_RC_SIZE, never TPM_RC_INSUFFICIENT. The transition's
        //own "exactly the session's digest width" check stays as the backstop.
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bDigest.MaxSize, out ReadOnlySpan<byte> cpHashA, out malformedResponseCode))
        {
            //Table 144: cpHashA is TPM2_PolicySigned()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //Parameter: policyRef (TPM2B_NONCE). Bound-first against sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause
        //10.3.4, Table 92, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, which bounds that
        //structure's buffer), for the same over-bound-and-truncated priority as cpHashA above.
        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bNonce.MaxSize, out ReadOnlySpan<byte> policyRef, out malformedResponseCode))
        {
            //Table 144: policyRef is TPM2_PolicySigned()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        //Parameter: expiration (INT32). Table 144: expiration is the fourth parameter, index 3.
        if(reader.Remaining < sizeof(int))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

            return false;
        }

        int expiration = reader.ReadInt32();

        //Parameter: auth (TPMT_SIGNATURE) — sigAlg (TPMI_ALG_SIG_SCHEME) selects the union member; the gate stays
        //inline, mirroring TryParseVerifySignature's. Table 144: auth is the fifth parameter, index 4.
        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 4);

            return false;
        }

        TpmiAlgSigScheme sigAlg = TpmiAlgSigScheme.FromValue((TpmAlgIdConstants)reader.ReadUInt16());
        if(sigAlg.Value is not (TpmAlgIdConstants.TPM_ALG_ECDSA or TpmAlgIdConstants.TPM_ALG_RSASSA or TpmAlgIdConstants.TPM_ALG_RSAPSS))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SCHEME, 4);

            return false;
        }

        //The post-gate TPMT_SIGNATURE body (hashAlg plus the sigAlg-selected member) is the shared helper's job;
        //it rents the pooled signature carrier as its own last act.
        if(!TryParseTpmtSignatureBody(ref reader, sigAlg, pool, out TpmtSignature? signature, out malformedResponseCode))
        {
            //Table 144: auth is TPM2_PolicySigned()'s fifth parameter, index 4.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 4);

            return false;
        }

        //auth is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            signature.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled carriers are rented here, the parse's last act after every wire check has passed, so no
        //refused parse ever creates one.
        Tpm2bDigest suppliedCpHash = Tpm2bDigest.Empty;
        Tpm2bNonce suppliedPolicyRef = Tpm2bNonce.Empty;
        Tpm2bNonce suppliedNonceTpm = Tpm2bNonce.Empty;
        try
        {
            suppliedCpHash = Tpm2bDigest.Create(cpHashA, pool);
            suppliedPolicyRef = Tpm2bNonce.Create(policyRef, pool);
            suppliedNonceTpm = Tpm2bNonce.Create(nonceTpm, pool);
            input = new TpmPolicySignedRequested(
                TpmiDhObject.FromValue(authObject), TpmiShPolicy.FromValue(policySession), suppliedNonceTpm, suppliedCpHash,
                suppliedPolicyRef, expiration, sigAlg, TpmiAlgHash.FromValue(signature.Signature.HashAlgorithm), signature);
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            signature.Dispose();
            suppliedNonceTpm.Dispose();
            suppliedPolicyRef.Dispose();
            suppliedCpHash.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyAuthorize()</c> carries a single command handle (policySession, no authorization — mirrors
    /// <c>TPM2_PolicyCommandCode()</c>/<c>TPM2_PolicyPCR()</c>/<c>TPM2_PolicyOR()</c>, none of which check the
    /// tag either), so its wire layout after the header is: handle area (policySession), then parameters
    /// (approvedPolicy as TPM2B_DIGEST, policyRef as TPM2B_NONCE, keySign as TPM2B_NAME, checkTicket as
    /// TPMT_TK_VERIFIED: tag, hierarchy, [tag]metadata present only for TPM_ST_DIGEST_VERIFIED, hmac as
    /// TPM2B_DIGEST) (Part 3, clause 23.16; Part 2, clause 10.6.4, Table 111; clause 10.6.5, Table 113). <c>policySession</c> is
    /// <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented approvedPolicy, policyRef, keySign, and checkTicket digest carriers transfers to the constructed request input, whose trial arm transfers them into the policyDigest fold and whose non-trial arm transfers them into the re-verification action, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after earlier carriers already succeeded releases those in the catch before rethrowing.")]
    private static bool TryParsePolicyAuthorize(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 170: policySession is TPM2_PolicyAuthorize()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> approvedPolicy, out malformedResponseCode))
        {
            //Table 170: approvedPolicy is TPM2_PolicyAuthorize()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_DIGEST buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.2,
        //Table 90), so the wire bound is answered here, ahead of the rental whose Create refuses the same bound
        //by throwing. The transition's own equality check against the session's digest stays as the backstop.
        //Table 170: approvedPolicy is the first parameter, index 0.
        if(approvedPolicy.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> policyRef, out malformedResponseCode))
        {
            //Table 170: policyRef is TPM2_PolicyAuthorize()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, which bounds that structure's
        //buffer); the carrier's Create refuses the same bound by throwing, so the wire answer is given here.
        //Table 170: policyRef is the second parameter, index 1.
        if(policyRef.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> keySign, out malformedResponseCode))
        {
            //Table 170: keySign is TPM2_PolicyAuthorize()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        //A TPM2B_NAME's content is bounded by sizeof(TPMU_NAME) — a 2-octet nameAlg plus the widest digest
        //(TPM 2.0 Library Part 2, clause 10.4.3, Table 105; the reference enforces it in TPM2B_NAME_Unmarshal),
        //so an oversized keySign is refused here rather than reaching the carrier's own throwing bound. The
        //transition's own nameAlg/width checks stay as the fail-closed backstop. Table 170: keySign is the
        //third parameter, index 2.
        if(keySign.Length > Tpm2bName.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 2);

            return false;
        }

        //checkTicket (TPMT_TK_VERIFIED): tag (UINT16) + hierarchy (UINT32) + [tag]metadata (UINT16, present only
        //for TPM_ST_DIGEST_VERIFIED) + hmac (TPM2B_DIGEST). All three selector fields are constrained at the wire
        //read, because that is what the command asks for: "The unmarshaling process requires that a proper
        //TPMT_TK_VERIFIED be provided for checkTicket but it may be a NULL Ticket" (Part 3, clause 23.16, printed
        //page 247). The NULL form is <tag, TPM_RH_NULL, 0x0000> for any of Table 112's three tags (Part 2, clause
        //10.6.5, Table 113), so every gate below admits it.
        //Table 170: checkTicket is the fourth parameter, index 3 — every field below belongs to it.
        if(reader.Remaining < sizeof(ushort) + sizeof(uint))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

            return false;
        }

        //TPMT_TK_VERIFIED.tag admits exactly Table 112's three values — TPM_ST_VERIFIED (TPM2_VerifySignature()),
        //TPM_ST_MESSAGE_VERIFIED (TPM2_VerifySequenceComplete()), TPM_ST_DIGEST_VERIFIED
        //(TPM2_VerifyDigestSignature(), Part 3 clause 23.16.2's preferred producer) — any other value is
        //#TPM_RC_TAG (Part 2, Table 113: "error returned when tag is not one of the values in Table 112"). The
        //re-verification recompute has no tag-legality check of its own — it hashes whatever tag this reader
        //hands it — so this gate is the only place the constraint holds.
        ushort checkTicketTag = reader.ReadUInt16();
        bool isCheckTicketTagAdmitted = checkTicketTag switch
        {
            (ushort)TpmStConstants.TPM_ST_VERIFIED or (ushort)TpmStConstants.TPM_ST_MESSAGE_VERIFIED or (ushort)TpmStConstants.TPM_ST_DIGEST_VERIFIED => true,
            _ => false
        };
        if(!isCheckTicketTagAdmitted)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_TAG, 3);

            return false;
        }

        //TPMT_TK_VERIFIED.hierarchy is TPMI_RH_HIERARCHY+ (Part 2, Table 113), so the admitted set is the
        //interface type's own (clause 9.13, Table 59) and a value outside it is TPM_RC_VALUE. The predicate is
        //read from the type rather than restated here, so the admitted set is stated in exactly one place.
        uint checkTicketHierarchy = reader.ReadUInt32();
        if(!TpmiRhHierarchy.IsHierarchy(checkTicketHierarchy))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 3);

            return false;
        }

        //[tag]metadata (Table 111, TPMU_TK_VERIFIED_META): present only for TPM_ST_DIGEST_VERIFIED, where it is a
        //TPMI_ALG_HASH with no NULL admission — an unrecognized value is TPM_RC_HASH, mirroring
        //TpmiAlgHash.Parse's own gate. The two TPMS_EMPTY arms (TPM_ST_VERIFIED, TPM_ST_MESSAGE_VERIFIED) carry no
        //metadata octets at all.
        TpmiAlgHash? checkTicketMetadata = null;
        if(checkTicketTag == (ushort)TpmStConstants.TPM_ST_DIGEST_VERIFIED)
        {
            if(reader.Remaining < sizeof(ushort))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 3);

                return false;
            }

            var checkTicketMetadataAlg = (TpmAlgIdConstants)reader.ReadUInt16();
            if(!TpmiAlgHash.IsAlgHash(checkTicketMetadataAlg))
            {
                malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_HASH, 3);

                return false;
            }

            checkTicketMetadata = TpmiAlgHash.FromValue(checkTicketMetadataAlg);
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> checkTicketDigest, out malformedResponseCode))
        {
            //Table 170: the ticket's digest is a field of TPM2_PolicyAuthorize()'s fourth parameter, index 3.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 3);

            return false;
        }

        //The ticket's own digest is a TPM2B_DIGEST too (Part 2, clause 10.6.5, Table 113), so it takes the same
        //sizeof(TPMU_HA) bound ahead of its rental. Table 170: it is a field of the fourth parameter, index 3.
        if(checkTicketDigest.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 3);

            return false;
        }

        //checkTicket is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled carriers are rented here, the parse's last act after every wire check has passed, so no
        //refused parse ever creates one.
        Tpm2bDigest suppliedApprovedPolicy = Tpm2bDigest.Empty;
        Tpm2bNonce suppliedPolicyRef = Tpm2bNonce.Empty;
        Tpm2bName suppliedKeySign = Tpm2bName.Empty;
        try
        {
            suppliedApprovedPolicy = Tpm2bDigest.Create(approvedPolicy, pool);
            suppliedPolicyRef = Tpm2bNonce.Create(policyRef, pool);
            suppliedKeySign = Tpm2bName.Create(keySign, pool);
            input = new TpmPolicyAuthorizeRequested(
                TpmiShPolicy.FromValue(policySession), suppliedApprovedPolicy, suppliedPolicyRef, suppliedKeySign,
                (TpmStConstants)checkTicketTag, TpmiRhHierarchy.FromValue(checkTicketHierarchy), checkTicketMetadata,
                Tpm2bDigest.Create(checkTicketDigest, pool));
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            suppliedKeySign.Dispose();
            suppliedPolicyRef.Dispose();
            suppliedApprovedPolicy.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyTicket()</c> carries the policy session command handle (no authorization — Auth Index:
    /// None, TPM 2.0 Library Part 3, Table 148), so its wire layout after the header is: handle area
    /// (policySession), then parameters (timeout as TPM2B_TIMEOUT, cpHashA as TPM2B_DIGEST, policyRef as
    /// TPM2B_NONCE, authName as TPM2B_NAME, ticket as TPMT_TK_AUTH: tag, hierarchy, digest as TPM2B_DIGEST)
    /// (Part 3, clause 23.5). <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal
    /// by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The generic TPM2B_TIMEOUT length rule ("8 or less", Part 2, Table 98) is answered HERE, at the wire
    /// read, ahead of the carrier rental whose <c>Create</c> refuses the same bound by throwing — the same
    /// placement the reference's own <c>TPM2B_TIMEOUT_Unmarshal</c> gives it, which is before any command body
    /// runs. The command-specific "exactly 8" rule is a separate, tighter check and stays in the transition,
    /// where it runs after the trial-session rejection: Part 4's <c>TPM2_PolicyTicket()</c>
    /// puts <c>if(session->attributes.isTrialPolicy) return TPM_RCS_ATTRIBUTES + RC_PolicyTicket_policySession;</c>
    /// ahead of <c>if(in->timeout.t.size != sizeof(UINT64)) return TPM_RCS_SIZE + RC_PolicyTicket_timeout;</c>.
    /// </para>
    /// <para>
    /// TPMT_TK_AUTH.tag legality (<c>TPM_ST_AUTH_SIGNED</c> or <c>TPM_ST_AUTH_SECRET</c> only — Part 2, Table
    /// 111: "TPM_RC_TAG error returned when tag is not TPM_ST_AUTH_*") IS enforced here, at the wire reader: the
    /// re-verification recompute has no independent tag-legality check of its own (an illegal tag would still
    /// recompute a comparable HMAC, since both sides would hash the caller's own bogus tag), so the wire-level
    /// gate is the only place that constraint is actually enforced. TPMT_TK_AUTH.hierarchy is typed
    /// TPMI_RH_HIERARCHY+ (Part 2, Table 114: {TPM_RH_OWNER, TPM_RH_PLATFORM, TPM_RH_ENDORSEMENT, TPM_RH_NULL},
    /// TPM_RC_VALUE otherwise) and is constrained to that legal set here for the identical reason — the
    /// re-verification recompute derives whatever proof the caller's hierarchy names with no legality check of
    /// its own (<c>TicketComputeAuth</c>'s own contract: the caller's claim is exactly what is being checked).
    /// </para>
    /// <para>
    /// authName has no TPM2B_NAME size bound of its own in the reference (<c>TPM2B_NAME_Unmarshal</c> bounds it
    /// to <c>sizeof(TPMU_NAME)</c>); this reader applies the same bound using this simulator's own widest
    /// modelled Name (2-octet nameAlg plus the widest supported digest, SHA-512) so a caller cannot shift the
    /// cpHash/policyRef/authName split across the un-length-prefixed equation-12 concatenation
    /// (<c>WriteAuthTicketMessage</c>) by supplying an oversized authName.
    /// </para>
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented timeout, cpHashA, policyRef, authName, and ticket-digest carriers transfers to the constructed request input, whose consuming transition transfers them into the re-verification action, and whose refusing arms dispose them through the input's own Dispose; a rent that fails after earlier carriers already succeeded releases those in the catch before rethrowing.")]
    private static bool TryParsePolicyTicket(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 148: policySession is TPM2_PolicyTicket()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> timeout, out malformedResponseCode))
        {
            //Table 148: timeout is TPM2_PolicyTicket()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //A TPM2B_TIMEOUT buffer is bounded by sizeof(UINT64) (Part 2, clause 10.3.10, Table 98), the bound the
        //reference's own unmarshal applies before any command body runs; the carrier's Create refuses the same
        //bound by throwing, so the wire answer is given here.
        //Table 148: timeout is the first parameter, index 0.
        if(timeout.Length > Tpm2bTimeout.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> cpHashA, out malformedResponseCode))
        {
            //Table 148: cpHashA is TPM2_PolicyTicket()'s second parameter, index 1.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 1);

            return false;
        }

        //A TPM2B_DIGEST buffer can be no wider than sizeof(TPMU_HA) (Part 2, clause 10.3.2, Table 90); the
        //transition's own "exactly the session's digest width" check stays as the backstop. Table 148: cpHashA
        //is the second parameter, index 1.
        if(cpHashA.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 1);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> policyRef, out malformedResponseCode))
        {
            //Table 148: policyRef is TPM2_PolicyTicket()'s third parameter, index 2.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 2);

            return false;
        }

        //A TPM2B_NONCE buffer can be no wider than sizeof(TPMU_HA) (TPM 2.0 Library Part 2, clause 10.3.4, Table
        //92, which types it as a TPM2B_DIGEST, and clause 10.3.2, Table 90, which bounds that structure's
        //buffer); the carrier's Create refuses the same bound by throwing, so the wire answer is given here.
        //Table 148: policyRef is the third parameter, index 2.
        if(policyRef.Length > Tpm2bNonce.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 2);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> authName, out malformedResponseCode))
        {
            //Table 148: authName is TPM2_PolicyTicket()'s fourth parameter, index 3.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 3);

            return false;
        }

        //Table 148: authName is the fourth parameter, index 3.
        if(authName.Length > Tpm2bName.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 3);

            return false;
        }

        //ticket (TPMT_TK_AUTH): tag (UINT16) + hierarchy (UINT32) + digest (TPM2B_DIGEST). Table 148: ticket is
        //the fifth parameter, index 4 — every field below belongs to it.
        if(reader.Remaining < sizeof(ushort) + sizeof(uint))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 4);

            return false;
        }

        ushort ticketTag = reader.ReadUInt16();
        if(ticketTag != (ushort)TpmStConstants.TPM_ST_AUTH_SIGNED && ticketTag != (ushort)TpmStConstants.TPM_ST_AUTH_SECRET)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_TAG, 4);

            return false;
        }

        //TPMT_TK_AUTH.hierarchy is TPMI_RH_HIERARCHY+ (Part 2, clause 10.6.6, Table 114), so the admitted set is
        //the interface type's own (clause 9.13, Table 59) and a value outside it is TPM_RC_VALUE. The predicate
        //is read from the type rather than restated here, so the admitted set is stated in exactly one place.
        uint ticketHierarchy = reader.ReadUInt32();
        if(!TpmiRhHierarchy.IsHierarchy(ticketHierarchy))
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 4);

            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> ticketDigest, out malformedResponseCode))
        {
            //Table 148: the ticket's digest is a field of TPM2_PolicyTicket()'s fifth parameter, index 4.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 4);

            return false;
        }

        //The ticket's own digest is a TPM2B_DIGEST (Part 2, clause 10.6.6, Table 114), so it takes the same
        //sizeof(TPMU_HA) bound ahead of its rental. Table 148: it is a field of the fifth parameter, index 4.
        if(ticketDigest.Length > Tpm2bDigest.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 4);

            return false;
        }

        //ticket is the final parameter; no octets may follow it (Part 3, clause 5.8.2, Table 2).
        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //The owned pooled carriers are rented here, the parse's last act after every wire check has passed, so no
        //refused parse ever creates one.
        Tpm2bTimeout suppliedTimeout = Tpm2bTimeout.Empty;
        Tpm2bDigest suppliedCpHash = Tpm2bDigest.Empty;
        Tpm2bNonce suppliedPolicyRef = Tpm2bNonce.Empty;
        Tpm2bName suppliedAuthName = Tpm2bName.Empty;
        try
        {
            suppliedTimeout = Tpm2bTimeout.Create(timeout, pool);
            suppliedCpHash = Tpm2bDigest.Create(cpHashA, pool);
            suppliedPolicyRef = Tpm2bNonce.Create(policyRef, pool);
            suppliedAuthName = Tpm2bName.Create(authName, pool);
            input = new TpmPolicyTicketRequested(
                TpmiShPolicy.FromValue(policySession), suppliedTimeout, suppliedCpHash, suppliedPolicyRef, suppliedAuthName,
                ticketTag, TpmiRhHierarchy.FromValue(ticketHierarchy), Tpm2bDigest.Create(ticketDigest, pool));
        }
        catch
        {
            //These carriers' only owner is this frame until the request adopts them, so a failing later rent
            //must release them or the pinned rentals are orphaned.
            suppliedAuthName.Dispose();
            suppliedPolicyRef.Dispose();
            suppliedCpHash.Dispose();
            suppliedTimeout.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyNV()</c> is authorized on the entity used to read the Index, so its wire layout after the
    /// header is: handle area (authHandle, nvIndex, policySession — only authHandle requires authorization),
    /// authorization area (a single password session), then parameters (operandB as TPM2B_OPERAND, offset as
    /// UINT16, operation as TPM_EO) (Part 3, clause 23.9). <c>policySession</c>, the third handle, is
    /// <c>TPMI_SH_POLICY</c>, refused out of range at unmarshal by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented authorization-password carrier transfers to the constructed request input, whose consuming transition releases it once the authorization arm has consumed it, and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParsePolicyNv(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_MISSING;

            return false;
        }

        //Handle area: authHandle, nvIndex, then policySession (the command handle, no authorization, refused
        //out of range at unmarshal by TryReadPolicySessionHandle). Table 156: authHandle then nvIndex, each
        //field's own shortfall designated to its own index — a buffer wide enough for authHandle alone
        //designates nvIndex, not authHandle.
        if(!TryReadHandle(ref reader, 0, out uint authHandle, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadHandle(ref reader, 1, out uint nvIndex, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 156: authHandle (index 0), nvIndex (index 1), policySession is the THIRD handle, index 2.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 2);

            return false;
        }

        if(!TryReadPasswordAuthArea(ref reader, out ReadOnlySpan<byte> suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        //Parameter: operandB (TPM2B_OPERAND).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> operandB, out malformedResponseCode))
        {
            //Table 156: operandB is TPM2_PolicyNV()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //TPM2B_OPERAND is "size limited to the same as the digest structure" (Part 2, clause 10.3.6, Table 94),
        //so its buffer is bounded by sizeof(TPMU_HA) exactly as a TPM2B_DIGEST is (Table 90). The bound is
        //answered here, ahead of the rental, because the carrier factory throws above it. Table 156: operandB
        //is the first parameter, index 0.
        if(operandB.Length > Tpm2bOperand.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameters: offset (UINT16) then operation (TPM_EO, UINT16), each field's own shortfall designated
        //to its own index (Table 156) — offset is the second parameter, index 1, and operation the third,
        //index 2.
        if(!TryReadUInt16Parameter(ref reader, 1, out ushort offset, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadUInt16Parameter(ref reader, 2, out ushort operation, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //TPM_EO carries only 12 defined values (Part 2, clause 6.8, Table 20); an undefined value is rejected here,
        //at unmarshal (Part 3, clause 5.1), so a REAL session's TpmEoComparator.TryEvaluate and a TRIAL session's
        //unconditional fold reject an invalid operation identically, rather than the real session throwing while the
        //trial session silently folds it. Table 156: operation is the third parameter, index 2.
        if(!((TpmEoConstants)operation).IsDefined())
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 2);

            return false;
        }

        //The request, with its owned password and operand carriers, is constructed as the parse's last act, so no
        //refused parse ever creates one; the password is rented first and released if the operand's rental fails.
        Tpm2bAuth suppliedPassword = Tpm2bAuth.Create(suppliedAuth, pool);
        try
        {
            input = new TpmPolicyNvRequested(
                TpmiRhNvAuth.FromValue(authHandle), suppliedPassword, TpmiRhNvIndex.FromValue(nvIndex),
                TpmiShPolicy.FromValue(policySession), Tpm2bOperand.Create(operandB, pool), offset, operation);
        }
        catch
        {
            suppliedPassword.Dispose();
            throw;
        }

        return true;
    }

    /// <summary>
    /// <c>TPM2_PolicyCounterTimer()</c> carries the policy session command handle (no authorization, so
    /// <c>TPM_ST_NO_SESSIONS</c>) followed by operandB (TPM2B_OPERAND), offset (UINT16), and operation (TPM_EO,
    /// UINT16) — Part 3, clause 23.10. <c>policySession</c> is <c>TPMI_SH_POLICY</c>, refused out of range at
    /// unmarshal by <see cref="TryReadPolicySessionHandle"/>.
    /// </summary>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parse-rented comparison operand transfers to the constructed request input, whose consuming transition hands it to the shared policy-digest fold and whose refusing arms dispose it through the input's own Dispose.")]
    private static bool TryParsePolicyCounterTimer(ref TpmReader reader, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;

        //Handle area: policySession (the command handle, no authorization, refused out of range at unmarshal
        //by TryReadPolicySessionHandle).
        if(!TryReadPolicySessionHandle(ref reader, out uint policySession, out malformedResponseCode))
        {
            //Table 158: policySession is TPM2_PolicyCounterTimer()'s sole handle, index 0.
            malformedResponseCode = HandleEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //Parameter: operandB (TPM2B_OPERAND).
        if(!TryReadTpm2bSpan(ref reader, out ReadOnlySpan<byte> operandB, out malformedResponseCode))
        {
            //Table 158: operandB is TPM2_PolicyCounterTimer()'s first parameter, index 0.
            malformedResponseCode = ParameterEncodedRc(malformedResponseCode, 0);

            return false;
        }

        //TPM2B_OPERAND is "size limited to the same as the digest structure" (Part 2, clause 10.3.6, Table 94),
        //so its buffer is bounded by sizeof(TPMU_HA) exactly as a TPM2B_DIGEST is (Table 90). The bound is
        //answered here, ahead of the rental, because the carrier factory throws above it. Table 158: operandB
        //is the first parameter, index 0.
        if(operandB.Length > Tpm2bOperand.MaxSize)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }

        //Parameters: offset (UINT16) then operation (TPM_EO, UINT16), each field's own shortfall designated
        //to its own index (Table 158) — offset is the second parameter, index 1, and operation the third,
        //index 2.
        if(!TryReadUInt16Parameter(ref reader, 1, out ushort offset, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadUInt16Parameter(ref reader, 2, out ushort operation, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        //TPM_EO carries only 12 defined values (Part 2, clause 6.8, Table 20); an undefined value is rejected here,
        //at unmarshal (Part 3, clause 5.1), so a REAL session's TpmEoComparator.TryEvaluate and a TRIAL session's
        //unconditional fold reject an invalid operation identically, rather than the real session throwing while the
        //trial session silently folds it. Table 158: operation is the third parameter, index 2.
        if(!((TpmEoConstants)operation).IsDefined())
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 2);

            return false;
        }

        //The request, with its owned operand carrier, is constructed as the parse's last act, so no refused parse
        //ever creates one.
        input = new TpmPolicyCounterTimerRequested(TpmiShPolicy.FromValue(policySession), Tpm2bOperand.Create(operandB, pool), offset, operation);

        return true;
    }

    /// <summary>
    /// <c>TPM2_FlushContext()</c> takes no handles and no authorization (Part 3, clause 28.4): its wire body
    /// after the header is a single flushHandle (TPMI_DH_CONTEXT) parameter, framed with no sessions. "No
    /// sessions of any type are allowed with this command and tag is required to be TPM_ST_NO_SESSIONS" (TPM 2.0
    /// Library Part 3, clause 28.4.1), so a <c>TPM_ST_SESSIONS</c>-tagged arrival is refused before the handle is
    /// even read — the same tag gate <see cref="TryParseContextSave"/> applies.
    /// <c>flushHandle</c> unmarshals through <see cref="TpmiDhContext.Parse"/>, exactly as
    /// <see cref="TryParseContextSave"/>'s <c>saveHandle</c> does: an out-of-range value (outside Table 57's
    /// HMAC-session, policy-session and transient ranges) throws <see cref="InvalidOperationException"/>, mapped
    /// to Table 57's <c>#TPM_RC_VALUE</c> (TPM 2.0 Library Part 2, clause 9.11); a short read throws
    /// <see cref="ArgumentOutOfRangeException"/>, mapped to <c>TPM_RC_INSUFFICIENT</c>.
    /// </summary>
    /// <param name="reader">The reader positioned at the handle area.</param>
    /// <param name="tag">The command tag read from the header.</param>
    /// <param name="input">The parsed request on success.</param>
    /// <param name="malformedResponseCode">The refusal code on failure.</param>
    /// <returns><see langword="true"/> when the command parsed.</returns>
    private static bool TryParseFlushContext(ref TpmReader reader, ushort tag, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_NO_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_BAD_TAG;

            return false;
        }

        //Table 228: flushHandle is a PARAMETER on the wire ("NOTE This is a use of a handle as a parameter"),
        //TPM2_FlushContext()'s sole parameter, index 0 — not a handle-area field.
        TpmiDhContext flushHandle;
        try
        {
            flushHandle = TpmiDhContext.Parse(ref reader);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmFlushContextRequested(flushHandle);

        return true;
    }

    /// <summary>
    /// Parses <c>TPM2_ContextSave()</c>'s <c>TPM_ST_NO_SESSIONS</c> form (TPM 2.0 Library Part 3, clause 28.2.2,
    /// Table 224): a single handle-area handle, no parameters. "No authorization sessions of any type are
    /// allowed with this command and tag is required to be TPM_ST_NO_SESSIONS", so a <c>TPM_ST_SESSIONS</c>-tagged
    /// arrival is refused before the handle is even read.
    /// </summary>
    /// <remarks>
    /// <c>saveHandle</c> unmarshals through <see cref="TpmiDhContext.Parse"/>, exactly as
    /// <see cref="TryParseFlushContext"/>'s own <c>flushHandle</c> does: an out-of-range value throws
    /// <see cref="InvalidOperationException"/>, mapped to Table 57's
    /// <c>#TPM_RC_VALUE</c>; a short read throws <see cref="ArgumentOutOfRangeException"/> from
    /// <see cref="TpmReader.ReadUInt32"/>'s own <c>BinaryPrimitives</c> call, mapped to <c>TPM_RC_INSUFFICIENT</c>.
    /// A trailing octet after the handle is <c>TPM_RC_SIZE</c>.
    /// </remarks>
    /// <param name="reader">The reader positioned at the handle area.</param>
    /// <param name="tag">The command tag read from the header.</param>
    /// <param name="input">The parsed request on success.</param>
    /// <param name="malformedResponseCode">The refusal code on failure.</param>
    /// <returns><see langword="true"/> when the command parsed.</returns>
    private static bool TryParseContextSave(ref TpmReader reader, ushort tag, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_NO_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_BAD_TAG;

            return false;
        }

        //Table 224: saveHandle is under the Handles heading, TPM2_ContextSave()'s sole handle, index 0 — unlike
        //TPM2_FlushContext()'s flushHandle, which Table 228 explicitly notes is a parameter.
        TpmiDhContext saveHandle;
        try
        {
            saveHandle = TpmiDhContext.Parse(ref reader);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        if(reader.Remaining != 0)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmContextSaveRequested(saveHandle);

        return true;
    }

    /// <summary>
    /// Parses <c>TPM2_ContextLoad()</c>'s <c>TPM_ST_NO_SESSIONS</c> form (TPM 2.0 Library Part 3, clause 28.3.2,
    /// Table 226): no handle area, one parameter — the whole <c>TPMS_CONTEXT</c>. "This command is used to
    /// reload a context that has been saved by TPM2_ContextSave(). No authorization sessions of any type are
    /// allowed with this command and tag is required to be TPM_ST_NO_SESSIONS", so a <c>TPM_ST_SESSIONS</c>-tagged
    /// arrival is refused before anything else is read.
    /// </summary>
    /// <remarks>
    /// The four fields are read separately, rather than through <see cref="TpmsContext.Parse"/>, so each
    /// channel's refusal maps to its own code: a short <c>sequence</c> is <c>TPM_RC_INSUFFICIENT</c> straight
    /// from <see cref="TpmReader.ReadUInt64"/>'s own <c>BinaryPrimitives</c> call; an out-of-range
    /// <c>savedHandle</c> or <c>hierarchy</c> is <c>TPM_RC_VALUE</c> (Part 2, clause 14.6.2; Table 58; Table 59); and
    /// <c>contextBlob</c>'s own <see cref="Tpm2bContextData.Parse"/> answers <c>TPM_RC_INSUFFICIENT</c> for a
    /// declared size the frame cannot cover — the only refusal reachable from this field over the wire, since
    /// <see cref="Tpm2bContextData.MaxSize"/> is itself the declared size's <c>UINT16</c> ceiling. The
    /// <see cref="InvalidOperationException"/> arm behind <c>TPM_RC_SIZE</c> stands for a narrower ceiling than
    /// that <c>UINT16</c> width, should one ever be declared. A trailing octet after the blob is
    /// <c>TPM_RC_SIZE</c>, and the parsed <see cref="TpmsContext"/> is built only once every field has
    /// succeeded — the last rental of the parse, mirroring every other structure-parameter parser in this file.
    /// </remarks>
    /// <param name="reader">The reader positioned at the parameter area.</param>
    /// <param name="tag">The command tag read from the header.</param>
    /// <param name="pool">The memory pool <c>contextBlob</c>'s carrier is rented from.</param>
    /// <param name="input">The parsed request on success.</param>
    /// <param name="malformedResponseCode">The refusal code on failure.</param>
    /// <returns><see langword="true"/> when the command parsed.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "Ownership of the parsed TpmsContext (and the ContextBlob rental it wraps) transfers to the constructed TpmContextLoadRequested, whose effect is its terminal owner on acceptance and whose own Dispose releases it on every refusing path reached after this method returns.")]
    private static bool TryParseContextLoad(ref TpmReader reader, ushort tag, BaseMemoryPool pool, [NotNullWhen(true)] out TpmSimulatorInput? input, out TpmRcConstants malformedResponseCode)
    {
        input = null;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(tag != (ushort)TpmStConstants.TPM_ST_NO_SESSIONS)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_BAD_TAG;

            return false;
        }

        //Table 226: context (TPMS_CONTEXT) is TPM2_ContextLoad()'s sole parameter, index 0 — every field below
        //(sequence, savedHandle, hierarchy, contextBlob) belongs to it, not to a handle area (Table 226 declares
        //none), matching TPM2_FlushContext()'s own "handle used as a parameter" trap.
        ulong sequence;
        try
        {
            sequence = reader.ReadUInt64();
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        TpmiDhSaved savedHandle;
        try
        {
            savedHandle = TpmiDhSaved.Parse(ref reader);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        TpmiRhHierarchy hierarchy;
        try
        {
            hierarchy = TpmiRhHierarchy.Parse(ref reader);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_VALUE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        Tpm2bContextData contextBlob;
        try
        {
            contextBlob = Tpm2bContextData.Parse(ref reader, pool);
        }
        catch(InvalidOperationException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_SIZE, 0);

            return false;
        }
        catch(ArgumentOutOfRangeException)
        {
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, 0);

            return false;
        }

        if(reader.Remaining != 0)
        {
            contextBlob.Dispose();
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        input = new TpmContextLoadRequested(new TpmsContext(sequence, savedHandle, hierarchy, contextBlob));

        return true;
    }

    /// <summary>
    /// Skips a <c>TPML_PCR_SELECTION</c> (UINT32 count + count selections of UINT16 hash + BYTE sizeofSelect +
    /// select), answering the structure's own response codes for a malformed one.
    /// </summary>
    /// <remarks>
    /// The list's own two bounds are both enforced here, each at the point the reference unmarshaler enforces it:
    /// <c>count</c> against <see cref="TpmlPcrSelection.MaxSelections"/> (Table 128's <c>#TPM_RC_SIZE</c>,
    /// "response code when count is greater than the possible number of banks", checked immediately after
    /// <c>count</c> is read and BEFORE any element is walked, TPM 2.0 Library Part 2, clause 10.8.7), then each
    /// selection's <c>sizeofSelect</c> against <see cref="TpmlPcrSelection.PcrSelectMin"/>..
    /// <see cref="TpmlPcrSelection.PcrSelectMax"/> (Table 107's <c>#TPM_RC_VALUE</c>, TPM 2.0 Library Part 2,
    /// clause 10.5.2; the widths themselves are clause 10.5.1's equations 1 and 2). Both run on a by-value reader
    /// copy before anything is rented, so a list that is both over-bound and truncated answers the count bound
    /// rather than a truncation further in. <see cref="TpmlPcrSelection.Parse"/> keeps its own two guards as the
    /// fail-closed backstop, so each response code has exactly one origin while the structure still refuses to
    /// rent for a shape it cannot hold.
    /// </remarks>
    /// <param name="reader">The reader positioned at the list's <c>count</c>.</param>
    /// <param name="malformedResponseCode">The response code for a malformed list; meaningless when this returns <see langword="true"/>.</param>
    /// <returns><see langword="true"/> when a well-formed list was skipped.</returns>
    private static bool TrySkipPcrSelection(ref TpmReader reader, out TpmRcConstants malformedResponseCode)
    {
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        uint count = reader.ReadUInt32();
        if(count > TpmlPcrSelection.MaxSelections)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        for(uint i = 0; i < count; i++)
        {
            if(reader.Remaining < sizeof(ushort) + sizeof(byte))
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

                return false;
            }

            _ = reader.ReadUInt16();
            byte sizeofSelect = reader.ReadByte();
            if(sizeofSelect < TpmlPcrSelection.PcrSelectMin || sizeofSelect > TpmlPcrSelection.PcrSelectMax)
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_VALUE;

                return false;
            }

            if(reader.Remaining < sizeofSelect)
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

                return false;
            }

            reader.Skip(sizeofSelect);
        }

        return true;
    }

    /// <summary>
    /// Reads a command authorization area carrying a single password session and yields the supplied
    /// authorization value (the hmac field, which for a <c>TPM_RS_PW</c> session is the plaintext authValue).
    /// </summary>
    /// <remarks>
    /// Only password sessions are modelled: an HMAC or policy session is not. The reader is
    /// taken by reference so the returned span, which aliases the command buffer, is valid for the caller,
    /// which rents the owning carrier as its own last act. Composes <see cref="TryBeginAuthArea"/> and
    /// <see cref="TryEndAuthArea"/> — bare by design, both preceding or bounding the per-slot walk rather than
    /// naming a slot — with <see cref="TryReadPasswordSessionBody"/>, which session-index-encodes its own
    /// slot's failures; this method introduces no bare site of its own.
    /// </remarks>
    /// <param name="reader">The reader positioned at the authorizationSize field.</param>
    /// <param name="suppliedAuth">The supplied authorization value, aliasing the command buffer.</param>
    /// <param name="malformedResponseCode">The response code for a malformed area; meaningless when this returns <see langword="true"/>.</param>
    /// <returns><see langword="true"/> when a well-formed password authorization area was read.</returns>
    private static bool TryReadPasswordAuthArea(ref TpmReader reader, out ReadOnlySpan<byte> suppliedAuth, out TpmRcConstants malformedResponseCode)
    {
        suppliedAuth = ReadOnlySpan<byte>.Empty;

        if(!TryBeginAuthArea(ref reader, out int sessionsStart, out uint authorizationSize, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadPasswordSessionBody(ref reader, out suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        return TryEndAuthArea(ref reader, sessionsStart, authorizationSize, out malformedResponseCode);
    }

    /// <summary>
    /// Reads the authorizationSize (UINT32) field that opens an authorization area and marks where the sessions
    /// begin, so the caller can confirm the sessions account for exactly the declared octets.
    /// </summary>
    /// <remarks>
    /// Both of its own refusals stay bare: this field, and the sanity check on its declared value, precede the
    /// per-slot walk entirely, so neither can be attributed to a handle, session, or parameter yet (Table 15's
    /// closing sentence, TPM 2.0 Library Part 2, clause 6.6.2). The reference's own <c>authSize</c> sanity
    /// check in <c>ExecCommand</c> answers the same condition bare, before <c>ParseHandleBuffer</c>'s
    /// field-by-field walk ever begins.
    /// </remarks>
    private static bool TryBeginAuthArea(ref TpmReader reader, out int sessionsStart, out uint authorizationSize, out TpmRcConstants malformedResponseCode)
    {
        sessionsStart = 0;
        authorizationSize = 0;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(uint))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        authorizationSize = reader.ReadUInt32();
        if(authorizationSize > (uint)reader.Remaining)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTHSIZE;

            return false;
        }

        //The smallest well-formed block is a session handle, an empty nonce, the attributes octet, and an
        //empty hmac (Part 3, clause 5.5, step 3.1: an authorizationSize below it is TPM_RC_AUTHSIZE; Part 4
        //ExecCommand refuses the same size before the area is ever walked). Bare, per this method's own doc
        //remarks.
        if(authorizationSize < MinimumAuthorizationSize)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTHSIZE;

            return false;
        }

        sessionsStart = reader.Consumed;

        return true;
    }

    /// <summary>
    /// The smallest an authorization area can be: one block holding a session handle (UINT32), an empty
    /// nonceCaller (its 2-octet size alone), the <c>sessionAttributes</c> octet, and an empty hmac (its 2-octet
    /// size alone) — TPM 2.0 Library Part 3, clause 5.5, step 3.1.
    /// </summary>
    private const int MinimumAuthorizationSize = sizeof(uint) + sizeof(ushort) + sizeof(byte) + sizeof(ushort);

    /// <summary>
    /// Confirms the sessions consumed exactly the declared authorization octets; any surplus means additional
    /// or oversized sessions the fixed session count here does not model — TPM 2.0 Library Part 3, clause
    /// 5.5, step 4.3: "If the maximum allowed number of sessions have been unmarshaled and fewer octets than
    /// indicated in authorizationSize were unmarshaled (that is, authorizationSize is too large), the TPM
    /// shall return TPM_RC_AUTHSIZE." Part 4's <c>RetrieveSessionData</c> answers this same condition with a
    /// session-indexed <c>TPM_RC_SIZE</c> at the slot beyond the fixed count and never cites
    /// <c>TPM_RC_AUTHSIZE</c> for it; this model follows Part 3's own clause, which states the bare code (a
    /// recorded divergence).
    /// </summary>
    private static bool TryEndAuthArea(ref TpmReader reader, int sessionsStart, uint authorizationSize, out TpmRcConstants malformedResponseCode)
    {
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Consumed - sessionsStart != (int)authorizationSize)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTHSIZE;

            return false;
        }

        return true;
    }

    /// <summary>
    /// Reads one <c>TPMS_AUTH_COMMAND</c> password session — sessionHandle (UINT32, must be <c>TPM_RS_PW</c>) +
    /// nonceCaller (TPM2B) + sessionAttributes (BYTE) + hmac (TPM2B) — and yields the supplied authorization
    /// value (the hmac field, which for a <c>TPM_RS_PW</c> session is the plaintext authValue).
    /// </summary>
    /// <remarks>
    /// The two rules that hold for a <c>TPM_RS_PW</c> slot on structure alone are answered here, where the slot's
    /// kind is already known and no lookup has happened yet — the position the reference gives them in
    /// <c>RetrieveSessionData</c> — through the shared
    /// <see cref="TpmLifecycleTransitions.TryValidatePasswordSlot"/>, which is the one place they are stated
    /// (TPM 2.0 Library Part 1, clause 15.6.4, Table 15). Both refusals are session-index-encoded to
    /// <paramref name="sessionIndex"/> — slot 0 for every single-authorization command, slot 1 when a caller reads
    /// a second password slot (<c>TPM2_EventSequenceComplete()</c>). The two sized fields carry the width rule of their own
    /// types ahead of that, through <see cref="TryReadSessionCredentialSpan"/>: a password slot's <c>hmac</c> is the same <c>TPM2B_AUTH</c> wire
    /// field a real session's credential is (Part 2, clause 10.12.2, Table 156), so it takes the same bound.
    /// </remarks>
    /// <param name="reader">The reader positioned at the session's handle.</param>
    /// <param name="suppliedAuth">The supplied authorization value, aliasing the command buffer; the caller rents the owning carrier as its own last act.</param>
    /// <param name="malformedResponseCode">The response code for a malformed session; meaningless when this returns <see langword="true"/>.</param>
    /// <param name="sessionIndex">The zero-based position of the slot being read, for the session-index encoding of its refusals.</param>
    /// <returns><see langword="true"/> when a well-formed password session was read.</returns>
    private static bool TryReadPasswordSessionBody(ref TpmReader reader, out ReadOnlySpan<byte> suppliedAuth, out TpmRcConstants malformedResponseCode, int sessionIndex = 0)
    {
        suppliedAuth = ReadOnlySpan<byte>.Empty;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(uint))
        {
            //The slot's own sessionHandle field, session-index-encoded (Part 2, clause 6.6.2) the same as
            //TryReadCommandSessionSpans's identical read for a real session slot.
            malformedResponseCode = SessionEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, sessionIndex);

            return false;
        }

        TpmiShAuthSession sessionHandle = TpmiShAuthSession.FromValue(reader.ReadUInt32());
        if(!sessionHandle.IsPasswordSession)
        {
            //TPM_RC_AUTH_TYPE is RC_VER1 (TpmRcConstants.cs), a format-zero code with no P/N field to carry a
            //designation (Part 2, clause 6.6.1) — it stays bare regardless of which slot names the wrong type.
            malformedResponseCode = TpmRcConstants.TPM_RC_AUTH_TYPE;

            return false;
        }

        if(!TryReadSessionCredentialSpan(ref reader, sessionIndex, Tpm2bNonce.MaxSize, out ReadOnlySpan<byte> nonceCaller, out malformedResponseCode))
        {
            return false;
        }

        if(reader.Remaining < sizeof(byte))
        {
            //The slot's own sessionAttributes octet, same designation as the sessionHandle read above.
            malformedResponseCode = SessionEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, sessionIndex);

            return false;
        }

        var sessionAttributes = (TpmaSession)reader.ReadByte();

        if(!TryReadSessionCredentialSpan(ref reader, sessionIndex, Tpm2bAuth.MaxSize, out suppliedAuth, out malformedResponseCode))
        {
            return false;
        }

        return TpmLifecycleTransitions.TryValidatePasswordSlot(sessionAttributes, nonceCaller.Length, sessionIndex, out malformedResponseCode);
    }

    /// <summary>
    /// Answers the structural width rule of a session slot's <c>nonce</c> or <c>hmac</c> field, ahead of the
    /// field's own read: a declared size wider than the bound the caller names for that field is
    /// session-index-encoded <c>TPM_RC_SIZE</c>.
    /// </summary>
    /// <remarks>
    /// <para>
    /// <c>TPMS_AUTH_COMMAND</c> types both fields as sized buffers the hash union bounds — <c>nonce</c> is a
    /// <c>TPM2B_NONCE</c> and <c>hmac</c> a <c>TPM2B_AUTH</c> (TPM 2.0 Library Part 2, clause 10.12.2, Table
    /// 156), and both are <c>TPM2B_DIGEST</c> by definition (clause 10.3.4, Table 92 and clause 10.3.5, Table
    /// 93), so both carry clause 10.3.2's implied check: "As with all sized
    /// buffers, the size is checked to see if it is within the prescribed range. If not, the response code is
    /// TPM_RC_SIZE" (Table 90, page 134). Each field names its OWN carrier's bound —
    /// <see cref="Tpm2bNonce.MaxSize"/> for the nonce, <see cref="Tpm2bAuth.MaxSize"/> for the hmac — so the
    /// value this frame compares against is the one whose factory would refuse the same octets downstream, even
    /// though both resolve to <c>sizeof(TPMU_HA)</c>. The bound is the hash union's width and never the width of
    /// the session's own hash algorithm, which is a property of the session rather than of the wire structure.
    /// </para>
    /// <para>
    /// The check runs on a by-value probe of the reader, which leaves the reader itself untouched, so it lands
    /// BEFORE the field's body-length check and a slot declaring a size the command cannot carry is answered as
    /// an out-of-range size rather than as a truncated command. Answering the width first is also what keeps a
    /// malformed frame away from the authorization compare entirely: a credential no <c>TPM2B_AUTH</c> could
    /// hold is a marshalling refusal rather than a failed authorization, so it charges no dictionary-attack
    /// counter and touches no lockout state.
    /// </para>
    /// <para>
    /// The encoding is the session-area one every other per-slot refusal here uses (Part 2, clause 6.6.2),
    /// because the offending octets belong to a numbered session rather than to a command parameter.
    /// </para>
    /// </remarks>
    /// <param name="reader">The reader positioned at the field's size prefix; unchanged by this check.</param>
    /// <param name="sessionIndex">The slot's zero-based index in the authorization area, for the response encoding.</param>
    /// <param name="maxSize">The bound of the field's own carrier type in octets: <see cref="Tpm2bNonce.MaxSize"/> for a <c>nonce</c>, <see cref="Tpm2bAuth.MaxSize"/> for an <c>hmac</c>.</param>
    /// <param name="malformedResponseCode">The session-index-encoded response code when this returns <see langword="false"/>; meaningless otherwise.</param>
    /// <returns><see langword="true"/> when the declared width is admissible, or when the size prefix itself cannot be read, which the field's own read answers.</returns>
    private static bool TryValidateSessionCredentialWidth(ref TpmReader reader, int sessionIndex, int maxSize, out TpmRcConstants malformedResponseCode)
    {
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        TpmReader probe = reader;
        if(probe.Remaining < sizeof(ushort))
        {
            return true;
        }

        if(probe.ReadUInt16() > maxSize)
        {
            malformedResponseCode = SessionEncodedRc(TpmRcConstants.TPM_RC_SIZE, sessionIndex);

            return false;
        }

        return true;
    }

    /// <summary>
    /// Reads one session slot's <c>nonce</c> or <c>hmac</c> field as a span over the command buffer, with the
    /// width rule of <see cref="TryValidateSessionCredentialWidth"/> applied first.
    /// </summary>
    /// <param name="reader">The reader positioned at the field's size prefix.</param>
    /// <param name="sessionIndex">The slot's zero-based index in the authorization area, for the response encoding.</param>
    /// <param name="maxSize">The bound of the field's own carrier type in octets: <see cref="Tpm2bNonce.MaxSize"/> for a <c>nonce</c>, <see cref="Tpm2bAuth.MaxSize"/> for an <c>hmac</c>.</param>
    /// <param name="bytes">The octets, aliasing the command buffer.</param>
    /// <param name="malformedResponseCode">The response code a malformed field answers with.</param>
    /// <returns><see langword="true"/> when the field read cleanly.</returns>
    private static bool TryReadSessionCredentialSpan(ref TpmReader reader, int sessionIndex, int maxSize, out ReadOnlySpan<byte> bytes, out TpmRcConstants malformedResponseCode)
    {
        bytes = ReadOnlySpan<byte>.Empty;

        if(!TryValidateSessionCredentialWidth(ref reader, sessionIndex, maxSize, out malformedResponseCode))
        {
            return false;
        }

        if(!TryReadTpm2bSpan(ref reader, out bytes, out malformedResponseCode))
        {
            //TryReadTpm2bSpan is a shared wire primitive with no session context of its own (Part 3, clause
            //5.8.2, Table 2); this reader already knows the slot's index, so its bare TPM_RC_INSUFFICIENT is
            //re-designated here to the session area (Part 2, clause 6.6.2) — the same designation
            //TryValidateSessionCredentialWidth already carries for its own SIZE check above.
            malformedResponseCode = SessionEncodedRc(malformedResponseCode, sessionIndex);

            return false;
        }

        return true;
    }

    /// <summary>
    /// Reads one handle-area field as a raw 32-bit value, refusing with a designated
    /// <see cref="TpmRcConstants.TPM_RC_INSUFFICIENT"/> when the reader cannot carry it.
    /// </summary>
    /// <remarks>
    /// Most multi-handle command parsers in this file call this once per handle, immediately before that
    /// handle's own read, so a buffer wide enough for an earlier handle but not a later one designates the later
    /// handle's own index rather than the area's first slot — the reference's <c>CommandDispatcher.c</c>'s <c>ParseHandleBuffer()</c>
    /// increments its handle count before returning the failing handle's own index (TPM
    /// 2.0 Library Part 2, clause 6.6.2, Table 16: "Number of the handle, session, or parameter in error. The
    /// number is one based."). A handle whose own admitted range is narrower than a raw UINT32 is read through
    /// its own dedicated primitive instead — <see cref="TryReadPolicySessionHandle"/> for a trailing
    /// <c>policySession</c> (<see cref="TryParsePolicyAuthorizeNv"/>, <see cref="TryParsePolicyNv"/>) or
    /// <see cref="TpmiShHmac.Parse(ref TpmReader)"/> for a trailing HMAC-only session handle
    /// (<see cref="TryParseGetSessionAuditDigest"/>) — each still designating that handle's own index on
    /// failure, so the attribution this helper gives holds file-wide even at the sites that do not call it.
    /// </remarks>
    /// <param name="reader">The reader positioned at the handle.</param>
    /// <param name="index">The handle's zero-based position in the command's own handle-area table.</param>
    /// <param name="handle">The unmarshalled handle value on success.</param>
    /// <param name="malformedResponseCode">The handle-index-encoded refusal code on failure.</param>
    /// <returns><see langword="true"/> when the handle was read.</returns>
    private static bool TryReadHandle(ref TpmReader reader, int index, out uint handle, out TpmRcConstants malformedResponseCode)
    {
        if(reader.Remaining < sizeof(uint))
        {
            handle = 0;
            malformedResponseCode = HandleEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, index);

            return false;
        }

        handle = reader.ReadUInt32();
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// Reads one UINT32 parameter-area field, refusing with a designated <see cref="TpmRcConstants.TPM_RC_INSUFFICIENT"/>
    /// when the reader cannot carry it.
    /// </summary>
    /// <remarks>
    /// <see cref="TryParseGetCapabilityParameters"/> and <see cref="TryParseDictionaryAttackParameters"/> — the
    /// two bare-UINT32 parameter cores in this file (Part 3 Tables 238 and 212) — call this once per field,
    /// immediately before that field's own read, so a buffer wide enough for an earlier field but not a later one
    /// designates the later field's own index rather than the block's first field — the same attribution
    /// <see cref="TryReadHandle"/> gives the handle area, mirroring the reference's per-field parameter-unmarshal
    /// loop (TPM 2.0 Library Part 2, clause 6.6.2, Table 16's "N" field).
    /// </remarks>
    /// <param name="reader">The reader positioned at the parameter.</param>
    /// <param name="index">The parameter's zero-based position in the command's own parameter table.</param>
    /// <param name="value">The unmarshalled value on success.</param>
    /// <param name="malformedResponseCode">The parameter-index-encoded refusal code on failure.</param>
    /// <returns><see langword="true"/> when the parameter was read.</returns>
    private static bool TryReadUInt32Parameter(ref TpmReader reader, int index, out uint value, out TpmRcConstants malformedResponseCode)
    {
        if(reader.Remaining < sizeof(uint))
        {
            value = 0;
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, index);

            return false;
        }

        value = reader.ReadUInt32();
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// Reads one UINT16 parameter-area field, refusing with a designated <see cref="TpmRcConstants.TPM_RC_INSUFFICIENT"/>
    /// when the reader cannot carry it.
    /// </summary>
    /// <remarks>
    /// <see cref="TryParseNvRead"/> (Part 3 Table 265), <see cref="TryParseNvCertify"/> (Table 271),
    /// <see cref="TryParsePolicyNv"/> (Table 156), and <see cref="TryParsePolicyCounterTimer"/> (Table 158) each
    /// call this once per UINT16 field, immediately before that field's own read, so a buffer wide enough for an
    /// earlier field but not a later one designates the later field's own index rather than the pair's first
    /// slot — the same attribution <see cref="TryReadUInt32Parameter"/> gives its own UINT32 fields, mirroring
    /// the reference's per-field parameter-unmarshal loop (TPM 2.0 Library Part 2, clause 6.6.2, Table 16's "N"
    /// field).
    /// </remarks>
    /// <param name="reader">The reader positioned at the parameter.</param>
    /// <param name="index">The parameter's zero-based position in the command's own parameter table.</param>
    /// <param name="value">The unmarshalled value on success.</param>
    /// <param name="malformedResponseCode">The parameter-index-encoded refusal code on failure.</param>
    /// <returns><see langword="true"/> when the parameter was read.</returns>
    private static bool TryReadUInt16Parameter(ref TpmReader reader, int index, out ushort value, out TpmRcConstants malformedResponseCode)
    {
        if(reader.Remaining < sizeof(ushort))
        {
            value = 0;
            malformedResponseCode = ParameterEncodedRc(TpmRcConstants.TPM_RC_INSUFFICIENT, index);

            return false;
        }

        value = reader.ReadUInt16();
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>
    /// Reads a TPM2B (UINT16 size prefix + octets) as a span over the command buffer, for a parse that rents the
    /// owning carrier as its last act — the octets reach the request through that carrier alone, never through an
    /// intermediate heap copy.
    /// </summary>
    /// <remarks>
    /// Two wire checks precede the read: a size prefix the command cannot carry, or a declared size the
    /// remaining octets cannot cover, is <c>TPM_RC_INSUFFICIENT</c> (Part 3, clause 5.8.2, Table 2). The reader is taken by
    /// reference so the returned span, which aliases the command buffer, is valid for the caller.
    /// </remarks>
    /// <param name="reader">The reader positioned at the size prefix.</param>
    /// <param name="bytes">The octets, aliasing the command buffer.</param>
    /// <param name="malformedResponseCode">The response code a malformed frame answers with.</param>
    /// <returns><see langword="true"/> when the field read cleanly.</returns>
    private static bool TryReadTpm2bSpan(ref TpmReader reader, out ReadOnlySpan<byte> bytes, out TpmRcConstants malformedResponseCode)
    {
        bytes = ReadOnlySpan<byte>.Empty;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        ushort size = reader.ReadUInt16();
        if(reader.Remaining < size)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        if(size > 0)
        {
            bytes = reader.ReadBytes(size);
        }

        return true;
    }

    /// <summary>
    /// Reads a TPM2B (UINT16 size prefix + octets) as a span over the command buffer, refusing a declared size
    /// over <paramref name="maxSize"/> BEFORE checking it against the octets remaining in the reader — so a
    /// field that is both over-bound and truncated answers <c>TPM_RC_SIZE</c> rather than
    /// <c>TPM_RC_INSUFFICIENT</c>.
    /// </summary>
    /// <remarks>
    /// This is <see cref="TryProbeOutsideInfo"/>'s ordering generalized to any TPM2B leaf field: the reference
    /// unmarshaler checks a TPM2B's declared size against its structure's own bound before the array read that
    /// would otherwise report a short buffer, and this bound-first check is what reproduces that priority for a
    /// field this parser actually captures (rather than only probes and skips).
    /// </remarks>
    /// <param name="reader">The reader positioned at the size prefix.</param>
    /// <param name="maxSize">The field's declared-size bound (its owning TPM2B carrier's <c>MaxSize</c>).</param>
    /// <param name="bytes">The octets, aliasing the command buffer.</param>
    /// <param name="malformedResponseCode">The response code a malformed frame answers with.</param>
    /// <returns><see langword="true"/> when the field read cleanly within its bound.</returns>
    private static bool TryReadTpm2bSpanBounded(ref TpmReader reader, int maxSize, out ReadOnlySpan<byte> bytes, out TpmRcConstants malformedResponseCode)
    {
        bytes = ReadOnlySpan<byte>.Empty;
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        ushort size = reader.ReadUInt16();
        if(size > maxSize)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

            return false;
        }

        if(reader.Remaining < size)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        if(size > 0)
        {
            bytes = reader.ReadBytes(size);
        }

        return true;
    }

    /// <summary>
    /// Parses a <c>TPMT_SIGNATURE</c>'s post-selector body — <c>hashAlg</c> followed by the <c>sigAlg</c>-selected
    /// <c>TPMU_SIGNATURE</c> member — shared by <see cref="TryParseVerifySignature"/>,
    /// <see cref="TryParseVerifySequenceComplete"/>, <see cref="TryParseVerifyDigestSignature"/> and
    /// <see cref="TryParsePolicySigned"/> once each has already gated <paramref name="sigAlg"/> to its own
    /// admitted set (TPM 2.0 Library Part 2, clause 11.3.6, Table
    /// 219; the <c>TPM_RC_SCHEME</c> gate on the selector itself stays exactly where each caller already has
    /// it, so <see cref="TpmuSignature"/>'s own selector throw stays unreachable here). The <c>TPM_ALG_HMAC</c>
    /// member is a <c>TPMT_HA</c> — the shared <c>hashAlg</c> field followed by an unsized digest the hashAlg
    /// itself sizes; the other members are TPM2B-framed.
    /// </summary>
    /// <remarks>
    /// <c>signatureR</c>/<c>signatureS</c> (<c>TPMS_SIGNATURE_ECC</c>, Part 2, clause 11.3.2, Table 214; each a
    /// <c>TPM2B_ECC_PARAMETER</c>, clause 11.2.5.1, Table 197) and the RSA signature (<c>TPMS_SIGNATURE_RSA</c>,
    /// clause 11.3.1, Table 212) are each read through <see cref="TryReadTpm2bSpanBounded"/>, so a declared size
    /// over the member's own bound answers <c>TPM_RC_SIZE</c> before a declared size the remaining buffer cannot
    /// cover answers <c>TPM_RC_INSUFFICIENT</c> — bound-before-truncation, the order
    /// <see cref="TryParseActivateCredential"/> already established for the credential fields. The pooled
    /// <see cref="TpmtSignature"/> is rented as the parse's last act: the RSA member through
    /// <see cref="TpmtSignature.Create"/> (the same surface the signing effects use), the ECDSA member through
    /// <see cref="TpmtSignature.CreateEcdsaFromComponents"/>, which takes the already-bound-checked r and s spans
    /// directly — <c>signatureR</c> and <c>signatureS</c> are unrelated in length on the wire (Table 214 imposes
    /// no relation between them), so a genuine pair whose combined length happens to be odd is accepted rather
    /// than rejected the way a P1363-concatenation-shaped constructor would; the verifying effect then reads each
    /// component as the integer it is and rebuilds the fixed-width pair itself
    /// (<see cref="TpmLifecycleTransitions.TryWriteNormalizedEcdsaSignature"/>).
    /// </remarks>
    /// <param name="reader">The reader positioned at the signature body's <c>hashAlg</c> field.</param>
    /// <param name="sigAlg">The already wire-gated signing-algorithm selector.</param>
    /// <param name="pool">The memory pool the signature's carrier is rented from.</param>
    /// <param name="signature">The parsed signature, owned by the caller.</param>
    /// <param name="malformedResponseCode">The response code a malformed frame answers with.</param>
    /// <returns><see langword="true"/> when the signature body read cleanly within its bounds.</returns>
    private static bool TryParseTpmtSignatureBody(ref TpmReader reader, TpmiAlgSigScheme sigAlg, BaseMemoryPool pool, [NotNullWhen(true)] out TpmtSignature? signature, out TpmRcConstants malformedResponseCode)
    {
        signature = null;

        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        var hashAlg = (TpmAlgIdConstants)reader.ReadUInt16();

        if(sigAlg.Value == TpmAlgIdConstants.TPM_ALG_HMAC)
        {
            //TPMU_SIGNATURE's HMAC member is a TPMT_HA (TPM 2.0 Library Part 2, clause 10.2.2, Table 89): the
            //hashAlg just read followed by an UNSIZED digest whose width the hashAlg itself fixes — no TPM2B
            //length prefix. An unadmitted or NULL hashAlg cannot size the digest and answers #TPM_RC_HASH,
            //the TPMI_ALG_HASH unmarshal channel (the reference unmarshals this member with the null flag
            //CLEAR, so a NULL hash never reaches the command action).
            if(hashAlg.GetDigestSize() is not int hmacDigestSize)
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_HASH;

                return false;
            }

            if(reader.Remaining < hmacDigestSize)
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

                return false;
            }

            signature = TpmtSignature.Hmac(TpmiAlgHash.FromValue(hashAlg), reader.ReadBytes(hmacDigestSize), pool);
            malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

            return true;
        }

        if(sigAlg.Value == TpmAlgIdConstants.TPM_ALG_ECDSA)
        {
            if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bEccParameter.MaxSize, out ReadOnlySpan<byte> signatureR, out malformedResponseCode))
            {
                return false;
            }

            if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bEccParameter.MaxSize, out ReadOnlySpan<byte> signatureS, out malformedResponseCode))
            {
                return false;
            }

            signature = TpmtSignature.CreateEcdsaFromComponents(hashAlg, signatureR, signatureS, pool);
            malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

            return true;
        }

        if(!TryReadTpm2bSpanBounded(ref reader, Tpm2bPublicKeyRsa.MaxRsaKeyBytes, out ReadOnlySpan<byte> rsaSignature, out malformedResponseCode))
        {
            return false;
        }

        signature = TpmtSignature.Create(sigAlg.Value, hashAlg, rsaSignature, pool);
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        return true;
    }

    /// <summary>Skips a TPM2B (UINT16 size prefix + octets) without copying — used for fields the model does not retain.</summary>
    private static bool TrySkipTpm2b(ref TpmReader reader, out TpmRcConstants malformedResponseCode)
    {
        malformedResponseCode = TpmRcConstants.TPM_RC_SUCCESS;

        if(reader.Remaining < sizeof(ushort))
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        ushort size = reader.ReadUInt16();
        if(reader.Remaining < size)
        {
            malformedResponseCode = TpmRcConstants.TPM_RC_INSUFFICIENT;

            return false;
        }

        reader.Skip(size);

        return true;
    }

    /// <summary>
    /// Probes an <c>outsideInfo</c> (<c>TPM2B_DATA</c>) parameter on a by-value reader copy: the declared
    /// <c>size</c> is peeked and checked against <see cref="Tpm2bData.MaxSize"/> BEFORE
    /// <see cref="TrySkipTpm2b"/>'s own truncation probe runs, so an <c>outsideInfo</c> that is BOTH over-bound
    /// and truncated answers <c>TPM_RC_SIZE</c> rather than <c>TPM_RC_INSUFFICIENT</c>.
    /// </summary>
    /// <remarks>
    /// <c>TPM2B_DATA</c>'s buffer is bounded by <c>sizeof(TPMT_HA)</c> (TPM 2.0 Library Part 2, clause 10.3.3,
    /// Table 91), and the reference unmarshaler settles that bound in the same order this probe does: the
    /// reference checks the declared size against <c>sizeof(TPMT_HA)</c> in <c>TPM2B_DATA_Unmarshal</c> before
    /// the <c>Array_Unmarshal</c> call that would otherwise need to declare the buffer insufficient (Part 4,
    /// Marshal.c's <c>Array_Unmarshal()</c>). When <paramref name="reader"/> is too short to carry even the <c>size</c> field, this peek is
    /// skipped and <see cref="TrySkipTpm2b"/> answers the shortfall as it always has.
    /// </remarks>
    /// <param name="reader">The reader positioned at the field's <c>size</c>; a probe copy the caller discards regardless of outcome.</param>
    /// <param name="malformedResponseCode">The response code for a malformed field; meaningless when this returns <see langword="true"/>.</param>
    /// <returns><see langword="true"/> when the field is within its size bound and not truncated.</returns>
    private static bool TryProbeOutsideInfo(ref TpmReader reader, out TpmRcConstants malformedResponseCode)
    {
        TpmReader sizePeek = reader;
        if(sizePeek.Remaining >= sizeof(ushort))
        {
            ushort declaredSize = sizePeek.ReadUInt16();
            if(declaredSize > Tpm2bData.MaxSize)
            {
                malformedResponseCode = TpmRcConstants.TPM_RC_SIZE;

                return false;
            }
        }

        return TrySkipTpm2b(ref reader, out malformedResponseCode);
    }

    private static TpmSuConstants ReadStartupType(ref TpmReader reader)
    {
        //An absent or short startup type is surfaced as an out-of-range value, which the transition
        //rejects with TPM_RC_VALUE — the same outcome the TPM gives for an invalid startupType.
        if(reader.Remaining < sizeof(ushort))
        {
            return (TpmSuConstants)0xFFFF;
        }

        return (TpmSuConstants)reader.ReadUInt16();
    }

    /// <summary>
    /// Frames one <see cref="TpmResponseIntent"/> into the wire-serialized <see cref="TpmResponse"/> its own
    /// command's response table describes, dispatching by the intent's concrete type.
    /// </summary>
    /// <remarks>
    /// <strong>Manual disposal, not <see langword="using"/> declarations.</strong> Every pattern-matched local
    /// above the <see langword="try"/> (<c>randomBuffer</c> through <c>startedSessionNonce</c>) is a
    /// nullable, pattern-matched VIEW into whichever concrete intent <paramref name="intent"/> actually is —
    /// <see langword="null"/> for every other intent shape — so none of them can be a single-declaration
    /// <see langword="using"/> target; each is released, once, in the single <see langword="finally"/> below
    /// once its own octets are copied into the framed response (a few, named at their own declaration, are
    /// zeroed first because they carry confidential material). One shared <see langword="finally"/> across
    /// every intent shape, rather than one <see langword="using"/> block per shape, keeps the release
    /// discipline in exactly one place for a switch this wide.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeResponse(TpmResponseIntent intent, BaseMemoryPool pool)
    {
        //A policy-gated TPM2_Unseal() response is likewise TPM_ST_SESSIONS-tagged and carries a trailing response
        //session area — but with TWO session entries (the policy session then the encrypt session) — so it is framed
        //by its own helper (the terminal owner of its pooled parameter-area and HMAC buffers).
        if(intent is TpmUnsealOverSessionsResponse unsealOverSessions)
        {
            return SerializeUnsealOverSessionsResponse(unsealOverSessions, pool);
        }

        //TPM2_Create() over sessions is likewise TPM_ST_SESSIONS-tagged and carries a trailing response session
        //area (a TPM_RS_PW placeholder, a real per-session entry, or both) — the request-decrypt counterpart of
        //TpmUnsealOverSessionsResponse — so it too is framed by its own helper.
        if(intent is TpmCreateOverSessionsResponse createOverSessions)
        {
            return SerializeCreateOverSessionsResponse(createOverSessions, pool);
        }

        //A session-authorized TPM2_PolicySecret() response is likewise TPM_ST_SESSIONS-tagged with a trailing
        //response session area (a single entry, the authorizing session's rolled nonce and real response HMAC),
        //so it too gets its own helper.
        if(intent is TpmPolicySecretOverSessionResponse policySecretOverSession)
        {
            return SerializePolicySecretOverSessionResponse(policySecretOverSession, pool);
        }

        //A session-authorized NV command (NV_Read/NV_Write/NV_DefineSpace/NV_UndefineSpace) response is
        //likewise TPM_ST_SESSIONS-tagged with a trailing single-entry response session area — the NV-family
        //counterpart of TpmPolicySecretOverSessionResponse, generalized over an (possibly empty) parameter area.
        if(intent is TpmNvSessionResponse nvSession)
        {
            return SerializeNvSessionResponse(nvSession, pool);
        }

        //The session-authorized KEYEDHASH commands share that single-entry shape but TPM2_HMAC_Start() also
        //returns a handle (Table 81's sequenceHandle, ahead of parameterSize), which the NV shape has no slot
        //for, so both frame through their own helper.
        if(intent is TpmHmacOverSessionResponse hmacOverSession)
        {
            return SerializeKeyedHashOverSessionResponse(hmacOverSession.ResponseCode, sequenceHandle: null, hmacOverSession.ParameterArea, hmacOverSession.Entry, pool);
        }

        if(intent is TpmHmacStartOverSessionResponse hmacStartOverSession)
        {
            return SerializeKeyedHashOverSessionResponse(
                hmacStartOverSession.ResponseCode, hmacStartOverSession.SequenceHandle, TpmParameterArea.Empty, hmacStartOverSession.Entry, pool);
        }

        //TPM2_NV_ChangeAuth() is TPM_ST_SESSIONS-tagged with no response parameters and one entry per command
        //session — the ADMIN policy session, plus a separate decrypt session when the caller protected newAuth
        //in flight — so it is framed by its own helper rather than the single-entry NV shape above.
        if(intent is TpmNvChangeAuthResponse nvChangeAuth)
        {
            return SerializeNvChangeAuthResponse(nvChangeAuth, pool);
        }

        //A command whose slots are independent of one another — the attest family (Certify/CertifyCreation/
        //Quote/GetTime/NV_Certify, a TPM2B_ATTEST/TPMT_SIGNATURE pair over independently authorized handles,
        //Part 3, Tables 90/92/94/100/255) and the signing family (Sign/SignDigest/SequenceUpdate/
        //SignSequenceComplete/VerifySequenceComplete, Tables 92/119/123/125/127) — owes its parameter area AND
        //one entry per slot with the placeholder decided per entry, which neither NV shape above can frame.
        if(intent is TpmOverSessionsResponse overSessions)
        {
            return SerializeOverSessionsResponse(overSessions, pool);
        }

        //The TpmRandomResponse intent is the terminal owner of the RNG buffer rented by the action
        //executor; release it in the finally regardless of how framing completes (its octets are
        //copied into the framed TPM2B_DIGEST on the success path).
        Tpm2bDigest? randomBuffer = (intent as TpmRandomResponse)?.RandomBytes;
        TpmsCapabilityData? capabilityData = (intent as TpmCapabilityResponse)?.CapabilityData;

        //The CreatePrimary and Sign intents are the terminal owners of the exported public area, each creation
        //by-product structure, and the signature; release them in the finally once their octets are framed.
        Tpm2bPublic? createdPublic = (intent as TpmCreatePrimaryResponse)?.OutPublic;
        Tpm2bCreationData? createdCreationData = (intent as TpmCreatePrimaryResponse)?.CreationData;
        Tpm2bDigest? createdCreationHash = (intent as TpmCreatePrimaryResponse)?.CreationHash;
        TpmtTkCreation? createdCreationTicket = (intent as TpmCreatePrimaryResponse)?.CreationTicket;
        Tpm2bName? createdName = (intent as TpmCreatePrimaryResponse)?.Name;
        TpmtSignature? signatureValue = (intent as TpmSignResponse)?.Signature;

        //The Create (seal) and Load intents own the wrapped blob, the sealed object's public area, its by-products,
        //and the object Name; release them in the finally once framed. The Unseal intent's octets are durable model
        //memory owned by the loaded object, so nothing is disposed for it.
        Tpm2bPrivate? sealedPrivate = (intent as TpmCreateResponse)?.PrivateBlob;
        Tpm2bPublic? sealedPublic = (intent as TpmCreateResponse)?.OutPublic;
        Tpm2bCreationData? sealedCreationData = (intent as TpmCreateResponse)?.CreationData;
        Tpm2bDigest? sealedCreationHash = (intent as TpmCreateResponse)?.CreationHash;
        TpmtTkCreation? sealedCreationTicket = (intent as TpmCreateResponse)?.CreationTicket;
        Tpm2bName? loadedName = (intent as TpmLoadResponse)?.Name;

        //The ContextSave intent owns the whole framed TPMS_CONTEXT — including the TPM2B_CONTEXT_DATA blob the
        //save effect encrypted and integrity-protected; release it in the finally once written.
        TpmsContext? contextSaveContext = (intent as TpmContextSaveResponse)?.Context;

        //The NV_ReadPublic intent owns the built public area (which itself owns pooled policy-digest memory) and
        //the computed Name buffer; release them in the finally once framed.
        TpmsNvPublic? nvReadPublicArea = (intent as TpmNvReadPublicResponse)?.NvPublic;
        Tpm2bName? nvReadPublicName = (intent as TpmNvReadPublicResponse)?.NvName;

        //The Certify intent owns the attest structure and the signature structure; release them in the finally
        //once the TPM2B_ATTEST and TPMT_SIGNATURE are framed.
        Tpm2bAttest? certifyInfoBuffer = (intent as TpmCertifyResponse)?.CertifyInfo;
        TpmtSignature? certifySignature = (intent as TpmCertifyResponse)?.Signature;

        //The CertifyCreation, GetTime, and NV_Certify intents likewise own their attest and signature structures;
        //release them in the finally once framed.
        Tpm2bAttest? certifyCreationInfoBuffer = (intent as TpmCertifyCreationResponse)?.CertifyInfo;
        TpmtSignature? certifyCreationSignature = (intent as TpmCertifyCreationResponse)?.Signature;
        Tpm2bAttest? timeInfoBuffer = (intent as TpmGetTimeResponse)?.TimeInfo;
        TpmtSignature? timeSignature = (intent as TpmGetTimeResponse)?.Signature;
        Tpm2bAttest? sessionAuditInfoBuffer = (intent as TpmGetSessionAuditDigestResponse)?.AuditInfo;
        TpmtSignature? sessionAuditSignature = (intent as TpmGetSessionAuditDigestResponse)?.Signature;
        Tpm2bAttest? nvCertifyInfoBuffer = (intent as TpmNvCertifyResponse)?.CertifyInfo;
        TpmtSignature? nvCertifySignature = (intent as TpmNvCertifyResponse)?.Signature;

        //The VerifySignature intent owns only its validation ticket — no attest, no signature (unlike every
        //other attest-family intent above). VerifyDigestSignature's ticket is the same shape, owned the same way.
        TpmtTkVerified? verifySignatureValidation = (intent as TpmVerifySignatureResponse)?.Validation;
        TpmtTkVerified? verifyDigestSignatureValidation = (intent as TpmVerifyDigestSignatureResponse)?.Validation;
        TpmtTkVerified? verifySequenceCompleteValidation = (intent as TpmVerifySequenceCompleteResponse)?.Validation;

        //The SequenceComplete/Hash intent owns its digest and its ticket; release both in the finally once framed.
        Tpm2bDigest? digestResult = (intent as TpmDigestResponse)?.Result;
        TpmtTkHashcheck? digestValidation = (intent as TpmDigestResponse)?.Validation;

        //The HMAC intent owns its outHMAC digest; release it in the finally once framed.
        Tpm2bDigest? hmacOutHmac = (intent as TpmHmacResponse)?.OutHmac;

        //The Encapsulate intent owns its shared secret and ciphertext; Decapsulate owns only the shared
        //secret (Table 63's single response parameter). Release them in the finally once framed.
        Tpm2bSharedSecret? encapsulateSharedSecret = (intent as TpmEncapsulateResponse)?.SharedSecret;
        Tpm2bKemCiphertext? encapsulateCiphertext = (intent as TpmEncapsulateResponse)?.Ciphertext;
        Tpm2bSharedSecret? decapsulateSharedSecret = (intent as TpmDecapsulateResponse)?.SharedSecret;

        //The PolicySecret/PolicySigned intents own their framed timeout, and their minted ticket-digest carrier
        //only when a real ticket was minted (null for a NULL ticket, so nothing to dispose there).
        Tpm2bTimeout? policySecretTimeout = (intent as TpmPolicySecretResponse)?.Timeout;
        Tpm2bDigest? policySecretTicketDigest = (intent as TpmPolicySecretResponse)?.TicketDigest;
        Tpm2bTimeout? policySignedTimeout = (intent as TpmPolicySignedResponse)?.Timeout;
        Tpm2bDigest? policySignedTicketDigest = (intent as TpmPolicySignedResponse)?.TicketDigest;

        //The PCR_Read intent owns the selection carrier its own request transferred here; release it in the
        //finally once framed. Its PcrValues are references into durable bank state, so nothing is disposed for them.
        TpmlPcrSelection? pcrReadSelection = (intent as TpmPcrReadResponse)?.PcrSelection;

        //The PCR_Event/EventSequenceComplete intent owns its digest list; release it in the finally once framed.
        TpmlDigestValues? eventDigests = (intent as TpmDigestValuesResponse)?.Digests;

        //The Quote intent likewise owns the marshaled attest buffer and the signature; release them in the
        //finally once framed.
        Tpm2bAttest? quotedBuffer = (intent as TpmQuoteResponse)?.Quoted;
        TpmtSignature? quoteSignature = (intent as TpmQuoteResponse)?.Signature;

        //The MakeCredential intent owns the credential-blob and secret buffers (both public); release them in the
        //finally once framed. The ActivateCredential intent owns the recovered credential secret — confidential, so
        //it is zeroed before disposal (the clear-before-dispose discipline used for the decrypted response parameter).
        Tpm2bIdObject? credentialBlobBuffer = (intent as TpmMakeCredentialResponse)?.CredentialBlob;
        Tpm2bEncryptedSecret? credentialSecretBuffer = (intent as TpmMakeCredentialResponse)?.Secret;

        //The Duplicate intent owns the duplication blob and the protected seed; release them in the finally
        //once framed. A wrapped blob and a transported seed protect themselves, while the TPM_RH_NULL form's
        //blob is plaintext sensitive material by design — it rides a pinned rental, which the pool zeroes when
        //the release below returns it.
        TpmDuplicateResponse? duplicateIntent = intent as TpmDuplicateResponse;

        //The Import intent owns the re-wrapped blob — a self-protecting wire value; release it in the finally
        //once framed.
        TpmImportResponse? importIntent = intent as TpmImportResponse;

        //The password/bare-policy ObjectChangeAuth intent likewise owns the freshly wrapped private area —
        //a self-protecting wire value; release it in the finally once framed.
        TpmObjectChangeAuthResponse? objectChangeAuthIntent = intent as TpmObjectChangeAuthResponse;

        //The plain-form RSA_Encrypt intent likewise owns the encrypted outData — a self-protecting wire value;
        //release it in the finally once framed. The session form never reaches this serializer at all (it frames
        //through SerializeOverSessionsResponse instead).
        TpmRsaEncryptResponse? rsaEncryptIntent = intent as TpmRsaEncryptResponse;

        //The plain-form RSA_Decrypt intent owns the recovered plaintext message — zeroed before disposal in the
        //finally below (the clear-before-dispose discipline), unlike the RSA_Encrypt intent's public
        //ciphertext. The session form never reaches this serializer either (SerializeOverSessionsResponse
        //instead, whose own parameter-area clear covers this response's plaintext there).
        TpmRsaDecryptResponse? rsaDecryptIntent = intent as TpmRsaDecryptResponse;
        TpmActivateCredentialResponse? activatedCredential = intent as TpmActivateCredentialResponse;

        //The StartAuthSession intent owns the framing step's own copy of the started session's nonceTPM, rented
        //alongside the copy the durable session record keeps; release it in the finally once framed.
        Tpm2bNonce? startedSessionNonce = (intent as TpmStartAuthSessionResponse)?.NonceTpm;
        try
        {
            int parameterSize = intent switch
            {
                TpmTestResultResponse { ResponseCode: TpmRcConstants.TPM_RC_SUCCESS } => sizeof(ushort) + sizeof(uint),
                TpmRandomResponse random => random.RandomBytes.SerializedSize,
                TpmCapabilityResponse capabilityResponse => sizeof(byte) + capabilityResponse.CapabilityData.GetSerializedSize(),

                //objectHandle + outPublic + creationData + creationHash + creationTicket + name, each sized by
                //its own structure so the framing arm below cannot drift from the size computed here.
                TpmCreatePrimaryResponse createPrimary =>
                    sizeof(uint)
                    + createPrimary.OutPublic.GetSerializedSize()
                    + createPrimary.CreationData.SerializedSize
                    + createPrimary.CreationHash.SerializedSize
                    + createPrimary.CreationTicket.SerializedSize
                    + createPrimary.Name.SerializedSize,

                //ECDSA: sigAlg + hash + r (TPM2B) + s (TPM2B), r and s splitting the IEEE P1363 signature at its
                //half. RSA: sigAlg + hash + sig (one TPM2B). The signature octets are the remaining length.
                //Shared by TPM2_Sign(), TPM2_SignDigest(), and TPM2_SignSequenceComplete() alike.
                TpmSignResponse sign => sign.Signature.GetSerializedSize(),

                //sequenceHandle (the response handle area) — no parameters at all (Tables 88/90).
                TpmSequenceStartResponse sequenceStart => sizeof(uint),

                //outPrivate (TPM2B_PRIVATE) + outPublic + creationData + creationHash + creationTicket, each
                //sized by its own structure. TPM2_Create() returns no Name (Part 3, clause 12.1).
                TpmCreateResponse createObject =>
                    createObject.PrivateBlob.SerializedSize
                    + createObject.OutPublic.GetSerializedSize()
                    + createObject.CreationData.SerializedSize
                    + createObject.CreationHash.SerializedSize
                    + createObject.CreationTicket.SerializedSize,

                //objectHandle + name (TPM2B_NAME).
                TpmLoadResponse load => sizeof(uint) + load.Name.SerializedSize,

                //The whole TPMS_CONTEXT: sequence + savedHandle + hierarchy + the TPM2B_CONTEXT_DATA blob,
                //sized by the structure so this arm cannot drift from what WriteTo actually writes.
                TpmContextSaveResponse contextSaveSizing => contextSaveSizing.Context.SerializedSize,

                //loadedHandle (the response handle area) — no response parameters at all (Table 227).
                TpmContextLoadResponse => sizeof(uint),

                //outData (TPM2B_SENSITIVE_DATA) carrying the recovered sealed octets.
                TpmUnsealResponse unseal => sizeof(ushort) + unseal.OutData.Length,

                //data (TPM2B_MAX_NV_BUFFER) carrying the octets read from the NV Index.
                TpmNvReadDataResponse nvReadData => nvReadData.Data.SerializedSize,

                //nvPublic (TPM2B_NV_PUBLIC, a UINT16 size prefix around the marshaled TPMS_NV_PUBLIC) + nvName (TPM2B_NAME).
                TpmNvReadPublicResponse nvReadPublic => (sizeof(ushort) + nvReadPublic.NvPublic.SerializedSize) + nvReadPublic.NvName.SerializedSize,

                //outPublic (TPM2B_PUBLIC) + name (TPM2B_NAME) + qualifiedName (TPM2B_NAME), each sized by its own
                //structure (Part 3, clause 12.4, Table 25).
                TpmReadPublicResponse readPublic => readPublic.OutPublic.GetSerializedSize() + readPublic.Name.SerializedSize + readPublic.QualifiedName.SerializedSize,

                //certifyInfo (TPM2B_ATTEST) + signature (TPMT_SIGNATURE), each sized by its own structure — the
                //same arithmetic the session arm's parameter-area framing uses, so the two arms cannot drift
                //apart in what rpHash would have to cover.
                TpmCertifyResponse certify => certify.CertifyInfo.GetSerializedSize() + certify.Signature.GetSerializedSize(),

                //certifyInfo (TPM2B_ATTEST) + signature (TPMT_SIGNATURE), the same shape as TpmCertifyResponse.
                TpmCertifyCreationResponse certifyCreation => certifyCreation.CertifyInfo.GetSerializedSize() + certifyCreation.Signature.GetSerializedSize(),

                //timeInfo (TPM2B_ATTEST) + signature (TPMT_SIGNATURE), the same shape as TpmCertifyResponse.
                TpmGetTimeResponse getTime => getTime.TimeInfo.GetSerializedSize() + getTime.Signature.GetSerializedSize(),

                //auditInfo (TPM2B_ATTEST) + signature (TPMT_SIGNATURE, 2 octets alone for the NULL signer's bare
                //selector), the same shape as TpmCertifyResponse.
                TpmGetSessionAuditDigestResponse getSessionAuditDigest => getSessionAuditDigest.AuditInfo.GetSerializedSize() + getSessionAuditDigest.Signature.GetSerializedSize(),

                //certifyInfo (TPM2B_ATTEST) + signature (TPMT_SIGNATURE), the same shape as TpmCertifyResponse.
                TpmNvCertifyResponse nvCertify => nvCertify.CertifyInfo.GetSerializedSize() + nvCertify.Signature.GetSerializedSize(),

                //validation (TPMT_TK_VERIFIED): tag (UINT16) + hierarchy (UINT32) + digest (TPM2B_DIGEST) — no
                //attest and no signature, unlike every other attest-family response above.
                TpmVerifySignatureResponse verifySignature => verifySignature.Validation.SerializedSize,

                //validation (TPMT_TK_VERIFIED): the same shape as TpmVerifySignatureResponse, but tagged
                //TPM_ST_DIGEST_VERIFIED with a conditional metadata field the structure itself accounts for.
                TpmVerifyDigestSignatureResponse verifyDigestSignature => verifyDigestSignature.Validation.SerializedSize,

                //validation (TPMT_TK_VERIFIED): the same shape again, tagged TPM_ST_MESSAGE_VERIFIED with no
                //metadata field at all — the sequence-command counterpart of both responses above.
                TpmVerifySequenceCompleteResponse verifySequenceComplete => verifySequenceComplete.Validation.SerializedSize,

                //result/outHash (TPM2B_DIGEST) + validation (TPMT_TK_HASHCHECK), each sized by its own structure
                //(Tables 94 and 70 share the shape).
                TpmDigestResponse digestResponseSizing => digestResponseSizing.Result.SerializedSize + digestResponseSizing.Validation.SerializedSize,

                //outHMAC (TPM2B_DIGEST): Table 72's single response parameter, no ticket.
                TpmHmacResponse hmacResponseSizing => hmacResponseSizing.OutHmac.SerializedSize,

                //sharedSecret (TPM2B_SHARED_SECRET) + ciphertext (TPM2B_KEM_CIPHERTEXT), each sized by its own
                //structure, in Table 61's order.
                TpmEncapsulateResponse encapsulate => encapsulate.SharedSecret.SerializedSize + encapsulate.Ciphertext.SerializedSize,

                //sharedSecret (TPM2B_SHARED_SECRET): Table 63's single response parameter.
                TpmDecapsulateResponse decapsulate => decapsulate.SharedSecret.SerializedSize,

                //currentTime (TPMS_TIME_INFO, fixed layout): the uncertified Time/Clock/resetCount/restartCount/Safe snapshot.
                TpmReadClockResponse => TpmsTimeInfo.SerializedSize,

                //pcrUpdateCounter (UINT32) + pcrSelectionOut (TPML_PCR_SELECTION, re-marshaled) + pcrValues (TPML_DIGEST).
                TpmPcrReadResponse pcrRead =>
                    sizeof(uint) + pcrRead.PcrSelection.GetSerializedSize() + PcrValuesSerializedSize(pcrRead.PcrValues),

                //digests / results (TPML_DIGEST_VALUES): count then each TPMT_HA, sized by the structure (Tables 133
                //and 96 share the shape).
                TpmDigestValuesResponse digestValues => digestValues.Digests.GetSerializedSize(),

                //quoted (TPM2B_ATTEST) + signature (TPMT_SIGNATURE), the same shape as TpmCertifyResponse.
                TpmQuoteResponse quote => quote.Quoted.GetSerializedSize() + quote.Signature.GetSerializedSize(),

                //sessionHandle (response handle) + nonceTPM (TPM2B_NONCE of the policy-hash width).
                TpmStartAuthSessionResponse startAuthSession =>
                    sizeof(uint) + startAuthSession.NonceTpm.SerializedSize,

                //policyDigest (TPM2B_DIGEST): the session's accumulated digest.
                TpmPolicyGetDigestResponse policyGetDigest => policyGetDigest.PolicyDigest.SerializedSize,

                //A NULL ticket: empty TPM2B_TIMEOUT + policyTicket (TPMT_TK_AUTH: tag + hierarchy + empty
                //digest). A real ticket: the full 8-byte TPM2B_TIMEOUT + policyTicket with its real digest.
                TpmPolicySecretResponse policySecret => policySecret.TicketDigest is { } secretTicket
                    ? policySecret.Timeout.SerializedSize + (sizeof(ushort) + sizeof(uint) + secretTicket.SerializedSize)
                    : sizeof(ushort) + (sizeof(ushort) + sizeof(uint) + sizeof(ushort)),

                //A NULL ticket: empty TPM2B_TIMEOUT + policyTicket (TPMT_TK_AUTH: tag + hierarchy + empty
                //digest). A real ticket: the full 8-byte TPM2B_TIMEOUT + policyTicket with its real digest.
                TpmPolicySignedResponse policySigned => policySigned.TicketDigest is { } signedTicket
                    ? policySigned.Timeout.SerializedSize + (sizeof(ushort) + sizeof(uint) + signedTicket.SerializedSize)
                    : sizeof(ushort) + (sizeof(ushort) + sizeof(uint) + sizeof(ushort)),

                //credentialBlob (TPM2B_ID_OBJECT) + secret (TPM2B_ENCRYPTED_SECRET).
                TpmMakeCredentialResponse makeCredential =>
                    makeCredential.CredentialBlob.SerializedSize + makeCredential.Secret.SerializedSize,

                //encryptionKeyOut (an empty TPM2B_DATA in the no-inner-wrapper model) + duplicate
                //(TPM2B_PRIVATE) + outSymSeed (TPM2B_ENCRYPTED_SECRET).
                TpmDuplicateResponse duplicateSizing =>
                    sizeof(ushort) + duplicateSizing.Duplicate.SerializedSize + duplicateSizing.OutSymSeed.SerializedSize,

                //outPrivate (TPM2B_PRIVATE).
                TpmImportResponse importSizing => importSizing.OutPrivate.SerializedSize,

                //outPrivate (TPM2B_PRIVATE): the password/bare-policy form's whole parameter area (Table 33).
                TpmObjectChangeAuthResponse objectChangeAuthSizing => objectChangeAuthSizing.OutPrivate.SerializedSize,

                //outData (TPM2B_PUBLIC_KEY_RSA): the plain form's whole parameter area (Table 45).
                TpmRsaEncryptResponse rsaEncryptSizing => rsaEncryptSizing.OutData.SerializedSize,

                //message (TPM2B_PUBLIC_KEY_RSA): the plain form's whole parameter area (Table 47).
                TpmRsaDecryptResponse rsaDecryptSizing => rsaDecryptSizing.Message.SerializedSize,

                //certInfo (TPM2B_DIGEST): the recovered credential secret.
                TpmActivateCredentialResponse activateCredential => activateCredential.CertInfo.SerializedSize,

                _ => 0
            };
            int total = TpmHeader.HeaderSize + parameterSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span);
                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_NO_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                switch(intent)
                {
                    case TpmImportResponse importResponse:
                    {
                        importResponse.OutPrivate.WriteTo(ref writer);

                        break;
                    }
                    case TpmDuplicateResponse duplicateResponse:
                    {
                        //encryptionKeyOut: the Empty Buffer the no-inner-wrapper form frames, then the blob and
                        //the protected seed.
                        writer.WriteUInt16(0);
                        duplicateResponse.Duplicate.WriteTo(ref writer);
                        duplicateResponse.OutSymSeed.WriteTo(ref writer);

                        break;
                    }
                    case TpmObjectChangeAuthResponse objectChangeAuthResponse:
                    {
                        objectChangeAuthResponse.OutPrivate.WriteTo(ref writer);

                        break;
                    }
                    case TpmRsaEncryptResponse rsaEncryptResponse:
                    {
                        //outData (TPM2B_PUBLIC_KEY_RSA): the encrypted output.
                        rsaEncryptResponse.OutData.WriteTo(ref writer);

                        break;
                    }
                    case TpmRsaDecryptResponse rsaDecryptResponse:
                    {
                        //message (TPM2B_PUBLIC_KEY_RSA): the recovered plaintext.
                        rsaDecryptResponse.Message.WriteTo(ref writer);

                        break;
                    }
                    case TpmTestResultResponse { ResponseCode: TpmRcConstants.TPM_RC_SUCCESS } testResultResponse:
                    {
                        writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                        writer.WriteUInt32((uint)testResultResponse.TestResult);

                        break;
                    }
                    case TpmRandomResponse randomResponse:
                    {
                        randomResponse.RandomBytes.WriteTo(ref writer);

                        break;
                    }
                    case TpmCapabilityResponse capabilityResponse:
                    {
                        capabilityResponse.MoreData.WriteTo(ref writer);
                        capabilityResponse.CapabilityData.WriteTo(ref writer);

                        break;
                    }
                    case TpmCreatePrimaryResponse createPrimaryResponse:
                    {
                        //objectHandle (the response handle area).
                        writer.WriteUInt32(createPrimaryResponse.ObjectHandle.Value);

                        //outPublic (TPM2B_PUBLIC) carrying the generated point.
                        createPrimaryResponse.OutPublic.WriteTo(ref writer);

                        //creationData, creationHash, creationTicket and name, in the order Part 3, clause 24.1's
                        //response table fixes; each structure writes its own size prefix and body, and each was
                        //computed faithfully in the effectful loop (the Name, creation hash, and ticket need the
                        //registered digest and HMAC seams, which are asynchronous).
                        createPrimaryResponse.CreationData.WriteTo(ref writer);
                        createPrimaryResponse.CreationHash.WriteTo(ref writer);
                        createPrimaryResponse.CreationTicket.WriteTo(ref writer);
                        createPrimaryResponse.Name.WriteTo(ref writer);

                        break;
                    }
                    case TpmSignResponse signResponse:
                    {
                        //signature (TPMT_SIGNATURE): the structure writes its own selector, hash, and member.
                        signResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmSequenceStartResponse sequenceStartResponse:
                    {
                        //sequenceHandle (the response handle area) — no parameters follow it.
                        writer.WriteUInt32(sequenceStartResponse.SequenceHandle.Value);

                        break;
                    }
                    case TpmCreateResponse createObjectResponse:
                    {
                        //outPrivate (TPM2B_PRIVATE): the wrapped blob carrying the sealed data.
                        createObjectResponse.PrivateBlob.WriteTo(ref writer);

                        //outPublic (TPM2B_PUBLIC): the sealed object's public area.
                        createObjectResponse.OutPublic.WriteTo(ref writer);

                        //creationData, creationHash and creationTicket, in the order Part 3, clause 12.1's
                        //response table fixes; no Name, which TPM2_Create() does not return.
                        createObjectResponse.CreationData.WriteTo(ref writer);
                        createObjectResponse.CreationHash.WriteTo(ref writer);
                        createObjectResponse.CreationTicket.WriteTo(ref writer);

                        break;
                    }
                    case TpmLoadResponse loadResponse:
                    {
                        //objectHandle (the response handle area).
                        writer.WriteUInt32(loadResponse.ObjectHandle.Value);

                        //name (TPM2B_NAME): the loaded object's Name.
                        loadResponse.Name.WriteTo(ref writer);

                        break;
                    }
                    case TpmContextSaveResponse contextSaveResponse:
                    {
                        //context (TPMS_CONTEXT): the command's whole parameter area, no response handle
                        //(Table 225 — ContextSave carries no response handle).
                        contextSaveResponse.Context.WriteTo(ref writer);

                        break;
                    }
                    case TpmContextLoadResponse contextLoadResponse:
                    {
                        //loadedHandle (the response handle area) — no parameters at all (Table 227).
                        writer.WriteUInt32(contextLoadResponse.LoadedHandle.Value);

                        break;
                    }
                    case TpmUnsealResponse unsealResponse:
                    {
                        //outData (TPM2B_SENSITIVE_DATA): the recovered sealed data, viewed at this framing
                        //primitive from the carrier the loaded sealed object owns.
                        writer.WriteTpm2b(unsealResponse.OutData.AsReadOnlySpan());

                        break;
                    }
                    case TpmNvReadDataResponse nvReadDataResponse:
                    {
                        //data (TPM2B_MAX_NV_BUFFER): the requested window of the NV Index's data area, copied out
                        //of the carrier the still-live Index owns — framing borrows it and never releases it.
                        writer.WriteTpm2b(nvReadDataResponse.Data.Span);

                        break;
                    }
                    case TpmNvReadPublicResponse nvReadPublicResponse:
                    {
                        //nvPublic (TPM2B_NV_PUBLIC): a UINT16 size prefix wrapping the marshaled TPMS_NV_PUBLIC.
                        writer.WriteUInt16((ushort)nvReadPublicResponse.NvPublic.SerializedSize);
                        nvReadPublicResponse.NvPublic.WriteTo(ref writer);

                        //nvName (TPM2B_NAME): the Index's computed Name.
                        nvReadPublicResponse.NvName.WriteTo(ref writer);

                        break;
                    }
                    case TpmReadPublicResponse readPublicResponse:
                    {
                        //outPublic (TPM2B_PUBLIC), name, and qualifiedName (TPM2B_NAME each), in Table 25's order —
                        //every carrier borrowed from the still-loaded object's record, so framing never releases them.
                        readPublicResponse.OutPublic.WriteTo(ref writer);
                        readPublicResponse.Name.WriteTo(ref writer);
                        readPublicResponse.QualifiedName.WriteTo(ref writer);

                        break;
                    }
                    case TpmCertifyResponse certifyResponse:
                    {
                        //certifyInfo (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself.
                        certifyResponse.CertifyInfo.WriteTo(ref writer);
                        certifyResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmCertifyCreationResponse certifyCreationResponse:
                    {
                        //certifyInfo (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself.
                        certifyCreationResponse.CertifyInfo.WriteTo(ref writer);
                        certifyCreationResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmGetTimeResponse getTimeResponse:
                    {
                        //timeInfo (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself.
                        getTimeResponse.TimeInfo.WriteTo(ref writer);
                        getTimeResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmGetSessionAuditDigestResponse getSessionAuditDigestResponse:
                    {
                        //auditInfo (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself —
                        //the NULL signer's TpmtSignature.Null writes its 2-octet TPM_ALG_NULL selector alone.
                        getSessionAuditDigestResponse.AuditInfo.WriteTo(ref writer);
                        getSessionAuditDigestResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmNvCertifyResponse nvCertifyResponse:
                    {
                        //certifyInfo (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself,
                        //the same layout the session arm frames into its parameter area.
                        nvCertifyResponse.CertifyInfo.WriteTo(ref writer);
                        nvCertifyResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmVerifySignatureResponse verifySignatureResponse:
                    {
                        //validation (TPMT_TK_VERIFIED): tag (TPM_ST_VERIFIED) + hierarchy + digest (TPM2B_DIGEST) —
                        //the HMAC over TPM_ST_VERIFIED || digest || keyName under the verifying key's re-derived
                        //hierarchy proof, written by the structure itself. No attest, no TPMT_SIGNATURE — the odd
                        //one out among the attest-family responses above.
                        verifySignatureResponse.Validation.WriteTo(ref writer);

                        break;
                    }
                    case TpmVerifyDigestSignatureResponse verifyDigestSignatureResponse:
                    {
                        //validation (TPMT_TK_VERIFIED): tag (TPM_ST_DIGEST_VERIFIED) + hierarchy + [tag]metadata
                        //(the verified scheme's hash algorithm) + hmac (TPM2B_DIGEST), written by the structure
                        //itself. No attest, no TPMT_SIGNATURE — the same odd-one-out shape as
                        //TpmVerifySignatureResponse.
                        verifyDigestSignatureResponse.Validation.WriteTo(ref writer);

                        break;
                    }
                    case TpmVerifySequenceCompleteResponse verifySequenceCompleteResponse:
                    {
                        //validation (TPMT_TK_VERIFIED): tag (TPM_ST_MESSAGE_VERIFIED) + hierarchy + hmac
                        //(TPM2B_DIGEST) — no metadata field, no attest, no TPMT_SIGNATURE, the same odd-one-out
                        //shape as TpmVerifySignatureResponse and TpmVerifyDigestSignatureResponse.
                        verifySequenceCompleteResponse.Validation.WriteTo(ref writer);

                        break;
                    }
                    case TpmDigestResponse digestResponse:
                    {
                        //result/outHash (TPM2B_DIGEST) then validation (TPMT_TK_HASHCHECK): tag + hierarchy +
                        //TPM2B digest, each written by its own structure (Tables 94 and 70 share the shape).
                        digestResponse.Result.WriteTo(ref writer);
                        digestResponse.Validation.WriteTo(ref writer);

                        break;
                    }
                    case TpmHmacResponse hmacResponse:
                    {
                        //outHMAC (TPM2B_DIGEST): Table 72's single response parameter — no ticket, the structure
                        //writes its own size prefix and body.
                        hmacResponse.OutHmac.WriteTo(ref writer);

                        break;
                    }
                    case TpmEncapsulateResponse encapsulateResponse:
                    {
                        //sharedSecret (TPM2B_SHARED_SECRET) then ciphertext (TPM2B_KEM_CIPHERTEXT), in Table
                        //61's order; each structure writes its own size prefix and body.
                        encapsulateResponse.SharedSecret.WriteTo(ref writer);
                        encapsulateResponse.Ciphertext.WriteTo(ref writer);

                        break;
                    }
                    case TpmDecapsulateResponse decapsulateResponse:
                    {
                        //sharedSecret (TPM2B_SHARED_SECRET): Table 63's single response parameter.
                        decapsulateResponse.SharedSecret.WriteTo(ref writer);

                        break;
                    }
                    case TpmReadClockResponse readClockResponse:
                    {
                        //currentTime (TPMS_TIME_INFO): fixed layout, no TPM2B wrapping.
                        readClockResponse.CurrentTime.WriteTo(ref writer);

                        break;
                    }
                    case TpmDigestValuesResponse digestValuesResponse:
                    {
                        //digests / results (TPML_DIGEST_VALUES): the structure writes its count and each tagged
                        //digest (Tables 133 and 96 share the shape).
                        digestValuesResponse.Digests.WriteTo(ref writer);

                        break;
                    }
                    case TpmPcrReadResponse pcrReadResponse:
                    {
                        //pcrUpdateCounter (UINT32): the TPM-wide PCR-change count the state carried in — moved by
                        //every extend or reset of a counted register, by TPM2_Startup(), and by TPM2_Clear().
                        writer.WriteUInt32(pcrReadResponse.PcrUpdateCounter);

                        //pcrSelectionOut (TPML_PCR_SELECTION): the structure re-marshals itself, reproducing the
                        //octets it was parsed from — the simulator returns every selected register in one read.
                        pcrReadResponse.PcrSelection.WriteTo(ref writer);

                        //pcrValues (TPML_DIGEST): count then each register value as a TPM2B_DIGEST, in ascending
                        //PCR-index order.
                        writer.WriteUInt32((uint)pcrReadResponse.PcrValues.Length);
                        for(int i = 0; i < pcrReadResponse.PcrValues.Length; i++)
                        {
                            writer.WriteTpm2b(pcrReadResponse.PcrValues[i].Span);
                        }

                        break;
                    }
                    case TpmQuoteResponse quoteResponse:
                    {
                        //quoted (TPM2B_ATTEST) then signature (TPMT_SIGNATURE): each structure writes itself.
                        quoteResponse.Quoted.WriteTo(ref writer);
                        quoteResponse.Signature.WriteTo(ref writer);

                        break;
                    }
                    case TpmStartAuthSessionResponse startAuthSessionResponse:
                    {
                        //sessionHandle (the response handle area).
                        writer.WriteUInt32(startAuthSessionResponse.SessionHandle.Value);

                        //nonceTPM (TPM2B_NONCE): the session's real, retained nonce (TPM 2.0 Library Part 3, clause
                        //11.1) for every session kind — a bound HMAC session's session-key KDFa consumed it, and a
                        //policy/trial session's TPM2_PolicySigned() aHash later binds to it (Part 3, clause 23.3),
                        //so neither can be a fixed placeholder.
                        startAuthSessionResponse.NonceTpm.WriteTo(ref writer);

                        break;
                    }
                    case TpmPolicyGetDigestResponse policyGetDigestResponse:
                    {
                        //policyDigest (TPM2B_DIGEST): the session's accumulated policyDigest, copied out of the
                        //carrier the still-live session owns — framing borrows it and never releases it.
                        policyGetDigestResponse.PolicyDigest.WriteTo(ref writer);

                        break;
                    }
                    case TpmPolicySecretResponse policySecretResponse:
                    {
                        WriteAuthTicketResponse(
                            ref writer, (ushort)TpmStConstants.TPM_ST_AUTH_SECRET, policySecretResponse.Timeout,
                            policySecretResponse.Hierarchy.Value, policySecretResponse.TicketDigest);

                        break;
                    }
                    case TpmPolicySignedResponse policySignedResponse:
                    {
                        WriteAuthTicketResponse(
                            ref writer, (ushort)TpmStConstants.TPM_ST_AUTH_SIGNED, policySignedResponse.Timeout,
                            policySignedResponse.Hierarchy.Value, policySignedResponse.TicketDigest);

                        break;
                    }
                    case TpmMakeCredentialResponse makeCredentialResponse:
                    {
                        //credentialBlob (TPM2B_ID_OBJECT): the integrity-protected, encrypted credential.
                        makeCredentialResponse.CredentialBlob.WriteTo(ref writer);

                        //secret (TPM2B_ENCRYPTED_SECRET): the seed transport (the marshaled ephemeral public point).
                        makeCredentialResponse.Secret.WriteTo(ref writer);

                        break;
                    }
                    case TpmActivateCredentialResponse activateCredentialResponse:
                    {
                        //certInfo (TPM2B_DIGEST): the recovered credential secret.
                        activateCredentialResponse.CertInfo.WriteTo(ref writer);

                        break;
                    }
                    default:
                    {
                        break;
                    }
                }

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            randomBuffer?.Dispose();
            capabilityData?.Dispose();
            createdPublic?.Dispose();
            createdCreationData?.Dispose();
            createdCreationHash?.Dispose();
            createdCreationTicket?.Dispose();
            createdName?.Dispose();
            signatureValue?.Dispose();
            sealedPrivate?.Dispose();
            sealedPublic?.Dispose();
            sealedCreationData?.Dispose();
            sealedCreationHash?.Dispose();
            sealedCreationTicket?.Dispose();
            loadedName?.Dispose();
            contextSaveContext?.Dispose();
            nvReadPublicArea?.Dispose();
            nvReadPublicName?.Dispose();
            certifyInfoBuffer?.Dispose();
            certifySignature?.Dispose();
            certifyCreationInfoBuffer?.Dispose();
            certifyCreationSignature?.Dispose();
            timeInfoBuffer?.Dispose();
            timeSignature?.Dispose();
            sessionAuditInfoBuffer?.Dispose();
            sessionAuditSignature?.Dispose();
            nvCertifyInfoBuffer?.Dispose();
            nvCertifySignature?.Dispose();
            verifySignatureValidation?.Dispose();
            verifyDigestSignatureValidation?.Dispose();
            verifySequenceCompleteValidation?.Dispose();
            digestResult?.Dispose();
            digestValidation?.Dispose();
            hmacOutHmac?.Dispose();
            encapsulateSharedSecret?.Dispose();
            encapsulateCiphertext?.Dispose();
            decapsulateSharedSecret?.Dispose();
            policySecretTimeout?.Dispose();
            policySecretTicketDigest?.Dispose();
            policySignedTimeout?.Dispose();
            policySignedTicketDigest?.Dispose();
            pcrReadSelection?.Dispose();
            eventDigests?.Dispose();
            quotedBuffer?.Dispose();
            quoteSignature?.Dispose();
            credentialBlobBuffer?.Dispose();
            credentialSecretBuffer?.Dispose();
            duplicateIntent?.Duplicate.Dispose();
            duplicateIntent?.OutSymSeed.Dispose();
            importIntent?.OutPrivate.Dispose();
            objectChangeAuthIntent?.OutPrivate.Dispose();
            rsaEncryptIntent?.OutData.Dispose();

            //The recovered plaintext is confidential: zeroed before the rental returns to the pool.
            rsaDecryptIntent?.Message.Clear();
            rsaDecryptIntent?.Message.Dispose();
            startedSessionNonce?.Dispose();

            //The recovered credential secret is confidential: releasing its carrier returns the pinned segment to
            //the pool, which zeroes every segment it takes back, so the framed octets do not outlive the response.
            activatedCredential?.CertInfo.Dispose();
        }

        //The serialized size of a TPML_DIGEST (UINT32 count + each value as a TPM2B_DIGEST): the pcrValues member
        //of a TPM2_PCR_Read() response.
        static int PcrValuesSerializedSize(ImmutableArray<ReadOnlyMemory<byte>> values)
        {
            int size = sizeof(uint);
            for(int i = 0; i < values.Length; i++)
            {
                size += sizeof(ushort) + values[i].Length;
            }

            return size;
        }
    }

    /// <summary>
    /// Frames a session-authorized TPM2_PolicySecret() response (TPM 2.0 Library Part 3, clause 23.4).
    /// </summary>
    /// <remarks>
    /// A TPM_ST_SESSIONS-tagged, one-session-entry response: after the header come parameterSize and the framed
    /// TPM2B_TIMEOUT ‖ TPMT_TK_AUTH bytes, then the response session area. The parameter-area and HMAC buffers
    /// are the terminal owners released here.
    /// </remarks>
    /// <param name="intent">The framed session response to serialize.</param>
    /// <param name="pool">The memory pool for the response buffer.</param>
    /// <returns>The serialized <see cref="TpmResponse"/> wrapped in a <see cref="TpmResult{T}"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializePolicySecretOverSessionResponse(TpmPolicySecretOverSessionResponse intent, BaseMemoryPool pool)
    {
        try
        {
            int nonceLength = intent.NonceTpm.Size;
            int authAreaSize =
                (sizeof(ushort) + nonceLength)          //nonceTPM (TPM2B_NONCE).
                + sizeof(byte)                          //sessionAttributes.
                + intent.Hmac.SerializedSize;           //hmac (TPM2B).

            //parameterSize (UINT32) + the framed timeout/ticket parameter area + the response session area.
            int parameterSize = intent.ParameterArea.Length;
            int total = TpmHeader.HeaderSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                //Header carries the sessions tag so the caller parses the trailing response session area.
                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                //parameterSize then the already-framed TPM2B_TIMEOUT ‖ TPMT_TK_AUTH bytes verbatim.
                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(intent.ParameterArea.Span);

                //Response session area: nonceTPM, sessionAttributes (echoed and HMAC'd identically), hmac.
                intent.NonceTpm.WriteTo(ref writer);
                writer.WriteByte((byte)intent.SessionAttributes);
                intent.Hmac.WriteTo(ref writer);

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            intent.ParameterArea.Dispose();
            intent.NonceTpm.Dispose();
            intent.Hmac.Dispose();
        }
    }

    /// <summary>
    /// Frames a session-authorized command's response for the commands whose authorization area carries exactly
    /// one session: the NV family (<c>TPM2_NV_Read()</c>, <c>TPM2_NV_Write()</c>, <c>TPM2_NV_DefineSpace()</c>,
    /// <c>TPM2_NV_UndefineSpace()</c>) and the parameter-free hierarchy and provisioning commands
    /// (<c>TPM2_Clear()</c>, <c>TPM2_ClearControl()</c>, <c>TPM2_HierarchyControl()</c>,
    /// <c>TPM2_SetPrimaryPolicy()</c>, and <c>TPM2_NV_GlobalWriteLock()</c>) (TPM 2.0 Library Part 1, clause
    /// 15.6.1).
    /// </summary>
    /// <remarks>
    /// The same TPM_ST_SESSIONS-tagged, one-session-entry shape <c>SerializePolicySecretOverSessionResponse</c>
    /// frames, generalized over an empty-or-populated parameter area (empty for Write/DefineSpace/UndefineSpace,
    /// the framed TPM2B_MAX_NV_BUFFER for Read). The parameter-area and HMAC buffers are the terminal owners
    /// released here.
    /// </remarks>
    /// <param name="intent">The framed session response to serialize.</param>
    /// <param name="pool">The memory pool for the response buffer.</param>
    /// <returns>The serialized <see cref="TpmResponse"/> wrapped in a <see cref="TpmResult{T}"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeNvSessionResponse(TpmNvSessionResponse intent, BaseMemoryPool pool)
    {
        try
        {
            int nonceLength = intent.NonceTpm.Size;
            int authAreaSize =
                (sizeof(ushort) + nonceLength)          //nonceTPM (TPM2B_NONCE).
                + sizeof(byte)                          //sessionAttributes.
                + intent.Hmac.SerializedSize;           //hmac (TPM2B).

            //parameterSize (UINT32) + the already-framed response parameter bytes + the response session area.
            int parameterSize = intent.ParameterArea.Length;
            int total = TpmHeader.HeaderSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                //Header carries the sessions tag so the caller parses the trailing response session area.
                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                //parameterSize then the already-framed response parameter bytes verbatim (zero-length for
                //Write/DefineSpace/UndefineSpace).
                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(intent.ParameterArea.Span);

                //Response session area: nonceTPM, sessionAttributes (echoed and HMAC'd identically), hmac.
                intent.NonceTpm.WriteTo(ref writer);
                writer.WriteByte((byte)intent.SessionAttributes);
                intent.Hmac.WriteTo(ref writer);

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            intent.ParameterArea.Dispose();
            intent.NonceTpm.Dispose();
            intent.Hmac.Dispose();
        }
    }

    /// <summary>
    /// Frames a session-authorized <c>TPM2_HMAC()</c> or <c>TPM2_HMAC_Start()</c> response (TPM 2.0 Library
    /// Part 1, clause 15.6.1): a <c>TPM_ST_SESSIONS</c>-tagged envelope, <c>TPM2_HMAC_Start()</c>'s
    /// <c>sequenceHandle</c> in the handle area (Part 3, Table 81), <c>parameterSize</c>, the already-framed parameter
    /// octets verbatim (<c>outHMAC</c> for <c>TPM2_HMAC()</c>, nothing for <c>TPM2_HMAC_Start()</c>), then the
    /// single authorizing session's entry — nonceTPM, the echoed attributes, and the response HMAC or the empty
    /// hmac Part 4 <c>BuildSingleResponseAuth</c> assigns a <c>TPM2_PolicyPassword()</c> session.
    /// </summary>
    /// <remarks>
    /// The parameter area, the framed nonce and the HMAC are released here, as the terminal owner; the entry's
    /// retained nonce is not this step's — the completing transition installed it on the durable session record.
    /// </remarks>
    /// <param name="responseCode">The command response code (success).</param>
    /// <param name="sequenceHandle">The new sequence's handle for <c>TPM2_HMAC_Start()</c>, or <see langword="null"/> for <c>TPM2_HMAC()</c>, which returns no handle.</param>
    /// <param name="parameterArea">The framed response parameter octets; disposed after framing.</param>
    /// <param name="entry">The session's framed response entry; its framed nonce and HMAC are disposed after framing.</param>
    /// <param name="pool">The memory pool for the response buffer.</param>
    /// <returns>The serialized <see cref="TpmResponse"/> wrapped in a <see cref="TpmResult{T}"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeKeyedHashOverSessionResponse(
        TpmRcConstants responseCode, TpmiDhObject? sequenceHandle, TpmParameterArea parameterArea, TpmHmacFramedSession entry, BaseMemoryPool pool)
    {
        try
        {
            int handleAreaSize = sequenceHandle is null ? 0 : sizeof(uint);
            int authAreaSize =
                entry.NewNonceTpm.SerializedSize     //nonceTPM (TPM2B_NONCE).
                + sizeof(byte)                       //sessionAttributes.
                + entry.Hmac.SerializedSize;         //hmac (TPM2B), empty where Part 4 frames it empty.

            int parameterSize = parameterArea.Length;
            int total = TpmHeader.HeaderSize + handleAreaSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)responseCode);
                header.WriteTo(ref writer);

                //The response handle area precedes parameterSize (Part 1, clause 15.6.1's response layout).
                if(sequenceHandle is { } handle)
                {
                    writer.WriteUInt32(handle.Value);
                }

                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(parameterArea.Span);

                entry.NewNonceTpm.WriteTo(ref writer);
                writer.WriteByte((byte)entry.SessionAttributes);
                entry.Hmac.WriteTo(ref writer);

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            parameterArea.Dispose();
            entry.NewNonceTpm.Dispose();
            entry.Hmac.Dispose();
        }
    }

    /// <summary>
    /// Frames an authValue rotation's response — <c>TPM2_NV_ChangeAuth()</c> or
    /// <c>TPM2_HierarchyChangeAuth()</c>: a <c>TPM_ST_SESSIONS</c>-tagged envelope with a zero-length parameter
    /// area — neither command returns parameters (TPM 2.0 Library Part 3, clause 31.15, Table 270 and clause
    /// 24.8, Table 206) — followed by one entry per command session, in command-session order (Part 1, clause 16.6).
    /// </summary>
    /// <remarks>
    /// The <c>parameterSize</c> field is still written, and still zero, because the envelope is
    /// session-tagged: a caller parses the response session area only after consuming that length prefix. Entry
    /// order matches the order the executor parsed and verified the command's sessions in, so a byte off in
    /// either entry fails the caller's own verification. A <c>TPM_RS_PW</c> slot's entry is the placeholder shape
    /// <see cref="SerializeCreateOverSessionsResponse"/> also frames — an empty nonceTPM, the echoed attributes,
    /// and an empty hmac — and still occupies its own wire position. Each real entry's HMAC buffer is the
    /// terminal owner released here; a placeholder owns none.
    /// </remarks>
    /// <param name="intent">The framed session entries to serialize.</param>
    /// <param name="pool">The memory pool for the response buffer.</param>
    /// <returns>The serialized <see cref="TpmResponse"/> wrapped in a <see cref="TpmResult{T}"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeNvChangeAuthResponse(TpmNvChangeAuthResponse intent, BaseMemoryPool pool)
    {
        try
        {
            int authAreaSize = 0;
            foreach(TpmNvChangeAuthFramedSessionEntry entry in intent.Entries)
            {
                authAreaSize +=
                    entry.NewNonceTpm.SerializedSize  //nonceTPM (TPM2B_NONCE), empty for a password slot.
                    + sizeof(byte)                               //sessionAttributes.
                    + (entry.Hmac?.SerializedSize ?? sizeof(ushort)); //hmac (TPM2B), empty for a password slot.
            }

            int total = TpmHeader.HeaderSize + sizeof(uint) + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                writer.WriteUInt32(0u);

                foreach(TpmNvChangeAuthFramedSessionEntry entry in intent.Entries)
                {
                    if(entry.Hmac is Tpm2bAuth entryHmac)
                    {
                        entry.NewNonceTpm.WriteTo(ref writer);
                        writer.WriteByte((byte)entry.SessionAttributes);
                        entryHmac.WriteTo(ref writer);

                        continue;
                    }

                    //A password slot's placeholder: an empty nonceTPM and an empty hmac, since a password
                    //authorization carries no session key to compute one with.
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                    writer.WriteByte((byte)entry.SessionAttributes);
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                }

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            foreach(TpmNvChangeAuthFramedSessionEntry entry in intent.Entries)
            {
                entry.NewNonceTpm.Dispose();
                entry.Hmac?.Dispose();
            }
        }
    }

    /// <summary>
    /// Frames a <c>TPM2_Unseal()</c> response over 0, 1, or 2 real sessions plus an optional leading policy
    /// placeholder entry (TPM 2.0 Library Part 3, clause 12.7; Part 1, clause 15.7).
    /// </summary>
    /// <remarks>
    /// Like the encrypt-attributed GetRandom response it is <c>TPM_ST_SESSIONS</c>-tagged, but its response
    /// session area carries one entry per command session, in order: after the header (Unseal has no response
    /// handles) come parameterSize (UINT32), the (possibly encrypted) outData (TPM2B_SENSITIVE_DATA), then the
    /// policy placeholder entry when present (a zero nonceTPM of its hash width + echoed sessionAttributes + an
    /// EMPTY hmac — a satisfied plain policy session carries no key, so the TPM returns a zero-length response
    /// HMAC for it, Part 1, clause 16.6), followed by every real session's entry (its rolled nonceTPM + echoed
    /// sessionAttributes + its own response hmac). The order matches the order the executor parses and verifies
    /// the sessions in, so a byte-off in any entry fails the caller's verification. The parameter-area and each
    /// entry's HMAC buffer are the terminal owners released here; the parameter area holds the recovered secret,
    /// encrypted when a session carries the encrypt attribute, so it is zeroed before disposal regardless.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeUnsealOverSessionsResponse(TpmUnsealOverSessionsResponse intent, BaseMemoryPool pool)
    {
        try
        {
            //Policy placeholder entry (present only when HasPolicyPlaceholder is set): a zero nonceTPM of the
            //policy hash width, the echoed attributes, and an empty hmac.
            int policyAuthSize = intent.HasPolicyPlaceholder
                ? (sizeof(ushort) + intent.PolicyNonceLength) + sizeof(byte) + sizeof(ushort)
                : 0;

            //One entry per real session: its rolled nonceTPM, the echoed attributes, and its own response HMAC.
            int realAuthSize = 0;
            foreach(TpmUnsealFramedSessionEntry entry in intent.Entries)
            {
                realAuthSize +=
                    entry.NewNonceTpm.SerializedSize //nonceTPM (TPM2B_NONCE).
                    + sizeof(byte)                              //sessionAttributes.
                    + entry.Hmac.SerializedSize;                //hmac (TPM2B).
            }

            int authAreaSize = policyAuthSize + realAuthSize;

            //parameterSize (UINT32) + the (possibly encrypted) parameter area + the response session area.
            int parameterSize = intent.ParameterArea.Length;
            int total = TpmHeader.HeaderSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                //Header carries the sessions tag so the caller parses the response session area (Part 1, clause 17).
                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                //parameterSize then the (possibly encrypted) outData (its TPM2B size field is the unprotected
                //count). Unseal returns no response handle, so the parameter area follows the header directly
                //(Part 3, clause 12.7).
                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(intent.ParameterArea.Span);

                //Response session area, in command-session order. The policy placeholder, when present, is always
                //session index 0 (a policy session can only ever be Unseal's first, primary-authorizing session).
                if(intent.HasPolicyPlaceholder)
                {
                    Span<byte> policyNonce = stackalloc byte[intent.PolicyNonceLength];
                    policyNonce.Clear();
                    writer.WriteTpm2b(policyNonce);
                    writer.WriteByte((byte)intent.PolicyAttributes);
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                }

                //Every real session's entry, in command-session order: its rolled nonceTPM (nonceNewer), echoed
                //attributes (HMAC'd identically), and its own response HMAC.
                foreach(TpmUnsealFramedSessionEntry entry in intent.Entries)
                {
                    entry.NewNonceTpm.WriteTo(ref writer);
                    writer.WriteByte((byte)entry.SessionAttributes);
                    entry.Hmac.WriteTo(ref writer);
                }

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            //Zero the recovered secret before returning the parameter-area buffer to the pool, matching the
            //clear-before-dispose discipline the executor uses for the decrypted response parameter.
            intent.ParameterArea.Memory.Span.Clear();
            intent.ParameterArea.Dispose();
            foreach(TpmUnsealFramedSessionEntry entry in intent.Entries)
            {
                entry.NewNonceTpm.Dispose();
                entry.Hmac.Dispose();
            }
        }
    }

    /// <summary>
    /// Frames a <c>TPM2_Create()</c> response over one or two sessions — the request-decrypt counterpart of
    /// <see cref="SerializeUnsealOverSessionsResponse"/>.
    /// </summary>
    /// <remarks>
    /// Like the Unseal response it is <c>TPM_ST_SESSIONS</c>-tagged with a trailing response session area, in
    /// command-session order: a <c>TPM_RS_PW</c> parent-auth session's placeholder entry (an EMPTY nonceTPM —
    /// unlike a policy placeholder's zero-VALUE, hash-width nonce, Part 1, clause 16.6.4 — plus an empty hmac)
    /// when HasPasswordPlaceholder is set, then every real session's entry (its rolled nonceTPM, echoed
    /// attributes, its own response HMAC). <c>TPM2_Create()</c> has no response handle, so parameterSize then
    /// the parameter area (outPrivate ‖ outPublic ‖ creationByProducts, never encrypted here) follow the header
    /// directly (Part 3, clause 12.1). The parameter-area and each entry's HMAC buffer are the terminal owners
    /// released here.
    /// </remarks>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeCreateOverSessionsResponse(TpmCreateOverSessionsResponse intent, BaseMemoryPool pool)
    {
        try
        {
            //Password placeholder entry (present only when HasPasswordPlaceholder is set): an EMPTY nonceTPM
            //(size 0, Part 1, clause 16.6.4 — unlike a policy session's zero-VALUE, hash-width nonce), the echoed
            //(forced continueSession) attributes, and an empty hmac.
            int passwordAuthSize = intent.HasPasswordPlaceholder
                ? sizeof(ushort) + sizeof(byte) + sizeof(ushort)
                : 0;

            int realAuthSize = 0;
            foreach(TpmCreateFramedSessionEntry entry in intent.Entries)
            {
                realAuthSize +=
                    entry.NewNonceTpm.SerializedSize
                    + sizeof(byte)
                    + entry.Hmac.SerializedSize;
            }

            int authAreaSize = passwordAuthSize + realAuthSize;

            int parameterSize = intent.ParameterArea.Length;
            int total = TpmHeader.HeaderSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(intent.ParameterArea.Span);

                //The password placeholder, when present, is always session index 0 (TPM_RS_PW can only ever be
                //TPM2_Create()'s first, parent-authorizing session).
                if(intent.HasPasswordPlaceholder)
                {
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                    writer.WriteByte((byte)intent.PasswordPlaceholderAttributes);
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                }

                foreach(TpmCreateFramedSessionEntry entry in intent.Entries)
                {
                    entry.NewNonceTpm.WriteTo(ref writer);
                    writer.WriteByte((byte)entry.SessionAttributes);
                    entry.Hmac.WriteTo(ref writer);
                }

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            intent.ParameterArea.Dispose();
            foreach(TpmCreateFramedSessionEntry entry in intent.Entries)
            {
                entry.NewNonceTpm.Dispose();
                entry.Hmac.Dispose();
            }
        }
    }

    /// <summary>
    /// Frames the response of a command whose authorization slots are independent of one another — an attest
    /// command (<c>TPM2_Certify()</c>, <c>TPM2_CertifyCreation()</c>, <c>TPM2_Quote()</c>, <c>TPM2_GetTime()</c>,
    /// <c>TPM2_NV_Certify()</c>) or a signing-family command (<c>TPM2_Sign()</c>, <c>TPM2_SignDigest()</c>,
    /// <c>TPM2_SequenceUpdate()</c>, <c>TPM2_SignSequenceComplete()</c>, <c>TPM2_VerifySequenceComplete()</c>) —
    /// over an authorization area carrying at least one real session (TPM 2.0 Library Part 3, Tables 90, 92, 94,
    /// 100, 255, 119, 123, 125, and 127; Part 1, clause 15.6.1).
    /// </summary>
    /// <remarks>
    /// The shape <see cref="SerializeCreateOverSessionsResponse"/> frames, with the placeholder decided per entry
    /// instead of by a single leading flag: each of these commands authorizes its handles independently, so a
    /// <c>TPM_RS_PW</c> slot can sit at any index. After the header — followed by a response handle (UINT32)
    /// when <see cref="TpmOverSessionsResponse.ResponseHandle"/> is set (TPM 2.0 Library Part 3, clause 4.3;
    /// none of the attest or signing family returns one, but a no-authorization command routed onto this same
    /// intent through <see cref="TpmLifecycleTransitions.ApplyPendingSessionFrame"/> may) — come parameterSize
    /// (UINT32), the framed parameter area — empty for <c>TPM2_SequenceUpdate()</c> — then one entry per command
    /// session in command-session order — a password slot's empty nonceTPM, echoed attributes, and empty hmac,
    /// or a real session's rolled nonceTPM, echoed attributes, and its own response hmac (the Empty Buffer under
    /// the No-HMAC-Authorization rule, Part 1, clause 16.6.16). The order matches the order the executor parsed
    /// and verified the sessions in, so a byte off in any entry fails the caller's own verification. The
    /// parameter-area and each real entry's HMAC buffer are the terminal owners released here.
    /// </remarks>
    /// <param name="intent">The framed response to serialize.</param>
    /// <param name="pool">The memory pool for the response buffer.</param>
    /// <returns>The serialized <see cref="TpmResponse"/> wrapped in a <see cref="TpmResult{T}"/>.</returns>
    [SuppressMessage("Reliability", "CA2000:Dispose objects before losing scope",
        Justification = "TpmResponse takes ownership of the rented buffer and is owned by the returned TpmResult, which the caller disposes.")]
    private static TpmResult<TpmResponse> SerializeOverSessionsResponse(TpmOverSessionsResponse intent, BaseMemoryPool pool)
    {
        try
        {
            int authAreaSize = 0;
            foreach(TpmFramedSessionEntry entry in intent.Entries)
            {
                authAreaSize +=
                    entry.NewNonceTpm.SerializedSize  //nonceTPM (TPM2B_NONCE), empty for a password slot.
                    + sizeof(byte)                               //sessionAttributes.
                    + (entry.Hmac?.SerializedSize ?? sizeof(ushort)); //hmac (TPM2B), empty for a password slot.
            }

            int parameterSize = intent.ParameterArea.Length;
            int responseHandleSize = intent.ResponseHandle is null ? 0 : sizeof(uint);
            int total = TpmHeader.HeaderSize + responseHandleSize + sizeof(uint) + parameterSize + authAreaSize;

            IMemoryOwner<byte> owner = pool.Rent(total);
            try
            {
                var writer = new TpmWriter(owner.Memory.Span[..total]);

                var header = new TpmHeader((ushort)TpmStConstants.TPM_ST_SESSIONS, (uint)total, (uint)intent.ResponseCode);
                header.WriteTo(ref writer);

                //The response handle area, when present, is written directly after the header and ahead of
                //parameterSize (TPM 2.0 Library Part 3, clause 4.3) — excluded from rpHash by construction,
                //since rpHash covers only ParameterArea (Part 1, clause 15.8).
                if(intent.ResponseHandle is TpmHandle responseHandle)
                {
                    writer.WriteUInt32(responseHandle.Value);
                }

                writer.WriteUInt32((uint)parameterSize);
                writer.WriteBytes(intent.ParameterArea.Span);

                foreach(TpmFramedSessionEntry entry in intent.Entries)
                {
                    if(entry.Hmac is Tpm2bAuth entryHmac)
                    {
                        entry.NewNonceTpm.WriteTo(ref writer);
                        writer.WriteByte((byte)entry.SessionAttributes);
                        entryHmac.WriteTo(ref writer);

                        continue;
                    }

                    //A password slot's placeholder: an empty nonceTPM and an empty hmac, since a password
                    //authorization carries no session key to compute one with.
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                    writer.WriteByte((byte)entry.SessionAttributes);
                    writer.WriteTpm2b(ReadOnlySpan<byte>.Empty);
                }

                return TpmResult<TpmResponse>.Success(new TpmResponse(owner, total));
            }
            catch
            {
                owner.Dispose();
                throw;
            }
        }
        finally
        {
            //Zeroed before release: this shared parameter area carries TPM2_RSA_Decrypt()'s recovered plaintext
            //when the framed intent is that command's session form. TpmParameterArea.Dispose() itself zeroes
            //the whole rental, so the explicit clear is defence in depth, harmless for every other command
            //framed through this generic serializer.
            intent.ParameterArea.Memory.Span.Clear();
            intent.ParameterArea.Dispose();
            foreach(TpmFramedSessionEntry entry in intent.Entries)
            {
                entry.NewNonceTpm.Dispose();
                entry.Hmac?.Dispose();
            }
        }
    }
}
